/// A question's answer, as its button: its words, what it does, its look, its keys.
#[derive(Clone, Debug, PartialEq)]
pub struct Answer {
    pub label: &'static str,
    pub action: Action,
    pub look: Look,
    pub keys: &'static [&'static str],
}

/// An answer's look: the way out (outlined), the default (filled), or a default that destroys
/// what cannot be brought back (red).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Look {
    Cancel,
    Primary,
    Destroys,
}

/// The quit question: these terminals would lose a running program.
#[derive(Clone, Debug, Default, PartialEq, Serialize)]
pub struct Confirm {
    pub running: Vec<Running>,
    /// Not the quit question: "Stop its agent and dismiss?" for this task, whose agent runs.
    pub dismiss: Option<TaskId>,
    /// Not the quit question: "Unlist this repository?" for the one at this path, which a live
    /// task works in. Nothing on disk changes either way.
    pub unlist: Option<String>,
    /// Not the quit question: "Close this workspace?" for this temporary one, whose terminals
    /// in `running` would end once its Undo runs out.
    pub close: Option<WorkbookId>,
    /// Not the quit question: "Stop "<title>" and put it away?" for this task, whose turn runs.
    pub later: Option<(TaskId, String)>,
    /// Not the quit question: "Close <title>? It has unsaved changes" for this owned app pane.
    pub edited: Option<PaneId>,
    /// Not the quit question: "Delete the worktree of <branch>?" for the linked one at this path.
    pub delete: Option<String>,
    /// The quit question's agents quitting stops, by their conversation's name (`quit_agents`).
    pub agents: Vec<String>,
    /// The quit question's drafts quitting loses (`Model::unsent`).
    pub unsent: Vec<quit::Unsent>,
}

impl Confirm {
    /// What a key does to the question. The user's: ↵, Q or ⌘Q quits; every other key or
    /// shortcut cancels, and does nothing else, e.g. ⌘W cancels and closes nothing. A socket
    /// client's: ↵ or Q quits and Esc cancels, so a test can answer; `None` for any other key,
    /// which is refused: a client's shortcut must not answer for the user.
    pub fn answer(key: &str, mods: Mods, origin: Origin) -> Option<Action> {
        let plain = mods == Mods::default();
        let cmd = mods == Mods { cmd: true, ..Mods::default() };
        match (key, origin) {
            ("enter" | "q", _) if plain => Some(Action::QuitConfirm),
            ("q", Origin::User) if cmd => Some(Action::QuitConfirm),
            ("escape", _) if plain => Some(Action::QuitCancel),
            (_, Origin::User) => Some(Action::QuitCancel),
            (_, Origin::Socket | Origin::System) => None,
        }
    }

    /// What a key does to "Stop "<task>" and put it away?": ↵ alone stops it (no Q, no ⌘Q: it is
    /// no quit); Esc, or any other key of the user's, keeps it running. A client's other key: `None`.
    pub fn answer_later(key: &str, mods: Mods, origin: Origin) -> Option<Action> {
        match (key, origin) {
            ("enter", _) if mods == Mods::default() => Some(Action::QuitConfirm),
            ("escape", _) if mods == Mods::default() => Some(Action::QuitCancel),
            (_, Origin::User) => Some(Action::QuitCancel),
            _ => None,
        }
    }

    /// What a key does to "Delete this worktree?": it cannot be undone, so the user's ⌘↵ deletes
    /// and ↵ alone does nothing (a ↵ meant for a terminal never deletes a folder); Esc, or any other
    /// key of theirs, keeps it. A client's: `None`, refused (`repos::DELETE_USERS`).
    pub fn answer_delete(key: &str, mods: Mods, origin: Origin) -> Option<Action> {
        match (key, origin) {
            ("enter", Origin::User) if mods == Mods { cmd: true, ..Mods::default() } => Some(Action::QuitConfirm),
            ("enter", Origin::User) if mods == Mods::default() => None,
            (_, Origin::User) => Some(Action::QuitCancel),
            _ => None,
        }
    }

    /// The question's two answers as its buttons, no first, yes last (right-most, the default).
    /// Each names its result; yes carries the keys that press it. Deleting a worktree cannot be
    /// undone: its yes is red and asks ⌘↵.
    pub fn answers(&self) -> [Answer; 2] {
        let (no, yes) = match () {
            _ if self.dismiss.is_some() => ("Cancel", "Stop and dismiss"),
            _ if self.later.is_some() => ("Keep running", "Stop, resume later"),
            _ if self.edited.is_some() => ("Cancel", "Close"),
            _ if self.unlist.is_some() => ("Cancel", "Unlist"),
            _ if self.close.is_some() => ("Cancel", "Close workspace"),
            _ if self.delete.is_some() => ("Keep it", "Delete worktree"),
            _ => ("Cancel", "Quit"),
        };
        let (look, keys): (Look, &'static [&'static str]) = match self.delete {
            Some(_) => (Look::Destroys, &["⌘", "↵"]),
            None => (Look::Primary, &["↵"]),
        };
        [
            Answer { label: no, action: Action::QuitCancel, look: Look::Cancel, keys: &[] },
            Answer { label: yes, action: Action::QuitConfirm, look, keys },
        ]
    }

    /// The question's title, e.g. "Quit ottospace?".
    pub fn title(&self) -> String {
        if self.dismiss.is_some() {
            return "Stop its agent and dismiss?".into();
        }
        if let Some((_, title)) = &self.later {
            return format!("Stop \"{title}\" and put it away?");
        }
        if self.unlist.is_some() {
            return "Unlist this repository?".into();
        }
        if self.close.is_some() {
            return "Close this workspace?".into();
        }
        if self.delete.is_some() {
            return "Delete this worktree?".into();
        }
        "Quit ottospace?".into()
    }

    /// What quitting ends, one line each: a terminal ("pane 2 · cargo", "pane 3 · sleep
    /// (background)"), then an agent ("agent · Fix the login"). At most 5, then "and 2 more".
    pub fn lines(&self) -> Vec<String> {
        let line = |r: &Running| match (&r.program, r.background) {
            (Some(program), true) => format!("pane {} · {program} (background)", r.pane),
            (Some(program), false) => format!("pane {} · {program}", r.pane),
            (None, true) => format!("pane {} · (background)", r.pane),
            (None, false) => format!("pane {}", r.pane),
        };
        let agents = self.agents.iter().map(|title| format!("agent · {title}"));
        let all: Vec<String> = self.running.iter().map(line).chain(agents).collect();
        let mut lines: Vec<String> = all.iter().take(5).cloned().collect();
        if all.len() > 5 {
            lines.push(format!("and {} more", all.len() - 5));
        }
        lines
    }
}

