/// The most characters the picker's filter holds: no app's name is longer, and a huge paste
/// is not shaped again every frame.
pub const MAX_FILTER: usize = 200;

/// Something the picker can put in a new pane.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum PickItem {
    Terminal,
    /// "File…": the open panel, then the file in a viewer.
    File,
    /// A running app, by name. Choosing it lists its windows: the picker's second step.
    App {
        name: String,
    },
    /// The second step's first row: a new window of `app`, owned (it closes with its pane).
    NewWindow {
        app: String,
        bundle: Option<String>,
        /// It has a menu item titled "New Window" (`new_window::MENU_ITEM`).
        #[serde(default)]
        menu_item: bool,
    },
    /// The second step: one of `app`'s windows, by its window-server id; its title drawn, never
    /// in the state. `pane`: the pane that held it when listed.
    Window {
        app: String,
        window: u32,
        #[serde(skip)]
        title: String,
        pane: Option<PaneId>,
        /// What tells it from a window of the same title, never in the state.
        #[serde(skip)]
        frame: crate::ax::Frame,
        #[serde(skip)]
        subrole: String,
    },
    /// An installed app that is not running, by where it is. Choosing it starts it.
    Closed {
        name: String,
        path: String,
    },
    /// In the transcript's picker: an app that can play sound, and one of its windows (its
    /// title drawn, never in the state). Choosing it starts a transcript of the app.
    Sound {
        #[serde(skip)]
        pid: i32,
        name: String,
        /// The window's title and id.
        #[serde(skip)]
        window: Option<(String, Option<u32>)>,
        playing: bool,
    },
}

impl PickItem {
    /// What the filter matches: the label, and a sound app's window as its row shows it.
    fn filter_text(&self) -> String {
        match self {
            PickItem::Sound { name, window: Some((window, _)), .. } => format!("{name} · {window}"),
            _ => self.label().to_string(),
        }
    }

    pub fn label(&self) -> &str {
        match self {
            PickItem::Terminal => "Terminal",
            PickItem::File => "File…",
            PickItem::NewWindow { .. } => "New window",
            PickItem::App { name } | PickItem::Closed { name, .. } | PickItem::Sound { name, .. } => name,
            PickItem::Window { title, .. } if title.is_empty() => "Untitled window",
            PickItem::Window { title, .. } => title,
        }
    }
}

