    /// What reaches a native agent: the user's alone, on any ground.
    fn talks(action: &Action) -> bool {
        matches!(
            action,
            Action::TalkSend
                | Action::TalkAnswer { .. }
                | Action::TalkExpand { .. }
                | Action::TalkAsk { .. }
                | Action::TalkDenyNote
                | Action::TalkEscape
                | Action::TalkInterrupt
                | Action::TalkView { .. }
        )
    }

    /// A transcript's start, pause, resume or stop: the user's alone. What it heard: the shell's.
    fn listen_refused(action: &Action, origin: Origin) -> Option<&'static str> {
        match action {
            Action::ListenStart { .. }
            | Action::ListenToggle { .. }
            | Action::ListenPause { .. }
            | Action::ListenResume { .. }
            | Action::ListenStop { .. }
            | Action::ListenPicker { .. } => Some(listen::USERS_ALONE),
            Action::ListenFixture
            | Action::ListenAvailable { .. }
            | Action::ListenBegan { .. }
            | Action::ListenFailed { .. }
            | Action::ListenHeard { .. }
            | Action::ListenWindows { .. }
            | Action::ListenEnded { .. }
            | Action::ListenPast { .. }
                if origin == Origin::Socket =>
            {
                Some(listen::SHELLS_ALONE)
            }
            _ => None,
        }
    }

    /// Agent mode: a level or the menu, the user's alone; a record of an app's use, the shell's.
    fn agent_refused(action: &Action, origin: Origin) -> Option<&'static str> {
        match action {
            Action::AgentLevel { .. }
            | Action::AgentMenu { .. }
            | Action::AgentMenuMove { .. }
            | Action::AgentMenuChoose { .. }
            | Action::AgentMenuClose
            | Action::AgentOfferAccept { .. }
                if origin != Origin::User =>
            {
                Some(crate::agent_mode::USERS_ALONE)
            }
            Action::AppUsed { .. } if origin == Origin::Socket => Some(crate::agent_mode::SHELLS_ALONE),
            _ => None,
        }
    }

    /// An offered window put in a pane or waved away: the user's alone. A new window: the shell's.
    fn offer_refused(action: &Action, origin: Origin) -> Option<&'static str> {
        match action {
            Action::OfferAccept { .. } | Action::OfferDismiss { .. } | Action::OfferList { .. } => {
                Some(offers::USERS_ALONE)
            }
            Action::WindowOffered { .. } | Action::OfferGone { .. } if origin == Origin::Socket => {
                Some(offers::SHELLS_ALONE)
            }
            _ => None,
        }
    }

    /// A slot made, filled or cleared: the user's alone. What a look found: the shell's.
    fn slot_refused(action: &Action, origin: Origin) -> Option<&'static str> {
        match action {
            Action::SlotMake { .. }
            | Action::SlotDialogOpen { .. }
            | Action::SlotDialogSet { .. }
            | Action::SlotDialogClose
            | Action::SlotDialogKeep
            | Action::SlotClear { .. }
            | Action::SlotAccept { .. }
            | Action::SlotDecline { .. }
            | Action::SlotNext { .. }
            | Action::SlotLookAgain { .. }
            | Action::SlotGiveBack { .. } => Some(crate::slot::USERS_ALONE),
            Action::SlotWindows { .. }
            | Action::SlotHosted { .. }
            | Action::SlotTick { .. }
            | Action::WindowGone { .. }
            | Action::Adopt { seen: Some(_), .. }
                if origin == Origin::Socket =>
            {
                Some(crate::slot::SHELLS_ALONE)
            }
            _ => None,
        }
    }

    /// The clone dialog: the user's alone; a clone's news, the shell's.
    fn clone_refused(action: &Action, origin: Origin) -> Option<&'static str> {
        match action {
            Action::RepoPickFolder
            | Action::CloneOpen
            | Action::CloneMove { .. }
            | Action::CloneChoose { .. }
            | Action::CloneClose { .. } => Some(crate::clone::USERS_ALONE),
            Action::CloneProgress { .. } | Action::CloneDone { .. } if origin == Origin::Socket => {
                Some(crate::clone::SHELLS_ALONE)
            }
            _ => None,
        }
    }

    /// A pin, a hide or their undo: refused from all but the user on its own ground.
    fn writes_settings(action: &Action) -> bool {
        let apps =
            matches!(action, Action::AppPin { .. } | Action::AppHide { .. } | Action::AppsUndo | Action::ListPin);
        apps || matches!(action, Action::RepoAdd { .. } | Action::RepoRemove { .. })
    }

    /// A workbook saved, opened, renamed, deleted or put back: the user's alone, as those are.
    fn of_workbooks(action: &Action) -> bool {
        matches!(
            action,
            Action::WorkbookSave { .. }
                | Action::WorkbookNew { .. }
                | Action::WorkbookAddTab { .. }
                | Action::WorkbookSaveAll { .. }
                | Action::WorkbookOpen { .. }
                | Action::WorkbookEdit { .. }
                | Action::WorkbookRemove { .. }
                | Action::WorkbookKeep { .. }
                | Action::WorkbookUndo
                | Action::WorkbookReopen { .. }
                | Action::RowMenu { .. }
                | Action::RowMenuMove { .. }
                | Action::RowMenuChoose { .. }
                | Action::RowMenuClose
                | Action::SpaceOpen { space: Owner::Workbook { .. } }
        )
    }

    /// A move in the palette: the user's alone. Opening it takes the keyboard, so a mode in its
    /// way says its own reason first.
    fn in_palette(action: &Action) -> bool {
        matches!(
            action,
            Action::PaletteMove { .. }
                | Action::PaletteChoose { .. }
                | Action::ClosePalette
                | Action::GoToDrill
                | Action::GoToBack
        ) || matches!(
            action,
            Action::InspectorOpen { .. }
                | Action::InspectorClose
                | Action::InspectorFold { .. }
                | Action::InspectorSelect { .. }
                | Action::InspectorMove { .. }
                | Action::InspectorFilter { on: false }
        )
    }

    #[test]
    fn the_inspector_takes_the_drawers_place_and_gives_it_back() {
        let mut m = Model::default();
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        // Not over the new-task box while it has the keyboard: the box would type unseen.
        m.update(Action::OpenCompose { text: "fix".into() });
        m.update(Action::InspectorOpen { pane: 1, app: "A".into() });
        assert!(m.inspector.is_none());
        m.update(Action::CloseCompose);
        // A drawer that closes under it leaves it there; what the drawer is asked to show next takes the place back.
        m.update(Action::InspectorOpen { pane: 1, app: "A".into() });
        assert!(m.inspector.is_some());
        m.update(Action::OpenCompose { text: "fix".into() });
        assert_eq!((m.inspector.is_none(), m.compose_line().cloned()), (true, Some("fix".into())));
    }

    /// Go-to's rows as listed for its query: each name.
    fn goto_rows(m: &Model) -> Vec<String> {
        let Some(palette) = &m.palette else { return Vec::new() };
        let Some(goto) = &palette.goto else { return Vec::new() };
        match &goto.drill {
            Some(_) => goto.rows.clone(),
            None => goto.place_matches(palette.query.text()).into_iter().map(|(_, row)| row.name.clone()).collect(),
        }
    }

    fn go_type(m: &mut Model, text: &str) -> Vec<Effect> {
        m.update(Action::FieldEdit { edit: Edit::Insert(text.into()) })
    }

    /// Two workspaces of the Repos list's checkouts, `app` on show, and a task that needs the user.
    fn goto_places() -> Model {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: listed() });
        m.update(Action::RepoClick { path: "/code/app-2".into(), axis: Right });
        m.update(Action::RepoClick { path: "/code/app".into(), axis: Right });
        let assign = Assign::default();
        m.update(Action::TaskAdd { title: "fix login".into(), priority: 2, state: State::NeedsYou, tab: None, assign });
        m
    }

    #[test]
    fn go_to_lists_places_the_last_used_first_the_current_last_for_the_user_alone() {
        let mut m = goto_places();
        assert!(m.update(Action::PaletteGoTo.sent_by(Origin::Socket)).is_empty());
        assert!(m.palette.is_none());
        m.update(Action::PaletteGoTo);
        assert_eq!(m.mode(), Mode::Palette);
        // app-2's workspace was selected before; then the rest in their sections' order; the
        // workspace on show and its checkout last.
        assert_eq!(goto_rows(&m), ["app-2", "app-2", "fix login", "app", "app"]);
        go_type(&mut m, "fix");
        assert_eq!(goto_rows(&m), ["fix login"]);
        // A client types nothing, moves nothing, chooses nothing.
        m.update(Action::GoToDrill.sent_by(Origin::Socket));
        assert!(m.update(Action::PaletteChoose { index: None }.sent_by(Origin::Socket)).is_empty());
        assert!(m.palette.is_some());
        // ↵: as the task's row does, its conversation.
        m.update(Action::PaletteChoose { index: None });
        assert_eq!(
            (m.palette.is_none(), m.talk.as_ref().map(|talk| talk.task.clone())),
            (true, Some(Subject::Task(1)))
        );
    }

