    #[test]
    fn a_place_that_goes_leaves_go_to_and_ends_a_drill_into_it() {
        let mut m = goto_places();
        m.update(Action::PaletteGoTo);
        go_type(&mut m, "app-2");
        // Its checkout's row, under its workspace's.
        m.update(Action::PaletteMove { delta: 1 });
        m.update(Action::GoToDrill);
        // The worktree is no longer listed: it leaves the list, and the drill ends.
        let only = Repo { worktrees: vec![], ..listed().remove(0) };
        m.update(Action::SetRepos { repos: vec![only] });
        let palette = m.palette.as_ref().expect("open");
        assert_eq!((palette.view(), palette.query.text()), (commands::View::Places, "app-2"));
        assert!(palette.goto.as_ref().is_some_and(|goto| {
            goto.places.iter().all(|row| row.place != crate::goto::Place::Checkout("/code/app-2".into()))
        }));
    }

    #[test]
    fn the_palette_runs_the_chosen_command_for_the_user_alone() {
        let mut m = Model::default();
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        // A client opens nothing, and the user's ⌘⇧P opens it.
        assert!(m.update(Action::PaletteOpen.sent_by(Origin::Socket)).is_empty());
        assert_eq!(m.mode(), Mode::Normal);
        m.update(Action::PaletteOpen);
        assert_eq!((m.mode(), m.field().map(|(of, _)| of)), (Mode::Palette, Some("palette")));
        // A client types nothing in it and chooses nothing.
        m.update(Action::FieldEdit { edit: Edit::Insert("quit".into()) }.sent_by(Origin::Socket));
        assert!(m.update(Action::PaletteChoose { index: None }.sent_by(Origin::Socket)).is_empty());
        assert_eq!(m.palette.as_ref().map(|p| p.query.text().to_string()), Some(String::new()));
        // Behind it, pane actions wait, and no other box opens.
        assert_eq!(m.waits(&Action::Close { pane: None }), Some(commands::PALETTE_OPEN));
        m.update(Action::OpenPicker { axis: Right, new_tab: false, items: vec![PickItem::Terminal] });
        m.update(Action::OpenCompose { text: String::new() });
        assert_eq!((m.picker.is_none(), m.compose.is_none(), m.panes.len()), (true, true, 1));
        // Typing narrows it to its first match; ↓ wraps; ↵ runs the highlighted one and closes it.
        m.update(Action::FieldEdit { edit: Edit::Insert("next".into()) });
        let rows = m.palette.as_ref().map(Palette::matches).unwrap_or_default();
        assert_eq!(rows[..2], [Command::FocusNext, Command::NextTab]);
        m.update(Action::PaletteMove { delta: rows.len() as i32 + 1 });
        assert_eq!(m.update(Action::PaletteChoose { index: None }), vec![Effect::Run { command: Command::NextTab }]);
        assert_eq!((m.palette.is_none(), m.mode()), (true, Mode::Normal));
        // Nothing matched: ↵ keeps it open, so the query can be fixed.
        m.update(Action::PaletteOpen);
        m.update(Action::FieldEdit { edit: Edit::Insert("zzz".into()) });
        assert!(m.update(Action::PaletteChoose { index: None }).is_empty());
        assert!(m.palette.is_some());
        // Over the conversation: the palette takes the keys, and closing it gives them back.
        m.update(Action::ClosePalette);
        m.update(Action::TaskAdd {
            title: "t".into(),
            priority: 3,
            state: State::Running,
            tab: None,
            assign: Assign::default(),
        });
        let id = m.tasks.list[0].id;
        m.update(Action::SpaceOpen { space: Owner::Task { id } });
        (m.talk, m.agents) =
            (Some(talk::Talk { task: Subject::Task(id), open: true, keys: true }), vec![Subject::Task(id)]);
        assert_eq!(m.mode(), Mode::Talk);
        m.update(Action::PaletteOpen);
        assert_eq!(m.mode(), Mode::Palette);
        m.update(Action::ClosePalette);
        assert_eq!(m.mode(), Mode::Talk);
        // Not over the key reference.
        m.update(Action::ClosePalette);
        m.update(Action::ToggleKeys);
        m.update(Action::PaletteOpen);
        assert!(m.palette.is_none());
    }

    fn action_is_palettes(action: &Action) -> bool {
        matches!(
            action,
            Action::PaletteMove { .. }
                | Action::PaletteChoose { .. }
                | Action::ClosePalette
                | Action::GoToDrill
                | Action::GoToBack
        )
    }

    /// Every action from every origin. The origin decides, not the action: only the user's own
    /// move ends sneak mode, and only the user takes the keyboard from under its labels.
    #[test]
    fn only_the_user_dismisses_a_notice_and_a_fixed_settings_line_shows_again() {
        use crate::notice::{Kind, Notice};
        let dismiss = |notice, text: &str| Action::NoticeDismiss { notice, text: text.into() };
        let mut m = Model::default();
        m.update(Action::SettingsRead { text: "{,}".into(), written: false }.sent_by(Origin::System));
        let line = m.settings_line().expect("a problem");
        let said = Notice { kind: Kind::SettingsProblem, text: line.clone() };
        // A client's and the system's are refused: nothing hidden, no effect.
        for origin in [Origin::Socket, Origin::System] {
            let sent = dismiss(Kind::SettingsProblem, &line);
            assert_eq!(m.refusal(&sent, origin), Some(crate::notice::USERS_ALONE));
            assert_eq!((m.update(sent.sent_by(origin)), m.notice_hidden.len()), (vec![], 0));
        }
        // The user's: one that stays until fixed is remembered, one of a kind; it ends no mode.
        m.update(Action::ToggleKeys);
        let gone = vec![Effect::NoticeDismissed { kind: Kind::SettingsProblem }];
        assert_eq!(m.update(dismiss(Kind::SettingsProblem, "old")), gone);
        assert_eq!(m.update(dismiss(Kind::SettingsProblem, &line)), gone);
        assert_eq!((&m.notice_hidden, m.keys), (&vec![said.clone()], true));
        assert_eq!(crate::notice::shown(std::slice::from_ref(&said), &m.notice_hidden), None);
        // One the shell holds in a slot is not remembered: said again, it shows again.
        assert_eq!(m.update(dismiss(Kind::Failed, "x")), [Effect::NoticeDismissed { kind: Kind::Failed }]);
        assert_eq!(m.notice_hidden, [said.clone()]);
        // The same problem read again stays dismissed; fixed, then wrong again, it shows.
        m.update(Action::SettingsRead { text: "{,}".into(), written: false }.sent_by(Origin::System));
        assert_eq!(m.notice_hidden, [said]);
        m.update(Action::SettingsRead { text: "{}".into(), written: false }.sent_by(Origin::System));
        assert_eq!((m.notice_hidden.len(), m.settings_line()), (0, None));
    }

    #[test]
    fn only_the_users_own_move_ends_sneak_whatever_the_action() {
        for action in &samples() {
            for origin in [Origin::User, Origin::Socket, Origin::System] {
                let mut m = Model::default();
                m.update(Action::Split { axis: Right, kind: Kind::Empty });
                sneak(&mut m, 3);
                let refused = match action {
                    _ if origin == Origin::User => None,
                    _ if writes_settings(action) => Some(apps::USERS_ALONE),
                    _ if of_workbooks(action) => Some(workbook::USERS_ALONE),
                    _ if listen_refused(action, origin).is_some() => listen_refused(action, origin),
                    _ if agent_refused(action, origin).is_some() => agent_refused(action, origin),
                    _ if slot_refused(action, origin).is_some() => slot_refused(action, origin),
                    _ if offer_refused(action, origin).is_some() => offer_refused(action, origin),
                    _ if clone_refused(action, origin).is_some() => clone_refused(action, origin),
                    Action::TaskTalk { .. }
                    | Action::TaskCard { .. }
                    | Action::SessionOpen { .. }
                    | Action::TalkStart
                    | Action::TaskStop { .. } => Some(agents::USERS_ALONE),
                    Action::TabPlace { .. } => Some(TABS_USERS),
                    Action::DividerDrag { .. } | Action::DividerHold { .. } | Action::DividerEven { .. } => {
                        Some(DIVIDER_USERS)
                    }
                    Action::ReorderOver { .. } | Action::ReorderDrop | Action::ReorderCancel => {
                        Some(reorder::REORDER_USERS)
                    }
                    Action::TalkFront { .. } | Action::TalkCycle { .. } => Some(spaces::FRONT_USERS),
                    Action::ComposeHere => Some(spaces::PIN_USERS),
                    Action::RailSelect { .. } | Action::ListenShow { .. } | Action::ListenOpenPast { .. } => {
                        Some(rail::RAIL_USERS)
                    }
                    Action::CalendarJoin { .. } | Action::CalendarDismiss { .. } => Some(calendar::USERS_ALONE),
                    Action::ProjectOpen { .. } => Some(crate::projects::USERS_ALONE),
                    Action::CalendarRetry => Some(calendar::USERS_RETRY),
                    Action::CopyPath { .. } => Some(crate::status_bar::USERS_COPY),
                    _ if talks(action) => Some(chat::USERS_ALONE),
                    Action::BtwOpen
                    | Action::BtwKeys { .. }
                    | Action::BtwAsk
                    | Action::BtwUse { .. }
                    | Action::BtwClose => Some(btw::USERS_ALONE),
                    Action::BtwAnswered { .. } | Action::BtwFailed { .. } if origin == Origin::Socket => {
                        Some(btw::RUNNERS_ALONE)
                    }
                    Action::DialToggle => Some(chat::DIAL_USERS),
                    Action::FillDisplay => Some(crate::fill::USERS_ALONE),
                    Action::TabOut { .. } | Action::TabIn { .. } | Action::KeyWindow { .. } => {
                        Some(displays::USERS_ALONE)
                    }
                    Action::SetDisplays { .. } if origin == Origin::Socket => Some(displays::SHELLS_ALONE),
                    Action::AgentEvents { .. } if origin == Origin::Socket => Some(chat::RUNNERS_ALONE),
                    _ if in_palette(action) && action_is_palettes(action) => Some(commands::USERS_ALONE),
                    _ if in_palette(action) => Some(inspect::USERS_ALONE),
                    Action::InspectorRead { .. } | Action::InspectorFailed { .. } if origin == Origin::Socket => {
                        Some(inspect::USERS_ALONE)
                    }
                    Action::GoToFiles { .. } if origin == Origin::Socket => Some(goto::SHELLS_READ),
                    Action::AppWheel { .. } => Some(crate::app_wheel::USERS_ALONE),
                    Action::KeyUsed { .. } | Action::ResetKeyUse => Some(key_use::USERS_ALONE),
                    Action::RestoreKeyUse { .. } if origin == Origin::Socket => Some(key_use::READ_ALONE),
                    Action::NoticeDismiss { .. } => Some(crate::notice::USERS_ALONE),
                    Action::RestoreLayout { .. } if origin == Origin::Socket => Some(crate::layout_file::USERS_ALONE),
                    Action::RestoreWorkbooks { .. } if origin == Origin::Socket || m.compose.is_some() => {
                        Some(workbook::READ_ALONE)
                    }
                    Action::StartFresh | Action::UnfilledOpen { .. } => Some(crate::layout_file::USERS_ALONE),
                    Action::Paste { .. } => Some(clip::USERS_ALONE),
                    Action::CopyAnswer { .. } => Some(copy_ask::USERS_ALONE),
                    Action::CopyAsked { .. } if origin == Origin::Socket => Some(copy_ask::SHELLS_ALONE),
                    Action::PaneDrop { .. } | Action::TalkDrop { .. } => Some(clip::DROP_USERS),
                    Action::EditSettings => Some(SETTINGS_USERS),
                    Action::SettingsRead { .. } | Action::SetFeatures { .. } if origin == Origin::Socket => {
                        Some("only ottospace reads settings.json")
                    }
                    Action::SetHiddenSessions { .. } if origin == Origin::Socket => {
                        Some("only ottospace reads its files")
                    }
                    Action::EditorOpen | Action::EditorKeys { .. } => Some(editor::USERS_ALONE),
                    Action::EditorDone { .. } if origin == Origin::Socket => Some(editor::SHELLS_ALONE),
                    Action::ViewerRead { .. } | Action::ViewerScrolled { .. } if origin == Origin::Socket => {
                        Some(viewer::SHELLS_ALONE)
                    }
                    Action::WorktreeEdit { .. } | Action::ComposeWorktree { .. } => Some(crate::repos::USERS_ALONE),
                    Action::WorktreeAdded { .. } | Action::WorktreeFailed { .. } if origin == Origin::Socket => {
                        Some(crate::repos::USERS_ALONE)
                    }
                    Action::PrOpen { .. } => Some(crate::prs::USERS_ALONE),
                    Action::LinkOpen { .. } => Some(crate::term_links::USERS_ALONE),
                    Action::CityCamera { .. } => Some(city::USERS_ALONE),
                    Action::SetPrs { .. } if origin == Origin::Socket => Some("only ottospace reads pull requests"),
                    Action::SetHeads { .. } if origin == Origin::Socket => Some("only ottospace reads the checkouts"),
                    Action::SessionWork { .. } if origin == Origin::Socket => Some("only ottospace reads sessions"),
                    Action::RowMenuDrawn { .. } if origin == Origin::Socket => Some(workbook::USERS_ALONE),
                    Action::NewWindowCame { .. } | Action::NewWindowFailed { .. } | Action::WindowEdited { .. }
                        if origin == Origin::Socket =>
                    {
                        Some(crate::new_window::SHELLS_ALONE)
                    }
                    Action::TalkToggle => Some(rail::DRAWER_USERS),
                    _ if action.feature() == Some(Feature::Decisions) => Some(decisions::USERS_ALONE),
                    _ if action.feature() == Some(Feature::ZoomOut) => Some(zoom::USERS_ALONE),
                    Action::TaskDone { .. } | Action::TaskLater { .. } | Action::DoneUndo => Some(finish::USERS_ALONE),
                    Action::DoneNewTask => Some(finish::NEW_TASK_USERS),
                    Action::QuickOpen { .. } | Action::QuickPill { .. } => Some(quick::QUICK_USERS),
                    Action::ComposeDefault => Some(pickers::DEFAULT_USERS),
                    Action::ComposePen => Some(capture::USERS_ALONE),
                    Action::WorktreeRemoved { .. } if origin == Origin::Socket => Some(finish::SHELLS_ALONE),
                    Action::WorktreeDelete { .. } => Some(crate::repos::DELETE_USERS),
                    Action::LocalDay { .. } if origin == Origin::Socket => Some(finish::DAY_SHELLS),
                    Action::TalkKeys { on: true } if m.talk.as_ref().is_some_and(|t| !t.open) => {
                        Some(rail::DRAWER_USERS)
                    }
                    Action::BugRepo { .. } if origin == Origin::Socket => Some("only ottospace reads settings.json"),
                    Action::BugRepo { .. } | Action::BugStart { .. } => {
                        action.takes_keyboard().then_some("sneak mode is on")
                    }
                    action if action.bugs() => Some(crate::bug::USERS_ALONE),
                    _ => action.takes_keyboard().then_some("sneak mode is on"),
                };
                assert_eq!(m.refusal(action, origin), refused, "{action:?} from {origin:?}");
                m.update(action.clone().sent_by(origin));
                let ends = match action {
                    // The mode's own: its key and Esc leave from anywhere, the rest stay in it.
                    Action::Sneak { .. } | Action::LeaveSneak => true,
                    Action::SneakEnter { .. }
                    | Action::SneakDrawn { .. }
                    | Action::SneakType { .. }
                    | Action::SneakBackspace
                    | Action::SneakApp { .. }
                    | Action::AppWheel { .. } => false,
                    // A count of the key that turned it on, say: no input to it.
                    Action::KeyUsed { .. } | Action::ResetKeyUse | Action::RestoreKeyUse { .. } => false,
                    Action::NoticeDismiss { .. } => false,
                    // Its flag is off here: absent, it ends nothing.
                    Action::OverlayDismiss | Action::QuickOpen { .. } | Action::QuickPill { .. } => false,
                    _ => origin == Origin::User,
                };
                assert_eq!(m.sneak.is_none(), ends, "{action:?} from {origin:?}");
            }
        }
    }

    /// The tab bar as the shell reports it: each tab and its ×, left to right.
    fn tab_bar(tabs: &[u32]) -> Vec<Target> {
        let at = |(i, id): (usize, &u32)| {
            let x = i as f64 * 100.;
            [control(&format!("tab:{id}"), x), control(&format!("tab-close:{id}"), x + 80.)]
        };
        tabs.iter().enumerate().flat_map(at).collect()
    }

    /// An agent's `close_tab` takes tab 2 off the bar while the labels are up, and tab 3 slides
    /// under the pill that was on tab 2's ×. Those letters must not close anything.
    #[test]
    fn a_label_never_reaches_a_control_that_is_no_longer_drawn_or_the_one_that_took_its_place() {
        let mut m = Model::in_workspace();
        m.update(Action::NewTab);
        m.update(Action::NewTab);
        assert_eq!(m.tabs.iter().map(|t| t.id).collect::<Vec<_>>(), [1, 2, 3, HOME_TAB]);
        m.update(Action::Sneak { targets: tab_bar(&[1, 2, 3]) });
        let second = label_of(&m, "tab-close:2").expect("a label on tab 2's ×");
        let third = label_of(&m, "tab-close:3").expect("a label on tab 3's ×");
        assert_eq!((second.len(), third.len()), (2, 2), "a × takes two letters");

        // News: the mode stays on, and tab 2 is closed.
        m.update(Action::CloseTab { index: Some(1) }.sent_by(Origin::Socket));
        assert_eq!((m.mode(), m.tabs.len()), (Mode::Sneak, 3));
        // The next frame draws tabs 1 and 3: tab 3 where tab 2 was.
        m.update(Action::SneakDrawn { targets: tab_bar(&[1, 3]) }.sent_by(Origin::System));
        assert_eq!(label_of(&m, "tab-close:2"), None, "not drawn: no label");
        assert_eq!(label_of(&m, "tab-close:3"), Some(third.clone()), "the same letters");
        let moved = m.sneak.as_ref().unwrap().targets.iter().find(|t| t.label == third).unwrap();
        assert_eq!(moved.target.frame.x, 180., "the pill went with its control");

        // The letters that were on tab 2's × name nothing now: no tab closes, hidden or shown.
        assert_eq!(m.update(Action::SneakType { text: second }), []);
        assert_eq!((m.mode(), m.tabs.len()), (Mode::Normal, 3));
        // A label is only ever of a control in the last frame reported.
        m.update(Action::Sneak { targets: tab_bar(&[1, 3]) });
        let third = label_of(&m, "tab-close:3").unwrap();
        assert_eq!(m.update(Action::SneakType { text: third }), [Effect::Activate { id: "tab-close:3".into() }]);
    }

    #[test]
    fn sneak_enter_starts_the_mode_and_changes_nothing_while_it_is_on() {
        let mut m = Model::default();
        assert_eq!((m.update(Action::SneakEnter { targets: controls(30) }), m.mode()), (vec![], Mode::Sneak));
        m.update(Action::SneakType { text: "p".into() });
        // A second caller, or the user's ⌘⌃G just before: still on, the labels and letters as they were.
        let before = m.sneak.clone();
        m.update(Action::SneakEnter { targets: controls(3) });
        assert_eq!((m.mode(), &m.sneak), (Mode::Sneak, &before));
        // It starts only where the key does.
        m.update(Action::OpenPicker { axis: Right, new_tab: false, items: vec![PickItem::Terminal] });
        assert_eq!((m.update(Action::SneakEnter { targets: controls(3) }), m.mode()), (vec![], Mode::Pick));
    }

    #[test]
    fn starting_sneak_hides_the_accessibility_overlay() {
        let mut m = Model::default();
        m.update(Action::Open { kind: app(1), axis: Right, beside: None });
        m.update(Action::ToggleAxOverlay);
        assert!(m.ax_overlay);
        sneak(&mut m, 3);
        assert_eq!((m.ax_overlay, m.sneak.as_ref().map(|s| s.hid_overlay)), (false, Some(true)));
        // It stays hidden after the mode; ⌘⌃A shows it again.
        m.update(Action::LeaveSneak);
        assert!(!m.ax_overlay);
        sneak(&mut m, 3);
        assert_eq!(m.sneak.as_ref().map(|s| s.hid_overlay), Some(false), "nothing to hide this time");
    }

    #[test]
    fn sneak_starts_only_where_ottospace_has_the_keyboard_and_its_controls_show() {
        let mut m = Model::default();
        assert_eq!((sneak(&mut m, 0), m.mode()), (vec![], Mode::Normal), "nothing to label");
        // An app has the keyboard: the user returns first.
        m.update(Action::Open { kind: app(1), axis: Right, beside: None });
        m.update(Action::Enter { pane: 1 });
        assert_eq!((sneak(&mut m, 3), m.mode(), m.live), (vec![], Mode::App, Some(1)));
        m.update(Action::Leave);
        // The picker, the new-task box and the key reference cover the controls.
        m.update(Action::OpenPicker { axis: Right, new_tab: false, items: vec![PickItem::Terminal] });
        assert_eq!((sneak(&mut m, 3), m.mode()), (vec![], Mode::Pick));
        m.update(Action::ClosePicker);
        m.update(Action::OpenCompose { text: String::new() });
        assert_eq!((sneak(&mut m, 3), m.mode()), (vec![], Mode::Compose));
        m.update(Action::CloseCompose);
        m.update(Action::ToggleKeys);
        assert_eq!((sneak(&mut m, 3), m.sneak.is_none()), (vec![], true));
        m.update(Action::CloseKeys);
        // From list mode it starts, and Esc gives the list its keys back.
        m.update(Action::FocusList);
        assert_eq!((sneak(&mut m, 3), m.mode()), (vec![], Mode::Sneak));
        m.update(Action::LeaveSneak);
        assert_eq!(m.mode(), Mode::List);
    }

