    #[test]
    fn an_empty_kept_workspace_binds_with_no_line_and_a_client_never_binds_one() {
        const UID: &str = "9f3a61c2d4e5b708";
        let mut m = Model::default();
        m.update(Action::WorkbookNew { uid: UID.into() });
        // A client's task, opened: the workspace the user is in stays theirs.
        m.update(
            Action::TaskFromLine { line: "theirs".into(), known: Default::default(), open: true }
                .sent_by(Origin::Socket),
        );
        m.update(
            Action::TaskAdd {
                title: "x".into(),
                priority: 1,
                state: State::Running,
                tab: None,
                assign: Assign::default(),
            }
            .sent_by(Origin::Socket),
        );
        assert_eq!((m.space(), m.workbooks.list[0].task), (&Owner::Workbook { id: 1 }, None));
        // For later: no.
        m.update(Action::OpenCompose { text: "later".into() });
        assert_eq!(m.compose_status().as_deref(), Some("↵ starts @claude in your home folder · ⇧↵ later · Esc"));
        m.update(Action::ComposeSubmit { open: false });
        assert_eq!(m.workbooks.list[0].task, None);
        // The user's ↵: bound, with nothing said, since it takes nothing.
        m.update(Action::OpenCompose { text: "mine".into() });
        assert_eq!((m.joins(), m.compose_binds()), (Some(Owner::Workbook { id: 1 }), false));
        m.update(Action::ComposeEnter);
        let task = m.tasks.list.last().map(|task| task.id);
        assert_eq!((m.workbooks.list[0].task, m.tab_task(), m.spaces().len()), (task, task, 2));
        // Its file keeps the link.
        let text = crate::workbook::write(&m.workbooks.list[0]);
        assert_eq!(crate::workbook::parse(&text, UID).map(|book| book.task), Ok(task));
        // Its space gone (the last tab closed): opened from the list it is its own again.
        m.update(Action::CloseTab { index: None });
        assert_eq!((m.space(), m.workbooks.list[0].task), (&Owner::Home, task));
        m.update(Action::WorkbookOpen { workbook: 1, tab: None, home: None });
        assert_eq!((m.space(), m.workbooks.list[0].task), (&Owner::Workbook { id: 1 }, None));
    }

    /// The bug of 0.1.0: with the new task open in the drawer, a click on a tab did nothing (the
    /// box held the keyboard). The user's pick goes there and the line is kept; a client's waits.
    #[test]
    fn the_users_tab_click_puts_the_new_task_aside() {
        let mut m = Model::default();
        term(&mut m);
        m.update(Action::NewTab);
        m.update(Action::OpenCompose { text: "half".into() });
        assert_eq!(m.compose_host(), Some(Host::Drawer));
        m.update(Action::SelectTab { index: 0 }.sent_by(Origin::Socket));
        assert_eq!((m.active, m.compose_line().cloned()), (1, Some("half".into())));
        m.update(Action::SelectTab { index: 0 });
        assert_eq!((m.active, m.compose_line()), (0, None));
        m.update(Action::OpenCompose { text: String::new() });
        assert_eq!(m.compose_line().cloned(), Some("half".into()), "kept");
        // Not for a space: the box stays open, pinned where it was opened.
        let a = add_task(&mut m, "a", State::Captured);
        m.update(Action::CloseCompose);
        m.update(Action::SpaceOpen { space: task_space(a) });
        m.update(Action::OpenCompose { text: "more".into() });
        m.update(Action::SpaceSelect { index: 0 });
        assert_eq!((m.space(), m.compose_line().map(String::as_str)), (&Owner::Home, Some("more")));
        assert_eq!(m.compose_space(), Some(task_space(a)));
    }

    #[test]
    fn no_client_moves_what_the_user_types_to() {
        // The user types to task 1's agent; Workspace has a tab with a pane, the task's space two tabs.
        let typing = || {
            let mut m = Model::default();
            m.update(Action::SetRepos { repos: listed() });
            term(&mut m);
            let a = add_task(&mut m, "a", State::Captured);
            started(&mut m, Action::TaskTalk { id: a });
            assert_eq!(m.mode(), Mode::Talk);
            m
        };
        let siblings = [
            Action::NewTab,
            Action::NewEmptyTab,
            Action::SelectVisibleTab { index: 0 },
            Action::SelectTab { index: 0 },
            Action::CloseTab { index: None },
            Action::SpaceSelect { index: 0 },
            Action::SpaceClick { index: 0 },
            Action::SpaceCycle { delta: 1 },
            Action::SpaceHide { index: None },
            Action::SpaceOpen { space: Owner::Home },
            Action::TaskGo { id: None },
            Action::OpenRepo { path: "/code/app".into(), axis: Right },
            Action::OpenPicker { axis: Right, new_tab: true, items: vec![PickItem::Terminal] },
            Action::OpenCompose { text: "theirs".into() },
            Action::Focus { pane: 1 },
            Action::Split { axis: Right, kind: Kind::Terminal },
            Action::FocusList,
            Action::TalkToggle,
        ];
        for action in siblings {
            for origin in [Origin::Socket, Origin::System] {
                let mut m = typing();
                let (talk, tab) = (m.talk.clone(), m.tabs[m.active].id);
                m.update(action.clone().sent_by(origin));
                let what = format!("{origin:?}'s {action:?}");
                assert_eq!((&m.talk, m.mode(), m.tabs[m.active].id), (&talk, Mode::Talk, tab), "{what}");
            }
        }
        // The user's own: the keys go where the user went.
        let mut m = typing();
        m.update(Action::SpaceSelect { index: 0 });
        assert_eq!((m.talk.is_none(), m.mode()), (true, Mode::Normal));
        // The new task being written: a client neither closes nor files it.
        let mut m = Model::default();
        m.update(Action::OpenCompose { text: String::new() });
        keys(&mut m, "mine");
        for action in
            [Action::CloseCompose, Action::ComposeEscape, Action::ComposeEnter, Action::ComposeSubmit { open: false }]
        {
            assert_eq!(m.refusal(&action, Origin::Socket), Some(spaces::BOX_TYPING), "{action:?}");
        }
        m.update(Action::NewTab.sent_by(Origin::Socket));
        assert_eq!((line(&m), m.tasks.list.len(), m.active), ("mine", 0, 0));
    }

    #[test]
    fn the_users_click_on_the_bar_is_not_behind_the_new_task() {
        let boxed = || {
            let mut m = Model::default();
            m.update(Action::SetRepos { repos: listed() });
            term(&mut m);
            m.update(Action::OpenCompose { text: String::new() });
            keys(&mut m, "mine");
            m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::Left, select: false } });
            m
        };
        let cursor = |m: &Model| m.compose.as_ref().map(Field::cursor);
        let toggle = || Action::ToggleSection { section: Section::Repos };
        let open = || Action::OpenRepo { path: "/code/app".into(), axis: Right };
        const WHY: &str = "the new-task box is open";
        // Only the bar changes: the box keeps its line, its cursor and the keyboard.
        let mut m = boxed();
        m.update(toggle());
        assert_eq!((m.sidebar, line(&m), cursor(&m), m.mode()), (Some(Section::Repos), "mine", Some(3), Mode::Compose));
        m.update(Action::RepoFold { path: "/code/app".into(), fold: Some(true) });
        assert_eq!((m.repo_folded(&listed()[0]), line(&m), m.mode()), (true, "mine", Mode::Compose));
        keys(&mut m, "!");
        assert_eq!(line(&m), "min!e");
        m.update(Action::CloseSidebar);
        assert_eq!((m.sidebar, line(&m), m.mode()), (None, "min!e", Mode::Compose));
        // A client's waits, and is told why.
        for origin in [Origin::Socket, Origin::System] {
            assert_eq!(m.waits_for(&toggle(), origin), Some(WHY));
            m.update(toggle().sent_by(origin));
            assert_eq!((m.sidebar, m.mode()), (None, Mode::Compose), "{origin:?}");
        }
        // The keyboard goes where the click says: the line is put aside, and comes back.
        let click = Action::RepoClick { path: "/code/app-2".into(), axis: Right };
        for action in [open(), click, Action::SelectTab { index: 0 }, Action::Focus { pane: 1 }] {
            let mut m = boxed();
            assert_eq!(m.waits_for(&action, Origin::User), None, "{action:?}");
            m.update(action.clone());
            assert_eq!((line(&m), m.mode()), ("<closed>", Mode::Normal), "{action:?}");
            m.update(Action::OpenCompose { text: String::new() });
            assert_eq!((line(&m), cursor(&m)), ("mine", Some(3)), "{action:?}");
        }
        let mut m = boxed();
        m.update(open());
        assert_eq!((m.tabs.len(), m.pane(2).and_then(|p| p.cwd.as_deref())), (3, Some("/code/app")));
        // A field in a row takes the keyboard the same way: a new worktree's branch.
        let mut m = boxed();
        let dirs = repos::RepoDirs { worktrees: Some("/wt".into()), ..Default::default() };
        m.update(Action::SetRepoDirs { dirs }.sent_by(Origin::System));
        m.update(Action::WorktreeEdit { repo: "/code/app".into() });
        assert_eq!((line(&m), m.mode()), ("<closed>", Mode::Mark));
        // A key for panes still waits, and so does the bar under the key reference.
        let mut m = boxed();
        for action in [Action::Split { axis: Right, kind: Kind::Terminal }, Action::NewTab, Action::FocusList] {
            assert_eq!(m.waits_for(&action, Origin::User), Some(WHY), "{action:?}");
            m.update(action);
            assert_eq!((m.panes.len(), m.tabs.len(), line(&m), m.mode()), (1, 2, "mine", Mode::Compose));
        }
        // ⌘/ twice: the box's tags, then every key.
        m.update(Action::ToggleKeys);
        m.update(Action::ToggleKeys);
        for action in [toggle(), open()] {
            m.update(action);
            assert_eq!((m.sidebar, m.tabs.len(), line(&m)), (None, 2, "mine"));
        }
        // A follow-up that comes later (a pressed field's app, a launched app's window) is the
        // system's: it waits, and the line stays where it is. So does a branch's field with no folder.
        let mut m = boxed();
        let later = [Action::Enter { pane: 1 }, Action::Focus { pane: 1 }];
        for action in later.into_iter().chain([Action::WorktreeEdit { repo: "/code/app".into() }]) {
            let origin = if matches!(action, Action::WorktreeEdit { .. }) { Origin::User } else { Origin::System };
            m.update(action.clone().sent_by(origin));
            assert_eq!((line(&m), cursor(&m), m.mode()), ("mine", Some(3), Mode::Compose), "{action:?}");
        }
        // The toast is beside the box too. Its ×: the notice goes, the line, the cursor and
        // the keyboard stay. Its "Open settings": the editor's tab, and the line is put aside.
        let mut m = boxed();
        let dismiss = Action::NoticeDismiss { notice: crate::notice::Kind::SettingsProblem, text: "1:2".into() };
        assert_eq!(m.waits_for(&dismiss, Origin::User), None);
        assert_eq!(m.update(dismiss).len(), 1);
        assert_eq!((m.notice_hidden.len(), line(&m), cursor(&m), m.mode()), (1, "mine", Some(3), Mode::Compose));
        assert_eq!(m.waits_for(&Action::EditSettings, Origin::User), None);
        m.update(Action::EditSettings);
        assert_eq!((m.tabs.len(), m.settings_pane.is_some(), line(&m), m.mode()), (3, true, "<closed>", Mode::Normal));
        m.update(Action::OpenCompose { text: String::new() });
        assert_eq!((line(&m), cursor(&m)), ("mine", Some(3)));
        // The top row's + makes a workspace: the line is put aside.
        let mut m = boxed();
        m.update(Action::WorkbookNew { uid: "00000000000000a1".into() });
        assert_eq!((line(&m), m.tabs.len()), ("<closed>", 3));
        m.update(Action::OpenCompose { text: String::new() });
        assert_eq!(line(&m), "mine");
        // A click on the selected space, its conversation closed under the box: the line is put
        // aside as for any space pick, and the chip is there for the conversation.
        let mut m = boxed();
        let a = add_task(&mut m, "a", State::Captured);
        m.update(Action::TaskTalk { id: a });
        m.update(Action::TalkToggle);
        m.update(Action::OpenCompose { text: "mine".into() });
        let at = m.shown_spaces().iter().position(|space| space.of == *m.space()).unwrap_or_default();
        m.update(Action::SpaceClick { index: at });
        assert_eq!((line(&m), m.agent_chip().map(|chip| chip.space)), ("<closed>", Some(at)));
        m.update(Action::SpaceClick { index: at });
        assert_eq!(m.talk.as_ref().map(|talk| talk.open), Some(true));
        m.update(Action::OpenCompose { text: String::new() });
        assert_eq!(line(&m), "mine");
        // A line kept is not lost to a later one put aside empty, or a client's.
        let mut m = boxed();
        m.update(Action::Focus { pane: 1 });
        m.update(Action::OpenCompose { text: "theirs".into() }.sent_by(Origin::Socket));
        m.update(Action::Focus { pane: 1 });
        m.update(Action::OpenCompose { text: String::new() });
        assert_eq!(line(&m), "mine");
        // While the user's editor has the line, a click that would put it aside waits.
        m.update(Action::EditorOpen);
        assert_eq!((m.edits_compose(), m.waits_for(&open(), Origin::User)), (true, Some(WHY)));
        m.update(open());
        m.update(toggle());
        assert_eq!((m.tabs.len(), m.sidebar, m.edits_compose(), line(&m)), (2, Some(Section::Repos), true, "mine"));
    }

    #[test]
    fn a_click_on_a_worktree_a_task_works_in_selects_that_task_and_its_terminal_word_does_not() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: listed() });
        let click = |path: &str| Action::RepoClick { path: path.into(), axis: Right };
        // No task there: a terminal in a workspace of its own, named for the folder, its default.
        m.update(click("/code/app-2"));
        assert_eq!((m.space(), m.pane(1).and_then(|p| p.cwd.as_deref())), (&WORKSPACE, Some("/code/app-2")));
        assert_eq!((m.space_title(m.space()), m.space_worktree(m.space())), ("app-2".into(), Some("/code/app-2")));
        // Two tasks in the repository, one dismissed: the live one's space is selected, its agent not started.
        for line in ["older >app", "newer >app"] {
            m.update(Action::TaskFromLine { line: line.into(), known: Default::default(), open: false });
        }
        m.update(Action::TaskDismiss { id: 2 });
        assert_eq!(m.repo_task("/code/app"), Some(1));
        let effects = m.update(click("/code/app"));
        assert!(!effects.iter().any(|e| matches!(e, Effect::StartAgent { .. })), "{effects:?}");
        assert_eq!((m.space(), m.panes.len()), (&task_space(1), 1));
        // Again from its hidden space: it comes back.
        m.update(Action::SpaceHide { index: None });
        m.update(click("/code/app"));
        assert_eq!(m.space(), &task_space(1));
        // The row's Terminal word: a terminal there anyway, in the task's empty tab.
        m.update(Action::OpenRepo { path: "/code/app".into(), axis: Right });
        assert_eq!((m.space(), m.panes.len()), (&task_space(1), 2));
        // The worktree's click: its workspace again, though a task works there too.
        m.update(Action::TaskFromLine { line: "third >app-2".into(), known: Default::default(), open: false });
        m.update(click("/code/app-2"));
        assert_eq!((m.space(), m.panes.len()), (&WORKSPACE, 2));
    }

    /// The Repos list of `listed`, its worktree on branch `fix/login`, and a second repository.
    fn branched() -> Vec<Repo> {
        let mut repos = listed();
        repos[0].worktrees[0].branch = Some("fix/login".into());
        repos.push(Repo { name: "zed".into(), path: "/code/zed".into(), branch: None, worktrees: vec![] });
        repos
    }

    /// The owner: a workspace "can carry a worktree (doesn't have to)". The user's click on a
    /// checkout no workspace has makes one for it, named for its branch, a terminal there; the
    /// click again selects it.
    #[test]
    fn a_repos_click_makes_a_workspace_of_that_worktree_and_selects_it_again() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: branched() });
        let click = |path: &str| Action::RepoClick { path: path.into(), axis: Right };
        m.update(click("/code/app-2"));
        let made = (m.space().clone(), m.space_title(m.space()), m.space_worktree(m.space()).map(String::from));
        assert_eq!(made, (WORKSPACE, "fix/login".into(), Some("/code/app-2".into())));
        assert_eq!(m.pane(1).and_then(|p| p.cwd.as_deref()), Some("/code/app-2"));
        assert_eq!(m.workbooks.list[0].worktree.as_deref(), Some("/code/app-2"), "kept in its file");
        // Again, from Home: the same one; nothing is made or opened.
        m.update(Action::SpaceSelect { index: 0 });
        m.update(click("/code/app-2"));
        assert_eq!((m.space(), m.workbooks.list.len(), m.panes.len()), (&WORKSPACE, 1, 1));
        // From that workspace, a repository's own folder: a new one, named for the repository, in
        // the workspaces' one order (by name: "app" before "fix/login").
        m.update(click("/code/app"));
        let second = Owner::Workbook { id: 2 };
        assert_eq!(
            (m.space(), m.space_title(&second), m.space_worktree(&second)),
            (&second, "app".into(), Some("/code/app"))
        );
        assert_eq!(m.shown_spaces().iter().map(|s| s.of.clone()).collect::<Vec<_>>(), [Owner::Home, second, WORKSPACE]);
        // Hidden: it comes back. Closed and kept: it opens again, its default kept.
        m.update(Action::SpaceHide { index: None });
        m.update(click("/code/app"));
        assert_eq!(m.space(), &Owner::Workbook { id: 2 });
        // A client's click on a checkout of no workspace makes none and sets no default.
        let theirs = m.update(click("/code/zed").sent_by(Origin::Socket));
        assert!(theirs.iter().any(|e| matches!(e, Effect::Opened(_))), "{theirs:?}");
        assert_eq!(m.workbooks.list.iter().filter(|book| book.worktree.as_deref() == Some("/code/zed")).count(), 0);
        assert_eq!(m.workbooks.list.len(), 2);
    }

    /// Of several workspaces for a checkout, the one whose default it is, then the one
    /// selected last; a task's space is chosen only when no default matches.
    #[test]
    fn a_repos_click_prefers_the_default_then_the_workspace_selected_last() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: branched() });
        let click = |path: &str| Action::RepoClick { path: path.into(), axis: Right };
        // A task of the worktree, started from Home: a space of its own.
        m.update(Action::OpenCompose { text: "first >app-2".into() });
        m.update(Action::ComposeEnter);
        assert_eq!(m.repo_space("/code/app-2", true), Some((task_space(1), Some(1))));
        // A workspace whose default it is wins over the task's space.
        m.update(Action::SpaceSelect { index: 0 });
        m.update(Action::OpenRepo { path: "/code/app-2".into(), axis: Right });
        assert_eq!(m.space_worktree(m.space()), Some("/code/app-2"), "made from Home: the user's has the default");
        let mine = m.space().clone();
        m.update(Action::SpaceSelect { index: 0 });
        m.update(click("/code/app-2"));
        assert_eq!(m.space(), &mine);
        // Two tasks' spaces for the main checkout: the one selected last.
        for line in ["a >app", "b >app"] {
            m.update(Action::SpaceSelect { index: 0 });
            m.update(Action::OpenCompose { text: line.into() });
            m.update(Action::ComposeEnter);
        }
        m.update(Action::SpaceOpen { space: task_space(2) });
        m.update(Action::SpaceSelect { index: 0 });
        m.update(click("/code/app"));
        assert_eq!(m.space(), &task_space(2));
    }

    /// The owner: "a terminal in the workspace starts in the default worktree makes sense". A
    /// workspace of no default: where a terminal starts today.
    #[test]
    fn a_terminal_opened_in_a_workspace_starts_in_its_default_worktree() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: branched() });
        m.update(Action::RepoClick { path: "/code/app-2".into(), axis: Right });
        let cwd = |m: &Model| m.focused.and_then(|id| m.pane(id)).and_then(|p| p.cwd.clone());
        term(&mut m);
        assert_eq!(cwd(&m).as_deref(), Some("/code/app-2"));
        m.update(Action::NewTab);
        m.update(Action::Open { kind: Kind::Terminal, axis: Right, beside: None });
        assert_eq!(cwd(&m).as_deref(), Some("/code/app-2"));
        // A client's split there too: it is the workspace's terminal.
        m.update(Action::Split { axis: Right, kind: Kind::Terminal }.sent_by(Origin::Socket));
        assert_eq!(cwd(&m).as_deref(), Some("/code/app-2"));
        // Its worktree no longer listed: no default, and a terminal starts where it did before.
        m.update(Action::SetRepos { repos: Vec::new() });
        assert_eq!(m.space_worktree(m.space()), None);
        term(&mut m);
        assert_eq!(cwd(&m), None);
        // An empty pane filled later: the default as listed then, not when the pane was made.
        m.update(Action::SetRepos { repos: branched() });
        m.update(Action::NewEmptyTab);
        let empty = m.focused.unwrap_or_default();
        assert_eq!(m.pane(empty).and_then(|p| p.cwd.clone()), None);
        m.update(Action::SetRepos { repos: Vec::new() });
        m.update(Action::Fill { pane: empty, kind: Kind::Terminal }.sent_by(Origin::System));
        assert_eq!(m.pane(empty).and_then(|p| p.cwd.clone()), None);
        m.update(Action::SetRepos { repos: branched() });
        m.update(Action::NewEmptyTab);
        let empty = m.focused.unwrap_or_default();
        m.update(Action::Fill { pane: empty, kind: Kind::Terminal }.sent_by(Origin::System));
        assert_eq!(m.pane(empty).and_then(|p| p.cwd.as_deref()), Some("/code/app-2"));
        // A client's terminal on Home goes to the workspace selected last: in its default.
        m.update(Action::SpaceSelect { index: 0 });
        m.update(Action::Split { axis: Right, kind: Kind::Terminal }.sent_by(Origin::Socket));
        assert_eq!((m.space(), cwd(&m).as_deref()), (&WORKSPACE, Some("/code/app-2")));
        // A workspace made with + has none.
        m.update(Action::WorkbookNew { uid: "9f3a61c2d4e5b708".into() });
        term(&mut m);
        assert_eq!((m.space_worktree(m.space()), cwd(&m)), (None, None));
    }

    /// A task started in a workspace with a default starts there, unless its line names
    /// another; a second one in a workspace of tasks too, not the first one's folder.
    #[test]
    fn a_task_started_in_a_workspace_starts_in_its_default_worktree() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: branched() });
        m.update(Action::RepoClick { path: "/code/app-2".into(), axis: Right });
        m.update(Action::OpenCompose { text: "first".into() });
        assert_eq!(
            m.compose_status().as_deref(),
            Some("↵ starts @claude in app-2 on fix/login, in this workspace · ⇧↵ later · Esc")
        );
        let cwd = |effects: &[Effect], id: TaskId| {
            effects.iter().find_map(|effect| match effect {
                Effect::StartAgent { task: Subject::Task(task), cwd, .. } if *task == id => cwd.clone(),
                _ => None,
            })
        };
        let effects = m.update(Action::ComposeEnter);
        assert_eq!((cwd(&effects, 1).as_deref(), m.task_worktree(1)), (Some("/code/app-2"), Some("/code/app-2")));
        // Bound to the task, the workspace keeps its default.
        let of = task_space(1);
        assert_eq!((m.space(), m.space_worktree(&of)), (&of, Some("/code/app-2")));
        let effects = join(&mut m, "second >zed");
        assert_eq!(cwd(&effects, 2).as_deref(), Some("/code/zed"));
        let effects = join(&mut m, "third");
        assert_eq!(cwd(&effects, 3).as_deref(), Some("/code/app-2"), "the default, not the task in front's");
    }

    /// Where task `id`'s agent was asked to start, by these effects.
    fn started_in(effects: &[Effect], id: TaskId) -> Option<Option<String>> {
        effects.iter().find_map(|effect| match effect {
            Effect::StartAgent { task: Subject::Task(task), cwd, .. } if *task == id => Some(cwd.clone()),
            _ => None,
        })
    }

    /// Review of the pinned box: closed by Esc after the user's switch of space, the keyboard is
    /// in the conversation on show, as when it closes in the space it was opened in.
    #[test]
    fn esc_after_a_switch_gives_the_keys_to_the_conversation_on_show() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: listed() });
        for (uid, title) in [("9f3a61c2d4e5b708", "one >app"), ("1b7c0e9a55d2f346", "two >app")] {
            m.update(Action::WorkbookNew { uid: uid.into() });
            term(&mut m);
            m.update(Action::OpenCompose { text: title.into() });
            m.update(Action::ComposeEnter);
        }
        for id in [1, 2] {
            m.update(Action::AgentStarted { task: Subject::Task(id), session: None, at: 1 }.sent_by(Origin::System));
        }
        let keys = |m: &Model| m.talk.as_ref().map(|talk| (talk.task.clone(), talk.open, talk.keys));
        // In its own space: Esc, and the keys are the conversation's.
        m.update(Action::OpenCompose { text: "x".into() });
        m.update(Action::ComposeEscape);
        let own = keys(&m);
        assert_eq!(own, Some((Subject::Task(2), true, true)));
        // Opened in task 2's, the user goes to task 1's, then Esc: task 1's has them.
        m.update(Action::OpenCompose { text: "y".into() });
        m.update(Action::SpaceOpen { space: task_space(1) });
        assert!(m.compose_elsewhere());
        m.update(Action::ComposeEscape);
        assert_eq!((m.compose.is_none(), keys(&m)), (true, Some((Subject::Task(1), true, true))));
    }

    /// The owner: the new-task box is pinned to where it was opened. The user's switch of space
    /// keeps it open there (a client's waits): ↵ starts the task in that workspace, with its new
    /// worktree. The user's Switch (or ⌘N) brings it to the one on show, the worktree choice
    /// checked again there. Its space hidden: it goes where the user is.
    #[test]
    fn the_new_task_box_is_pinned_to_the_workspace_it_was_opened_in() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: branched() });
        let dirs = repos::RepoDirs { worktrees: Some("/home/.ottospace/worktrees".into()), ..Default::default() };
        m.update(Action::SetRepoDirs { dirs });
        m.update(Action::WorkbookNew { uid: "9f3a61c2d4e5b708".into() });
        let b = m.space().clone();
        m.update(Action::RepoClick { path: "/code/app".into(), axis: Right });
        let a = m.space().clone();
        m.update(Action::OpenCompose { text: "Fix the zoom".into() });
        m.update(Action::ComposeWorktree { new: Some(true) });
        m.update(Action::SpaceOpen { space: b.clone() }.sent_by(Origin::Socket));
        assert_eq!((m.space(), m.compose_elsewhere()), (&a, false), "a client's waits");
        let go = |m: &mut Model, of: &Owner| m.update(Action::SpaceOpen { space: of.clone() });
        go(&mut m, &b);
        assert_eq!((m.space(), m.compose_space(), m.compose_elsewhere()), (&b, Some(a.clone()), true));
        assert_eq!(m.refusal(&Action::ComposeHere, Origin::Socket), Some(spaces::PIN_USERS));
        m.update(Action::ComposeHere.sent_by(Origin::Socket));
        assert_eq!(m.compose_space(), Some(a.clone()));
        // ↵: in A, its new worktree asked for; the view goes with it.
        let effects = m.update(Action::ComposeEnter);
        assert!(effects.iter().any(|e| matches!(e, Effect::AddWorktree { repo, .. } if repo == "/code/app")));
        assert_eq!((m.task_space(1), m.space()), (task_space(1), &task_space(1)));
        assert!(matches!(m.workbooks.space_of(&b), Owner::Workbook { .. }), "B is not bound");
        // Pinned to task 1's, the view moved to B: the user's Switch brings it to B, which has no
        // repository, so no new worktree.
        m.update(Action::OpenCompose { text: "Second".into() });
        m.update(Action::ComposeWorktree { new: Some(true) });
        assert!(m.compose_worktree);
        go(&mut m, &b);
        m.update(Action::ComposeHere);
        assert_eq!((m.compose_space(), m.compose_elsewhere(), m.compose_worktree), (Some(b.clone()), false, false));
        m.update(Action::ComposeEnter);
        assert_eq!(m.task_space(2), task_space(2));
        assert_ne!(m.task_space(2), m.task_space(1));
        // The user's ⌘N while the box is pinned elsewhere: here, the line kept.
        m.update(Action::OpenCompose { text: "third".into() });
        go(&mut m, &task_space(1));
        m.update(Action::OpenCompose { text: String::new() });
        assert_eq!((m.compose_space(), m.compose_line().map(String::as_str)), (Some(task_space(1)), Some("third")));
        m.update(Action::ComposeEnter);
        assert_eq!(m.task_space(3), task_space(1));
        // Pinned to a space hidden since: the box goes where the user is, with no line.
        m.update(Action::OpenCompose { text: "fourth".into() });
        go(&mut m, &task_space(2));
        // (A space hides under the box by no request: set as a file read or a shell step could leave it.)
        m.spaces.iter_mut().filter(|space| space.of == task_space(1)).for_each(|space| space.hidden = true);
        m.update(Action::Tick { now: 1 }.sent_by(Origin::System));
        assert_eq!((m.compose_space(), m.compose_elsewhere()), (Some(m.space().clone()), false));
    }

    /// The owner's canvas: "⌘N here joins this workspace and shares its checkout; the new-task box
    /// offers a new worktree as the other choice". The user's ↵ with it asks git for one named
    /// for the task; the task is in the workspace at once, and its agent starts there once it is
    /// made. A workspace of one task follows it there; with several, only the task moves.
    #[test]
    fn the_new_task_box_offers_a_new_worktree_where_the_task_starts_once_it_is_made() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: branched() });
        let root = "/home/.ottospace/worktrees";
        let dirs = repos::RepoDirs { worktrees: Some(root.into()), ..Default::default() };
        m.update(Action::SetRepoDirs { dirs });
        m.update(Action::RepoClick { path: "/code/app".into(), axis: Right });
        m.update(Action::OpenCompose { text: "Fix the zoom!".into() });
        let choice =
            |new, branch: &str| Some(worktrees::WorktreeChoice { new, repo: "app".into(), branch: branch.into() });
        assert_eq!(m.compose_worktree(), choice(false, "fix-the-zoom"), "this checkout, by default");
        let toggle = Action::ComposeWorktree { new: None };
        for origin in [Origin::Socket, Origin::System] {
            assert_eq!(m.refusal(&toggle, origin), Some(repos::USERS_ALONE));
        }
        m.update(toggle);
        assert_eq!(m.compose_worktree(), choice(true, "fix-the-zoom"));
        let said = "↵ starts @claude in a new worktree of app on fix-the-zoom, in this workspace · ⇧↵ later · Esc";
        assert_eq!(m.compose_status().as_deref(), Some(said));
        let path = format!("{root}/app/fix-the-zoom");
        let asked = |branch: &str, path: &str| Effect::AddWorktree {
            repo: "/code/app".into(),
            branch: branch.into(),
            path: path.into(),
            root: root.into(),
            fresh: true,
        };
        let effects = m.update(Action::ComposeEnter);
        assert!(effects.contains(&asked("fix-the-zoom", &path)), "{effects:?}");
        assert_eq!(started_in(&effects, 1), None, "nothing starts before the worktree is made");
        // In the workspace at once, its conversation open: it says what it waits for.
        let of = task_space(1);
        assert_eq!((m.space(), m.compose_worktree.then_some(())), (&of, None));
        assert_eq!(m.talk_note().as_deref(), Some("making its worktree fix-the-zoom…"));
        assert_eq!((m.talk_resumes(), m.agent_dir(&Subject::Task(1))), (None, None));
        // Made: the agent starts there, and the workspace of one task follows.
        let mut repos = branched();
        let listed = |name: &str, path: &str| repos::Worktree {
            name: name.into(),
            path: path.into(),
            branch: Some(name.into()),
        };
        repos[0].worktrees.push(listed("fix-the-zoom", &path));
        let made = |path: &str, repos: &[Repo]| Action::WorktreeAdded {
            repo: "/code/app".into(),
            path: path.into(),
            asked: path.into(),
            fresh: true,
            repos: repos.to_vec(),
        };
        let effects = m.update(made(&path, &repos).sent_by(Origin::System));
        assert_eq!(started_in(&effects, 1), Some(Some(path.clone())));
        assert_eq!((m.task_worktree(1), m.space_worktree(&of), m.space()), (Some(&*path), Some(&*path), &of));
        // A second there, the same words: the next free branch. Two tasks: only its own moves.
        m.update(Action::OpenCompose { text: "fix the zoom".into() });
        m.update(Action::ComposeWorktree { new: Some(true) });
        assert_eq!(m.compose_worktree(), choice(true, "fix-the-zoom-2"));
        let second = format!("{root}/app/fix-the-zoom-2");
        assert!(m.update(Action::ComposeEnter).contains(&asked("fix-the-zoom-2", &second)));
        repos[0].worktrees.push(listed("fix-the-zoom-2", &second));
        let effects = m.update(made(&second, &repos).sent_by(Origin::System));
        assert_eq!(started_in(&effects, 2), Some(Some(second.clone())));
        assert_eq!((m.task_worktree(2), m.space_worktree(&of)), (Some(&*second), Some(&*path)));
        // Git refused: the task waits in the workspace's checkout, unstarted; its Start is the user's.
        m.update(Action::OpenCompose { text: "deploy".into() });
        m.update(Action::ComposeWorktree { new: Some(true) });
        m.update(Action::ComposeEnter);
        let deploy = format!("{root}/app/deploy");
        // A + answer at the same folder is not the task's: it still waits.
        let theirs = |fresh| Action::WorktreeFailed { asked: deploy.clone(), fresh, repos: repos.clone() };
        let plus = Action::WorktreeAdded {
            repo: "/code/app".into(),
            path: deploy.clone(),
            asked: deploy.clone(),
            fresh: false,
            repos: repos.clone(),
        };
        assert_eq!(started_in(&m.update(plus.sent_by(Origin::System)), 3), None);
        m.update(theirs(false).sent_by(Origin::System));
        assert_eq!(m.talk_note().as_deref(), Some("making its worktree deploy…"));
        let failed = theirs(true);
        assert_eq!(m.refusal(&failed, Origin::Socket), Some(repos::USERS_ALONE));
        assert_eq!(m.update(failed.sent_by(Origin::System)), []);
        assert_eq!((m.talk_note(), m.talk_resumes()), (None, Some(false)));
        assert_eq!(m.agent_dir(&Subject::Task(3)).as_deref(), Some(&*path));
        // A line a client wrote, filed by its ↵: no worktree, nothing started.
        m.update(Action::OpenCompose { text: "theirs".into() }.sent_by(Origin::Socket));
        m.update(Action::ComposeWorktree { new: Some(true) });
        let effects = m.update(Action::ComposeEnter.sent_by(Origin::Socket));
        assert!(!effects.iter().any(|e| matches!(e, Effect::AddWorktree { .. } | Effect::StartAgent { .. })));
    }

    /// The choice is offered only where the task would work in a listed checkout, and there is
    /// a folder for worktrees.
    #[test]
    fn the_new_worktree_choice_is_absent_with_no_repository_to_make_it_of() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: branched() });
        m.update(Action::WorkbookNew { uid: "9f3a61c2d4e5b708".into() });
        m.update(Action::OpenCompose { text: "notes".into() });
        assert_eq!(m.compose_worktree(), None, "no folder for worktrees");
        let dirs = repos::RepoDirs { worktrees: Some("/w".into()), ..Default::default() };
        m.update(Action::SetRepoDirs { dirs });
        assert_eq!(m.compose_worktree(), None, "a workspace of no repository");
        m.update(Action::ComposeWorktree { new: Some(true) });
        assert!(!m.compose_worktree);
        // The line names one: offered.
        m.update(Action::FieldEdit { edit: Edit::Insert(" >zed".into()) });
        assert_eq!(m.compose_worktree().map(|choice| (choice.repo, choice.new)), Some(("zed".into(), false)));
        // ⇧↵ (for later) makes none.
        m.update(Action::ComposeWorktree { new: Some(true) });
        let effects = m.update(Action::ComposeSubmit { open: false });
        assert!(!effects.iter().any(|e| matches!(e, Effect::AddWorktree { .. })));
    }

    const MOVED_SESSION: &str = "8f14e45f-ceea-467f-a8d3-0242ac130009";

    /// What the shell reads of task `id`'s session, as the system: it says its agent is in `cwd`.
    fn agent_in(m: &mut Model, runner: &str, cwd: &str) -> Vec<Effect> {
        let work = progress::Work { runner: runner.into(), session: MOVED_SESSION.into(), ..Default::default() };
        m.update(Action::SessionWork { work, cwd: Some(cwd.into()) }.sent_by(Origin::System))
    }

    /// The workspace of the repository's own folder, its one task started there and following session
    /// `MOVED_SESSION` of `runner`.
    fn one_task_in_app(runner: &str) -> Model {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: branched() });
        m.update(Action::RepoClick { path: "/code/app".into(), axis: Right });
        join(&mut m, "first");
        m.tasks.link(1, sessions::Link { runner: runner.into(), id: MOVED_SESSION.into(), state: None });
        m
    }

    /// The owner: "an agent could create a worktree when starting a task - in that case, we'd want
    /// the workspace associated with that task to connect to that worktree". Its session says it
    /// works in another checkout of its repository: the task works there, and so does its
    /// workspace, which had the task's old one and no other task.
    #[test]
    fn a_task_follows_its_agent_into_a_worktree_and_so_does_its_workspace_of_one_task() {
        let mut m = one_task_in_app("claude");
        let of = task_space(1);
        assert_eq!((m.task_worktree(1), m.space_worktree(&of)), (Some("/code/app"), Some("/code/app")));
        // A `cd` in its own checkout moves nothing.
        agent_in(&mut m, "claude", "/code/app");
        assert_eq!(m.task_worktree(1), Some("/code/app"));
        let effects = agent_in(&mut m, "claude", "/code/app-2/src");
        assert!(!effects.contains(&Effect::ReadRepos), "listed already: {effects:?}");
        assert_eq!((m.task_worktree(1), m.space_worktree(&of)), (Some("/code/app-2"), Some("/code/app-2")));
        assert_eq!(m.tasks.get(1).and_then(|task| task.worktree.as_deref()), Some("/code/app-2"), "kept with the task");
        // A terminal opened there now starts in the new one; so does an agent started afresh.
        term(&mut m);
        assert_eq!(m.focused.and_then(|id| m.pane(id)).and_then(|p| p.cwd.as_deref()), Some("/code/app-2"));
        m.tasks.list[0].session = None;
        assert_eq!(m.agent_dir(&Subject::Task(1)).as_deref(), Some("/code/app-2"));
        // A client says nothing of where an agent works.
        let theirs = progress::Work { runner: "claude".into(), session: "x".into(), ..Default::default() };
        let action = Action::SessionWork { work: theirs, cwd: Some("/code/app".into()) };
        assert_eq!(m.refusal(&action, Origin::Socket), Some("only ottospace reads sessions"));
    }

    /// The owner: "good call on differentiating the subagent worktrees". A sub-agent's worktree is
    /// never the task's; nor is anything a runner whose records do not move with its agent says.
    #[test]
    fn a_subagents_worktree_and_a_runner_that_never_moves_move_no_task() {
        let mut repos = branched();
        let sub = "/code/app/.claude/worktrees/agent-a1b2";
        repos[0].worktrees.push(repos::Worktree { name: "agent-a1b2".into(), path: sub.into(), branch: None });
        let mut m = one_task_in_app("claude");
        m.update(Action::SetRepos { repos: repos.clone() });
        let effects = agent_in(&mut m, "claude", &format!("{sub}/src"));
        assert_eq!((m.task_worktree(1), effects.contains(&Effect::ReadRepos)), (Some("/code/app"), false));
        assert!(
            subagent_path(sub) && !subagent_path("/code/app/.claude/worktrees/fix") && !subagent_path("/code/agent-x")
        );
        // Codex: its `turn_context` cwd is the client's, never the agent's.
        let mut m = one_task_in_app("codex");
        agent_in(&mut m, "codex", "/code/app-2");
        assert_eq!(m.task_worktree(1), Some("/code/app"));
        // Another repository's checkout is no worktree of the task's.
        let mut m = one_task_in_app("claude");
        agent_in(&mut m, "claude", "/code/zed");
        assert_eq!(m.task_worktree(1), Some("/code/app"));
    }

    /// A worktree made a moment ago may not be in the list yet: it is read again, every
    /// `MOVE_RETRY_MS` for `MOVE_WAIT_MS`, and the task follows once it is there.
    #[test]
    fn a_worktree_not_listed_yet_is_looked_for_again_a_while() {
        let mut m = one_task_in_app("claude");
        m.update(Action::Tick { now: 1_000 });
        let fresh = "/code/app/.claude/worktrees/fix-zoom";
        assert!(agent_in(&mut m, "claude", fresh).contains(&Effect::ReadRepos));
        assert_eq!(m.task_worktree(1), Some("/code/app"));
        // Said again by the next read: not asked again at once.
        assert!(!agent_in(&mut m, "claude", fresh).contains(&Effect::ReadRepos));
        assert!(!m.update(Action::Tick { now: 1_000 + MOVE_RETRY_MS - 1 }).contains(&Effect::ReadRepos));
        assert!(m.update(Action::Tick { now: 1_000 + MOVE_RETRY_MS }).contains(&Effect::ReadRepos));
        // Listed now: the task works there.
        let mut repos = branched();
        repos[0].worktrees.push(repos::Worktree { name: "fix-zoom".into(), path: fresh.into(), branch: None });
        m.update(Action::SetRepos { repos }.sent_by(Origin::System));
        assert_eq!(m.task_worktree(1), Some(fresh));
        assert!(!m.update(Action::Tick { now: 1_000 + 2 * MOVE_RETRY_MS }).contains(&Effect::ReadRepos));
        // One never listed: asked for until the wait is over, then no more.
        agent_in(&mut m, "claude", "/code/app-9");
        let asks = (1..=10).filter(|n| {
            let now = 1_000 + 2 * MOVE_RETRY_MS + n * MOVE_RETRY_MS;
            m.update(Action::Tick { now }).contains(&Effect::ReadRepos)
        });
        assert_eq!(asks.count() as u64, MOVE_WAIT_MS / MOVE_RETRY_MS);
        assert_eq!(m.task_worktree(1), Some(fresh));
        // Listed later, by a read for another reason (the user's +): it still follows.
        let mut repos = branched();
        repos[0].worktrees.push(repos::Worktree { name: "app-9".into(), path: "/code/app-9".into(), branch: None });
        m.update(Action::SetRepos { repos }.sent_by(Origin::System));
        assert_eq!(m.task_worktree(1), Some("/code/app-9"));
    }

    /// The worktree a task moved into is removed, and its agent is back in the repository's own
    /// folder: the task and its workspace of one task work there, not in the one that went.
    #[test]
    fn back_from_a_worktree_that_went_the_task_and_its_workspace_forget_it() {
        let mut m = one_task_in_app("claude");
        agent_in(&mut m, "claude", "/code/app-2");
        let mut repos = branched();
        repos[0].worktrees.clear();
        m.update(Action::SetRepos { repos }.sent_by(Origin::System));
        agent_in(&mut m, "claude", "/code/app");
        let of = task_space(1);
        assert_eq!(m.tasks.get(1).and_then(|task| task.worktree.as_deref()), Some("/code/app"));
        assert_eq!(m.workbooks.list[0].worktree.as_deref(), Some("/code/app"), "{:?}", m.space_worktree(&of));
    }

    /// The owner: with several tasks in a workspace, one that moves "like the subagent case": the
    /// workspace does not change; that task has its own worktree, and says so.
    #[test]
    fn a_task_that_moves_in_a_workspace_of_several_leaves_its_default_as_it_is() {
        let mut m = one_task_in_app("claude");
        join(&mut m, "second");
        agent_in(&mut m, "claude", "/code/app-2");
        let of = task_space(1);
        assert_eq!((m.task_worktree(1), m.task_worktree(2), m.space_worktree(&of)), {
            (Some("/code/app-2"), Some("/code/app"), Some("/code/app"))
        });
        assert_eq!((m.worktree_label(1), m.worktree_label(2)), (Some("app-2".into()), Some("app".into())));
        // A task that joins now starts in the workspace's default.
        join(&mut m, "third");
        assert_eq!(m.task_worktree(3), Some("/code/app"));
    }

    /// A task's worktree is kept in its file; an older file, or one that could be no folder, has none.
    #[test]
    fn a_tasks_worktree_is_kept_and_an_older_file_has_none() {
        let mut m = Model::default();
        let kept = |worktree: &str| {
            let text =
                format!(r#"{{"id":7,"title":"app","state":"captured","priority":3,"repo":"/code/app"{worktree}}}"#);
            serde_json::from_str::<Task>(&text).expect("kept")
        };
        m.update(Action::RestoreTasks { tasks: vec![kept(""), kept(r#","worktree":"relative""#)], floor: 7 });
        assert!(m.tasks.list.iter().all(|task| task.worktree.is_none()));
        let task = kept(r#","worktree":"/code/app-2""#);
        let text = serde_json::to_string(&task.for_file()).expect("written");
        assert_eq!(
            serde_json::from_str::<Task>(&text).map(|task| task.worktree).ok(),
            Some(Some("/code/app-2".into()))
        );
    }

    /// Where a workspace's tasks work in different worktrees, each says which; else none does.
    #[test]
    fn a_tasks_worktree_is_named_only_where_its_workspaces_tasks_are_apart() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: branched() });
        m.update(Action::RepoClick { path: "/code/app".into(), axis: Right });
        join(&mut m, "first");
        join(&mut m, "second");
        assert_eq!((m.worktree_label(1), m.worktree_label(2)), (None, None));
        join(&mut m, "third >app-2");
        let labels: Vec<Option<String>> = (1..=3).map(|id| m.worktree_label(id)).collect();
        assert_eq!(labels, [Some("app".into()), Some("app".into()), Some("app-2".into())]);
        // A task in no workspace of others: none.
        m.update(Action::TaskFromLine { line: "alone >zed".into(), known: Default::default(), open: false });
        assert_eq!(m.worktree_label(4), None);
    }

    #[test]
    fn the_drawer_is_only_ever_on_the_selected_spaces_agent() {
        let mut m = Model::default();
        term(&mut m);
        let (a, b) = (add_task(&mut m, "a", State::Captured), add_task(&mut m, "b", State::Captured));
        m.update(Action::SpaceOpen { space: task_space(b) });
        // A click on a task: its space, and its chat; nothing starts.
        assert!(!m.update(Action::TaskTalk { id: a }).iter().any(|e| matches!(e, Effect::StartAgent { .. })));
        let shown = |m: &Model| m.talk.as_ref().filter(|t| t.open).and_then(|t| t.task.task());
        assert_eq!((shown(&m), m.tab_task()), (Some(a), Some(a)));
        // Another space, the drawer open: it shows that one's, starting nothing.
        assert_eq!(m.update(Action::SpaceSelect { index: 2 }), []);
        assert_eq!((shown(&m), m.agent_runs(&Subject::Task(b))), (Some(b), false));
        // A workspace of no task, and Home: no chat. Back: the drawer opens as it was.
        m.update(Action::SpaceSelect { index: 1 });
        assert!(m.talk.is_none());
        m.update(Action::SpaceSelect { index: 0 });
        assert!(m.talk.is_none());
        m.update(Action::SpaceSelect { index: 3 });
        assert_eq!(shown(&m), Some(a));
        // Closed: it stays closed.
        m.update(Action::TalkToggle);
        m.update(Action::SpaceSelect { index: 2 });
        assert_eq!((shown(&m), m.talk.as_ref().map(|t| t.task.clone())), (None, Some(Subject::Task(b))));
        // The keyboard in the drawer: a client's change of space waits; a tab change in the space does not.
        started(&mut m, Action::TaskTalk { id: a }); // starts it: the keyboard goes in
        assert_eq!(m.mode(), Mode::Talk);
        let theirs = Action::SpaceSelect { index: 2 };
        assert_eq!(m.refusal(&theirs, Origin::Socket), Some(spaces::CHAT_TYPING));
        assert_eq!(m.refusal(&Action::SelectTab { index: 0 }, Origin::Socket), Some(spaces::CHAT_TYPING));
        assert_eq!(m.refusal(&Action::SelectTab { index: m.active }, Origin::Socket), None);
        m.update(theirs.clone().sent_by(Origin::Socket));
        assert_eq!((shown(&m), m.mode()), (Some(a), Mode::Talk));
        // The user's: the keyboard goes where the user went.
        m.update(theirs);
        assert_eq!((shown(&m), m.mode()), (Some(b), Mode::Normal));
    }

    #[test]
    fn hiding_a_space_ends_nothing_and_its_row_opens_it_where_it_was() {
        let mut m = Model::default();
        term(&mut m);
        let (a, b) = (add_task(&mut m, "a", State::Captured), add_task(&mut m, "b", State::Captured));
        started(&mut m, Action::TaskTalk { id: a });
        m.update(Action::NewTab);
        term(&mut m);
        m.update(Action::SpaceOpen { space: task_space(b) });
        m.update(Action::SpaceSelect { index: 2 });
        let panes = m.panes.clone();
        // Hidden: off the row, its right neighbour selected; its tabs, panes and agent stay.
        assert_eq!(m.update(Action::SpaceHide { index: None }), []);
        assert_eq!((m.tab_task(), m.shown_spaces().len(), m.tabs.len()), (Some(b), 3, 5));
        assert_eq!((m.panes.clone(), m.agent_runs(&Subject::Task(a))), (panes, true));
        assert_eq!(row(&m)[2], (task_space(a), true, vec![1, 2]));
        // Selecting counts the row's spaces alone; cycling skips the hidden one.
        m.update(Action::SpaceSelect { index: 1 });
        m.update(Action::SpaceCycle { delta: 1 });
        assert_eq!(m.tab_task(), Some(b));
        // Home stays.
        m.update(Action::SpaceHide { index: Some(0) });
        assert!(!m.spaces()[0].hidden);
        // Its row opens it again where it was, on the tab it showed last; its chat is there.
        m.update(Action::TaskTalk { id: a });
        assert_eq!((m.space(), row(&m)[2].1, m.active, m.tabs.len()), (&task_space(a), false, 2, 5));
        assert_eq!(m.talk.as_ref().map(|t| (&t.task, t.open)), Some((&Subject::Task(a), true)));
        // A tab of a hidden space selected by its place shows it again too.
        m.update(Action::SpaceHide { index: None });
        m.update(Action::SelectTab { index: 1 });
        assert_eq!((m.space(), row(&m)[2].1), (&task_space(a), false));
    }

    #[test]
    fn a_dismissed_task_leaves_the_drawer_and_the_row_and_undo_brings_its_tabs_back() {
        let mut m = Model::default();
        term(&mut m);
        let (a, b) = (add_task(&mut m, "a", State::Captured), add_task(&mut m, "b", State::Captured));
        m.update(Action::TabPlace { tab: None, at: TabAt::End(task_space(a)) });
        started(&mut m, Action::TaskTalk { id: b });
        m.update(Action::AgentExited { task: Subject::Task(b) }.sent_by(Origin::System));
        started(&mut m, Action::TaskTalk { id: a });
        m.update(Action::AgentExited { task: Subject::Task(a) }.sent_by(Origin::System));
        // Dismissed: off the row and out of the drawer. Its tab, still on show, is the
        // workspace selected last's: b's, whose conversation the drawer is on.
        m.update(Action::RowDismiss { id: a });
        let talks = m.talk.as_ref().map(|talk| talk.task.clone());
        assert_eq!((talks, m.space(), m.spaces().len()), (Some(Subject::Task(b)), &task_space(b), 2));
        assert_eq!((m.space_tabs(&Owner::Home).len(), m.panes.len(), m.focused), (1, 1, Some(1)));
        // Taken back: its tab is its space's again.
        m.update(Action::TaskUndo);
        assert_eq!((m.tab_task(), m.spaces().len()), (Some(a), 3));
    }

    /// Review: a dismissed task's tab in a temporary workspace made for it, that workspace closed,
    /// then the dismissal undone: the task was bound to the closing workspace, kept and closing.
    #[test]
    fn a_dismissal_undone_binds_no_closing_workspace_and_keeps_its_tab() {
        let mut m = Model::default();
        term(&mut m);
        let a = add_task(&mut m, "a", State::Captured);
        m.update(Action::TabPlace { tab: None, at: TabAt::End(task_space(a)) });
        m.update(Action::TaskDismiss { id: a });
        let Owner::Workbook { id } = m.space().clone() else { panic!("{:?}", m.space()) };
        m.update(Action::SpaceHide { index: None });
        assert!(m.workbooks.closing(id));
        m.update(Action::TaskUndo);
        assert_eq!((m.workbooks.bound_to(a), m.workbooks.is_kept(id)), (None, false));
        m.update(Action::Tick { now: NOTICE_MS + 1 }.sent_by(Origin::System));
        assert_eq!((m.panes.len(), m.tabs.iter().filter(|tab| tab.space == task_space(a)).count()), (1, 1));
    }

    #[test]
    fn only_the_users_undo_links_a_dismissed_tasks_tabs_and_never_a_tab_made_since() {
        let mut m = Model::default();
        term(&mut m);
        let a = add_task(&mut m, "a", State::Captured);
        m.update(Action::TabPlace { tab: None, at: TabAt::End(task_space(a)) });
        m.update(Action::TaskDismiss { id: a });
        // Back by a state report: its tab stays the user's, in the workspace made for it.
        m.update(Action::TaskSetState { id: a, state: State::NeedsYou }.sent_by(Origin::Socket));
        assert_eq!((m.tasks.live(a).is_some(), m.tab_task()), (true, None));
        // Dismissed, every tab closed, a new tab with the same id: undo links nothing.
        m.update(Action::TabPlace { tab: None, at: TabAt::End(task_space(a)) });
        m.update(Action::TaskDismiss { id: a });
        m.update(Action::CloseTab { index: None });
        m.update(Action::NewTab);
        assert_eq!(m.tabs[0].id, 1, "the id is used again");
        m.update(Action::TaskUndo);
        assert_eq!((m.tasks.live(a).is_some(), m.tab_task()), (true, None));
    }

    #[test]
    fn dismissing_a_task_whose_agent_runs_asks_the_user_and_refuses_a_client() {
        let mut m = Model::default();
        term(&mut m);
        let a = add_task(&mut m, "a", State::Captured);
        started(&mut m, Action::TaskTalk { id: a });
        assert!(m.agent_runs(&Subject::Task(a)));
        let theirs = Action::TaskDismiss { id: a };
        assert_eq!(m.refusal(&theirs, Origin::Socket), Some(agents::USERS_ALONE));
        // The user's: "Stop its agent and dismiss?". No: nothing changes.
        m.update(Action::RowDismiss { id: a });
        assert_eq!(
            m.confirm.as_ref().map(|c| (c.dismiss, c.title())),
            Some((Some(a), "Stop its agent and dismiss?".into()))
        );
        m.update(Action::QuitCancel);
        assert_eq!((m.confirm.is_none(), m.tasks.get(a).map(|t| t.dismissed)), (true, Some(false)));
        // Yes: the agent is stopped as Stop does, and the task goes; its end does not bring it back.
        m.update(Action::RowDismiss { id: a });
        assert_eq!(m.update(Action::QuitConfirm), [Effect::StopAgent { task: Subject::Task(a) }]);
        m.update(Action::AgentExited { task: Subject::Task(a) }.sent_by(Origin::System));
        assert_eq!((m.tasks.get(a).map(|t| t.dismissed), m.spaces().len(), m.confirm.is_none()), (Some(true), 2, true));
        // A done task's Clear, confirmed: its notice says Cleared.
        m.update(Action::TaskUndo);
        started(&mut m, Action::TaskTalk { id: a });
        m.update(Action::TaskSetState { id: a, state: State::Done });
        assert!(m.agent_runs(&Subject::Task(a)) && m.done_row(a));
        m.update(Action::RowDismiss { id: a });
        m.update(Action::QuitConfirm);
        assert_eq!(m.undo_offer.map(|n| n.moved), Some(Moved::Cleared));
    }

    #[test]
    fn list_mode_moves_over_the_rows_and_opens_one() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: listed() });
        // With no section open the bar opens on Apps; on an open one it stays there.
        m.update(Action::FocusList);
        assert_eq!((m.mode(), m.sidebar), (Mode::List, Some(Section::Apps)));
        m.update(Action::FocusList);
        m.update(Action::ToggleSection { section: Section::Repos });
        m.update(Action::FocusList);
        // The repository's name is a row, over its checkouts; the list starts on the first checkout.
        assert_eq!((m.mode(), m.sidebar, m.list), (Mode::List, Some(Section::Repos), Some(1)));
        let rows = [
            ListRow::RepoHead("/code/app".into()),
            ListRow::Repo("/code/app".into()),
            ListRow::Repo("/code/app-2".into()),
        ];
        assert_eq!(m.list_rows(), rows);
        m.update(Action::ListMove { delta: -2 }); // wraps to the last row
        assert_eq!(m.list, Some(2));
        // Opening the row: a terminal in the worktree, and the keyboard goes to it.
        assert_eq!(m.update(Action::ListChoose { axis: Down }), [Effect::Opened(1)]);
        assert_eq!((m.pane(1).unwrap().cwd.as_deref(), m.mode()), (Some("/code/app-2"), Mode::Normal));
    }

    #[test]
    fn list_mode_acts_on_the_selected_task() {
        let mut m = Model::default();
        m.update(Action::NewTab);
        let second = m.tabs[1].id;
        m.update(Action::SelectTab { index: 0 });
        for (title, tab) in [("a", Some(second)), ("b", None), ("c", None)] {
            m.update(Action::TaskAdd {
                title: title.into(),
                priority: 1,
                state: State::NeedsYou,
                tab,
                assign: Assign::default(),
            });
        }
        m.update(Action::ToggleSection { section: Section::Tasks });
        m.update(Action::FocusList);
        let (heading, task) = (ListRow::Heading, ListRow::Task);
        // The headings are rows too; the selection starts on the first task. "a" has a tab, and
        // stays under Needs you with the others.
        assert_eq!((m.list_rows(), m.list), (vec![heading(Heading::NeedsYou), task(1), task(2), task(3)], Some(1)));
        // Dismiss the second task: the selection stays at its place, now on the next task.
        m.update(Action::ListMove { delta: 1 });
        m.update(Action::ListDismiss);
        assert_eq!((m.list_rows(), m.list), (vec![heading(Heading::NeedsYou), task(1), task(3)], Some(2)));
        // Hold it: it goes under Later, and the heading that came is under the selection. The
        // task keys do nothing on a heading.
        m.update(Action::ListHold);
        let held = vec![heading(Heading::NeedsYou), task(1), heading(Heading::Later), task(3)];
        assert_eq!((m.list_rows(), m.list), (held.clone(), Some(2)));
        m.update(Action::ListSnooze { until: 9 });
        assert_eq!(m.list_rows(), held);
        // Snooze it: gone with its heading, and the selection moves up to a row that is there.
        m.update(Action::ListMove { delta: 1 });
        m.update(Action::ListSnooze { until: 9 });
        assert_eq!((m.list_rows(), m.list), (vec![heading(Heading::NeedsYou), task(1)], Some(1)));
        m.update(Action::TaskUndo);
        assert_eq!(m.tasks.get(3).map(|t| (t.state, t.snoozed_until)), Some((State::Parked, None)));
        // ↵ on a task shows its space and its chat, starting nothing.
        assert_eq!(m.update(Action::ListChoose { axis: Right }), []);
        let shown = (m.tab_task(), m.mode(), m.talk.as_ref().and_then(|talk| talk.task.task()));
        assert_eq!(shown, (Some(1), Mode::Normal, Some(1)));
    }

    #[test]
    fn the_selection_follows_its_task_when_others_change_the_inbox() {
        let mut m = Model::default();
        for title in ["a", "b", "c"] {
            m.update(Action::TaskAdd {
                title: title.into(),
                priority: 2,
                state: State::NeedsYou,
                tab: None,
                assign: Assign::default(),
            });
        }
        m.update(Action::ToggleSection { section: Section::Tasks });
        m.update(Action::FocusList);
        m.update(Action::ListMove { delta: 1 }); // on b
        // An agent files a more urgent task above, and another task leaves: still on b.
        m.update(Action::TaskAdd {
            title: "urgent".into(),
            priority: 1,
            state: State::NeedsYou,
            tab: None,
            assign: Assign::default(),
        });
        assert_eq!((m.list, m.list_rows()[3].clone()), (Some(3), ListRow::Task(2)));
        m.update(Action::TaskSetState { id: 1, state: State::Cleaned });
        assert_eq!(m.list, Some(2));
        // The user's own hold keeps the place: the next task (c) comes under the selection.
        m.update(Action::ListHold);
        assert_eq!((m.list, m.list_rows()[2].clone()), (Some(2), ListRow::Task(3)));
        // The selected task is taken away by someone else: the selection stays on a row.
        m.update(Action::TaskSetState { id: 3, state: State::Cleaned });
        assert_eq!((m.list, m.list_rows()[2].clone()), (Some(2), ListRow::Heading(Heading::Later)));
        // ↵ shows the task's conversation and the list gives up the keyboard; its start goes in.
        m.update(Action::ListMove { delta: 1 });
        m.update(Action::ListChoose { axis: Right });
        m.update(Action::TalkStart);
        assert_eq!(
            (m.mode(), m.tab_task(), m.talk.as_ref().and_then(|talk| talk.task.task())),
            (Mode::Talk, Some(2), Some(2))
        );
    }

    #[test]
    fn list_mode_changes_section_hosts_apps_and_ends_with_the_bar() {
        let mut m = Model::default();
        m.update(Action::SetApps { names: vec!["Notes".into(), "Safari".into()] });
        m.update(Action::ToggleSection { section: Section::Repos });
        m.update(Action::FocusList);
        m.update(Action::ListSection { delta: -1 }); // Repos is first: before it, Marks, with no rows yet
        assert_eq!((m.sidebar, m.list_rows()), (Some(Section::Marks), vec![]));
        m.update(Action::ListSection { delta: 3 }); // then Repos again, Tasks, and Apps
        m.update(Action::ListMove { delta: 1 });
        assert_eq!((m.sidebar, m.list), (Some(Section::Apps), Some(1)));
        // The shell hosts the app; until it opens a pane, the list keeps the keyboard.
        let host = Effect::HostApp { name: "Safari".into(), axis: Right, new_tab: false };
        assert_eq!((m.update(Action::ListChoose { axis: Right }), m.mode()), (vec![host], Mode::List));
        // ⇧Tab: Apps, then Tasks. Nothing to move to or open there.
        m.update(Action::ListSection { delta: -1 });
        m.update(Action::ListMove { delta: 1 });
        assert_eq!(
            (m.sidebar, m.list, m.update(Action::ListChoose { axis: Right })),
            (Some(Section::Tasks), Some(0), vec![])
        );
        // Closing the bar, or a click on a pane, ends list mode. A second FocusList leaves too.
        m.update(Action::CloseSidebar);
        assert_eq!((m.mode(), m.list), (Mode::Normal, None));
        m.update(Action::FocusList);
        m.update(Action::FocusList);
        assert_eq!((m.mode(), m.sidebar), (Mode::Normal, Some(Section::Apps)));
        // Not behind the picker.
        m.update(Action::OpenPicker { axis: Right, new_tab: false, items: vec![PickItem::Terminal] });
        m.update(Action::FocusList);
        assert_eq!(m.mode(), Mode::Pick);
        m.update(Action::ClosePicker);
        assert_eq!(m.list, None);
    }

    #[test]
    fn the_new_task_box_files_a_line_as_a_task() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: listed() });
        term(&mut m);
        m.update(Action::OpenCompose { text: String::new() });
        assert_eq!(m.mode(), Mode::Compose);
        // It has the keyboard: a split waits, and the picker does not open over it.
        m.update(Action::Split { axis: Right, kind: Kind::Empty });
        m.update(Action::OpenPicker { axis: Right, new_tab: false, items: vec![PickItem::Terminal] });
        assert_eq!((m.panes.len(), m.mode()), (1, Mode::Compose));
        // ↵ on an empty line files nothing and keeps the box.
        m.update(Action::ComposeSubmit { open: false });
        assert_eq!((m.tasks.list.len(), m.mode()), (0, Mode::Compose));
        // Tab finishes the repository being typed; the name need not match in case.
        m.update(Action::FieldEdit { edit: Edit::Insert("fix zoom #Canvas >AP".into()) });
        assert_eq!(offered(&m), ["app", "app-2"], "worktrees too");
        m.update(Action::ComposeComplete);
        m.update(Action::FieldEdit { edit: Edit::Insert("p1x".into()) });
        m.update(Action::FieldEdit { edit: Edit::Delete { to: Motion::Left } });
        assert_eq!(m.compose.as_ref().map(Field::text), Some("fix zoom #Canvas >app p1"));
        // Tab finishes the word at the cursor, not the end of the line; ⌘Z takes both steps back.
        m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::Start, select: false } });
        m.update(Action::FieldEdit { edit: Edit::Insert(">a ".into()) });
        m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::Left, select: false } });
        m.update(Action::ComposeComplete);
        assert_eq!(m.field().map(|(of, field)| (of, field.text())), Some(("compose", ">app fix zoom #Canvas >app p1")));
        m.update(Action::FieldEdit { edit: Edit::Undo });
        m.update(Action::FieldEdit { edit: Edit::Undo });
        assert_eq!(m.compose_line().map(String::as_str), Some("fix zoom #Canvas >app p1"));
        // Inside a word, Tab replaces the whole word, not only what is before the cursor.
        m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::End, select: false } });
        for _ in 0..5 {
            m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::Left, select: false } });
        }
        m.update(Action::ComposeComplete);
        assert_eq!(m.field().map(|(_, field)| (field.text(), field.cursor())), Some(("fix zoom #Canvas >app p1", 22)));
        // Under the key reference the line is hidden: it has no keyboard, and nothing edits it.
        m.keys = true;
        m.update(Action::FieldEdit { edit: Edit::Insert("x".into()) });
        assert_eq!((m.field(), m.open_field().map(|(of, _)| of)), (None, Some("compose")));
        m.keys = false;
        assert_eq!(m.compose_line().map(String::as_str), Some("fix zoom #Canvas >app p1"));
        m.update(Action::ComposeSubmit { open: false });
        let task = &m.tasks.list[0];
        assert_eq!((task.title.as_str(), task.state, task.priority), ("fix zoom", State::Captured, 1));
        assert_eq!(
            (task.project.as_deref(), task.repo.as_deref(), m.mode()),
            (Some("Canvas"), Some("/code/app"), Mode::Normal)
        );
        // A project already used is suggested; an unknown repository stays in the title.
        m.update(Action::OpenCompose { text: "look #c".into() });
        assert_eq!(offered(&m), ["Canvas"]);
        m.update(Action::CloseCompose);
        m.update(Action::TaskFromLine { line: "ask @ana about >app-2".into(), known: Default::default(), open: false });
        assert_eq!(
            (m.tasks.list[1].title.as_str(), m.tasks.list[1].repo.as_deref()),
            ("ask @ana about", Some("/code/app-2"))
        );
        // The box holds no more than a title may: a longer task could not be read back.
        m.update(Action::OpenCompose { text: "x".repeat(MAX_TITLE + 50) });
        m.update(Action::FieldEdit { edit: Edit::Insert("yz".into()) });
        assert_eq!(m.compose.as_ref().map(|line| line.text().chars().count()), Some(MAX_TITLE));
        m.update(Action::CloseCompose);
        m.update(Action::TaskFromLine { line: "x".repeat(MAX_TITLE + 1), known: Default::default(), open: false });
        assert_eq!(m.tasks.list.len(), 2);
        // The picker may open again over itself, but not over the box; a dead pane closes behind either.
        m.update(Action::OpenPicker { axis: Right, new_tab: false, items: vec![PickItem::Terminal] });
        m.update(Action::OpenPicker { axis: Right, new_tab: true, items: vec![PickItem::Terminal] });
        assert_eq!(m.picker.as_ref().map(|p| p.new_tab), Some(true));
        m.update(Action::ClosePicker);
        m.update(Action::OpenCompose { text: String::new() });
        assert_eq!(m.update(Action::Close { pane: Some(1) }).len(), 1);
        m.update(Action::CloseCompose);
        // Not under the key reference.
        m.update(Action::ToggleKeys);
        m.update(Action::OpenCompose { text: String::new() });
        assert_eq!(m.compose, None);
    }

    fn keys(m: &mut Model, text: &str) {
        for c in text.chars() {
            m.update(Action::FieldEdit { edit: Edit::Insert(c.to_string()) });
        }
    }

    fn line(m: &Model) -> &str {
        m.compose_line().map_or("<closed>", String::as_str)
    }

    /// A box over one terminal, with two repositories, two agents, a skill and three projects.
    fn composing() -> Model {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: listed() });
        term(&mut m);
        for line in ["a #canvas", "b #canvas", "c #Cables", "d #flow-canvas"] {
            m.update(Action::TaskFromLine { line: line.into(), known: Default::default(), open: false });
        }
        m.update(Action::OpenCompose { text: String::new() });
        let names = compose::Names { agents: vec!["claude".into(), "codex".into()], skills: vec!["deploy".into()] };
        let known =
            Action::SetKnown { line: String::new(), typing: None, names: Some(names), paths: vec![], entries: vec![] };
        m.update(known);
        m
    }

    #[test]
    fn the_dropdown_opens_in_a_tag_and_its_keys_take_or_leave_a_row() {
        let mut m = composing();
        let shown = |m: &Model| m.dropdown().map(|menu| (menu.mark, offered(m), menu.selected, menu.note));
        // No tag at the cursor: no dropdown, and ↑ ↓ are the line's ends.
        keys(&mut m, "fix zoom");
        m.update(Action::ComposeMove { delta: -1 });
        assert_eq!((shown(&m), m.field().map(|(_, f)| f.cursor())), (None, Some(0)));
        m.update(Action::ComposeMove { delta: 1 });
        // A bare mark lists what there is, the project with the most tasks first, and
        // highlights the first: ↵ would take it.
        keys(&mut m, " #");
        let all = vec!["canvas".to_string(), "Cables".into(), "flow-canvas".into()];
        assert_eq!(shown(&m), Some(('#', all, Some(0), None)));
        // A letter narrows. Matches at the start come first.
        keys(&mut m, "ca");
        let rows = m.dropdown().unwrap().rows;
        assert_eq!(shown(&m), Some(('#', vec!["canvas".into(), "Cables".into(), "flow-canvas".into()], Some(0), None)));
        assert_eq!((rows[0].kind, rows[0].detail.as_str(), &rows[0].matched), ("project", "2 tasks", &vec![0, 1]));
        assert_eq!(rows[2].matched, [5, 6], "the letters matched are told, for the shell to draw them stronger");
        // ↓ and ↑ move and wrap; typing more keeps to the rows that are left.
        m.update(Action::ComposeMove { delta: 1 });
        m.update(Action::ComposeMove { delta: 1 });
        m.update(Action::ComposeMove { delta: 1 });
        m.update(Action::ComposeMove { delta: -1 });
        assert_eq!(m.dropdown().unwrap().selected, Some(2));
        keys(&mut m, "b");
        assert_eq!(shown(&m), Some(('#', vec!["Cables".into()], Some(0), None)));
        // ↵ on a highlighted row takes it and adds no task. The box stays; the dropdown is gone.
        m.update(Action::ComposeSubmit { open: false });
        assert_eq!((line(&m), shown(&m), m.tasks.list.len()), ("fix zoom #Cables ", None, 4));
        // Tab takes the highlighted row, or the first when none is.
        keys(&mut m, ">");
        m.update(Action::ComposeComplete);
        assert_eq!(line(&m), "fix zoom #Cables >app ");
        // Esc closes the dropdown and keeps the box; ↵ then adds, with the word as typed.
        keys(&mut m, "@co");
        m.update(Action::ComposeEscape);
        assert_eq!((shown(&m), m.mode()), (None, Mode::Compose));
        m.update(Action::ComposeMove { delta: 1 });
        assert_eq!(shown(&m), None, "closed, it does not take ↓");
        // Typing on opens it again; a second Esc, with it closed, closes the box.
        keys(&mut m, "d");
        assert_eq!(offered(&m), ["codex"]);
        m.update(Action::ComposeEscape);
        m.update(Action::ComposeEscape);
        assert_eq!(m.mode(), Mode::Normal);
    }

    #[test]
    fn the_agent_dropdown_offers_each_runner_and_its_models() {
        let mut m = composing();
        let agents = crate::agents::names(&Default::default(), vec!["ana".into()]);
        let names = compose::Names { agents, skills: Vec::new() };
        m.update(Action::SetKnown {
            line: String::new(),
            typing: None,
            names: Some(names),
            paths: vec![],
            entries: vec![],
        });
        keys(&mut m, "fix @");
        let rows = m.dropdown().unwrap().rows;
        let details: Vec<&str> = rows.iter().map(|row| row.detail.as_str()).collect();
        assert_eq!(offered(&m)[..3], ["claude", "claude-fable-5-2", "claude-opus-5-5"]);
        assert_eq!(
            (details[0], details[1], details[6], details[7]),
            ("runner", "claude model", "codex model", "saved agent")
        );
        // A word of the name finds it: `opus`, `gpt`.
        keys(&mut m, "opus");
        assert_eq!(offered(&m), ["claude-opus-5-5"]);
        m.update(Action::ComposeComplete);
        // A model that is not listed is a tag as typed.
        keys(&mut m, "@codex-gpt-7");
        assert_eq!(offered(&m), Vec::<String>::new());
        m.update(Action::ComposeSubmit { open: false });
        let task = m.tasks.list.last().unwrap();
        assert_eq!((task.title.as_str(), task.agent.as_deref()), ("fix", Some("codex-gpt-7")));
        assert_eq!(m.task_tags(task), "@codex-gpt-7");
    }

    #[test]
    fn enter_adds_the_task_unless_a_row_would_change_the_line() {
        // A name typed in full: its row is highlighted, but there is nothing to take. ↵ adds.
        let mut m = composing();
        keys(&mut m, "fix #canvas");
        assert_eq!(m.dropdown().and_then(|menu| menu.selected), Some(0));
        m.update(Action::ComposeSubmit { open: false });
        assert_eq!((m.mode(), m.tasks.list[4].project.as_deref()), (Mode::Normal, Some("canvas")));
        // A name nobody has: no rows, nothing is highlighted. ↵ adds.
        for text in ["fix #brand-new", "fix @nobody"] {
            m.update(Action::OpenCompose { text: text.into() });
            let note = m.dropdown().and_then(|menu| menu.note);
            assert_eq!(note.as_deref(), Some(if text.ends_with('w') { "new project" } else { "no match" }));
            m.update(Action::ComposeSubmit { open: false });
            assert_eq!(m.mode(), Mode::Normal, "{text}");
        }
        // ⌘↵ adds whatever is highlighted.
        m.update(Action::OpenCompose { text: "fix #ca".into() });
        m.update(Action::ComposeSubmit { open: true });
        assert_eq!(
            (
                m.compose_line(),
                m.tasks.list.last().filter(|t| t.project.as_deref() == Some("ca")).map(|t| t.title.as_str())
            ),
            (None, Some("fix"))
        );
        // A space after a name that is a row's takes the row, spelled as it is kept.
        m.update(Action::OpenCompose { text: "fix #CABLES".into() });
        keys(&mut m, " ");
        assert_eq!(line(&m), "fix #Cables ");
        keys(&mut m, "#cab ");
        assert_eq!(line(&m), "fix #Cables #cab ", "part of a name is not the name");
        // A click takes its row; a row that is not there takes nothing.
        keys(&mut m, "@c");
        m.update(Action::ComposeAccept { index: 9 });
        m.update(Action::ComposeAccept { index: 1 });
        assert_eq!(line(&m), "fix #Cables #cab @codex ");
        // Inside a line the whole word goes, and the cursor leaves the tag past the space there.
        m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::Start, select: false } });
        m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::WordRight, select: false } });
        keys(&mut m, " >a");
        m.update(Action::ComposeComplete);
        assert_eq!(
            (line(&m), m.field().map(|(_, f)| f.cursor()), m.dropdown()),
            ("fix >app #Cables #cab @codex ", Some(9), None)
        );
        // A selection, or the key reference over the box: no dropdown.
        keys(&mut m, "#c");
        m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::Left, select: true } });
        assert_eq!(m.dropdown(), None);
        m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::Right, select: false } });
        m.keys = true;
        assert_eq!(m.dropdown(), None);
    }

    #[test]
    fn a_folder_taken_from_the_dropdown_keeps_it_open_on_what_is_inside() {
        let mut m = composing();
        // The shell lists a folder: the core narrows its entries to what is typed.
        let read = |m: &mut Model, folder: &str, entries: &[&str]| {
            let (line, entries) = (m.compose_line().cloned().unwrap(), entries.iter().map(|e| e.to_string()).collect());
            m.update(Action::SetKnown {
                line,
                typing: Some((folder.into(), folder.replace('~', "/Users/me"))),
                names: None,
                paths: vec![],
                entries,
            });
        };
        keys(&mut m, "see /src/ex");
        // Not read yet: no dropdown, not "no match". The shell is asked for the folder.
        assert_eq!((m.dropdown(), m.compose_typing().as_deref()), (None, Some("/src/")));
        read(&mut m, "/src/", &["/src/export/", "/src/extra.rs", "/src/main.rs"]);
        let menu = m.dropdown().unwrap();
        assert_eq!((menu.rows[0].kind, menu.rows[1].kind, &menu.rows[0].matched), ("folder", "file", &vec![5, 6]));
        // Typed on in the same folder: the rows narrow at once, and nothing is read again.
        keys(&mut m, "p");
        assert_eq!((offered(&m), m.compose_typing()), (vec!["/src/export/".to_string()], None));
        // An answer for a folder no longer typed is dropped.
        read(&mut m, "/elsewhere/", &["/elsewhere/x/"]);
        assert_eq!(offered(&m), ["/src/export/"]);
        m.update(Action::ComposeSubmit { open: false });
        assert_eq!(line(&m), "see /src/export/");
        // While the folder taken is read, the rows shown stay, and none can be taken.
        let menu = m.dropdown().unwrap();
        assert_eq!((menu.stale, menu.selected, offered(&m)), (true, None, vec!["/src/export/".to_string()]));
        m.update(Action::ComposeComplete);
        m.update(Action::ComposeEnter);
        assert_eq!((line(&m), m.enter()), ("see /src/export/", Enter::Wait), "↵ waits: it adds no half-read path");
        // Its entries arrive; nothing of a name is typed, so none is highlighted.
        read(&mut m, "/src/export/", &["/src/export/My Notes/", "/src/export/a.rs"]);
        assert_eq!((offered(&m).len(), m.dropdown().unwrap().selected), (2, None));
        m.update(Action::ComposeMove { delta: 1 });
        m.update(Action::ComposeComplete);
        assert_eq!(line(&m), r"see /src/export/My\ Notes/");
        read(&mut m, "/src/export/My Notes/", &[]);
        assert_eq!(m.dropdown().and_then(|menu| menu.note).as_deref(), Some("no match"));
        // A folder typed in full, without its last `/`: its row is highlighted, but ↵ adds.
        m.update(Action::FieldEdit { edit: Edit::Delete { to: Motion::Left } });
        read(&mut m, "/src/export/", &["/src/export/My Notes/", "/src/export/a.rs"]);
        assert_eq!(m.dropdown().and_then(|menu| menu.selected), Some(0));
        m.update(Action::ComposeSubmit { open: false });
        assert_eq!(
            (m.mode(), m.tasks.list.last().map(|task| task.title.as_str())),
            (Mode::Normal, Some(r"see /src/export/My\ Notes"))
        );
    }

    #[test]
    fn a_path_moved_along_keeps_its_rows_and_highlight_and_says_how_many_more() {
        let mut m = composing();
        let read = |m: &mut Model, folder: &str, entries: Vec<String>| {
            let line = m.compose_line().cloned().unwrap();
            m.update(Action::SetKnown {
                line,
                typing: Some((folder.into(), folder.replace('~', "/Users/me"))),
                names: None,
                paths: vec![],
                entries,
            });
        };
        keys(&mut m, "plan ~");
        let many: Vec<String> = (0..12).map(|n| format!("~/n{n:02}/")).chain(["~/notes.md".into()]).collect();
        read(&mut m, "~/", many);
        // At most eight rows, and how many more.
        let menu = m.dropdown().unwrap();
        assert_eq!((menu.rows.len(), menu.note.as_deref()), (complete::MAX_ROWS, Some("… 5 more")));
        // ↓ to a row; typing on keeps it while it is still there; one no longer there moves nothing.
        keys(&mut m, "/n");
        m.update(Action::ComposeMove { delta: 1 });
        assert_eq!(m.dropdown().and_then(|menu| menu.selected), Some(1));
        keys(&mut m, "0");
        assert_eq!((m.dropdown().and_then(|menu| menu.selected), offered(&m)[1].as_str()), (Some(1), "~/n01/"));
        keys(&mut m, "5");
        assert_eq!(m.dropdown().and_then(|menu| menu.selected), Some(0));
        // Out of the path, its rows are gone: none comes back for the next path.
        keys(&mut m, " and /");
        assert_eq!(m.dropdown(), None);
    }

    #[test]
    fn a_relative_path_completes_only_in_a_repository() {
        let mut m = composing();
        keys(&mut m, "fix ./sr");
        assert_eq!((m.compose_typing(), m.dropdown()), (None, None));
        m.update(Action::CloseCompose);
        m.update(Action::OpenCompose { text: "fix >app ./sr".into() });
        assert_eq!(m.compose_typing().as_deref(), Some("./"));
        let line = m.compose_line().cloned().unwrap();
        let entries = vec!["./src/".to_string()];
        m.update(Action::SetKnown {
            line,
            typing: Some(("./".into(), "/code/app".into())),
            names: None,
            paths: vec![],
            entries,
        });
        assert_eq!((offered(&m), m.compose_typing()), (vec!["./src/".to_string()], None));
        // Another repository named: what was listed in the first is not offered as its own.
        for _ in "./sr".chars() {
            m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::Left, select: false } });
        }
        keys(&mut m, ">app-2 ");
        m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::End, select: false } });
        assert_eq!(m.compose_typing().as_deref(), Some("./"), "{:?}", m.compose_line());
        assert!(m.dropdown().is_none_or(|menu| menu.stale), "{:?}", m.dropdown());
        // Prose with a `/` in it opens nothing and asks for nothing.
        for prose in ["fix and/or", "due 11/14", "see https://x.io/a"] {
            m.update(Action::CloseCompose);
            m.update(Action::OpenCompose { text: prose.into() });
            assert_eq!((m.compose_typing(), m.dropdown()), (None, None), "{prose}");
        }
    }

    #[test]
    fn a_folder_the_user_takes_is_where_the_agent_runs() {
        let mut m = composing();
        let read = |m: &mut Model, folder: &str, entries: &[&str], paths: Vec<compose::PathFound>| {
            let (line, entries) = (m.compose_line().cloned().unwrap(), entries.iter().map(|e| e.to_string()).collect());
            m.update(Action::SetKnown {
                line,
                typing: Some((folder.into(), folder.replace('~', "/Users/me"))),
                names: None,
                paths,
                entries,
            });
        };
        let found = |typed: &str| compose::PathFound { typed: typed.into(), resolved: "/Users/me/notes/".into() };
        keys(&mut m, "help me plan my next week ~/no");
        read(&mut m, "~/", &["~/notes/", "~/notes.md"], vec![]);
        // A client's Tab finishes the word, and picks no folder.
        m.update(Action::ComposeComplete.sent_by(Origin::Socket));
        assert_eq!((line(&m), m.compose_folder()), ("help me plan my next week ~/notes/", None));
        m.update(Action::CloseCompose);
        m.update(Action::OpenCompose { text: String::new() });
        keys(&mut m, "help me plan my next week ~/no");
        read(&mut m, "~/", &["~/notes/", "~/notes.md"], vec![]);
        m.update(Action::ComposeComplete.sent_by(Origin::User));
        assert_eq!(m.compose_folder(), Some("~/notes/"));
        keys(&mut m, " folder");
        // ↵ will start the agent there; the path stays in the title as typed.
        assert_eq!(m.compose_plan().and_then(|plan| plan.dir).as_deref(), Some("~/notes/"));
        let said = "↵ starts @claude in ~/notes/, in this workspace · ⇧↵ later · Esc";
        assert_eq!(m.compose_status().as_deref(), Some(said));
        // ↵ at once, before the shell read the line again: the folder is where its listing was.
        m.update(Action::ComposeSubmit { open: false });
        let task = m.tasks.list.last().unwrap();
        assert_eq!(task.title, "help me plan my next week ~/notes/ folder");
        assert_eq!(
            (task.folder.as_deref(), task.dir().map(String::as_str)),
            (Some("/Users/me/notes"), Some("/Users/me/notes"))
        );
        // The × takes the folder off, and the line keeps the path. Edited away, it is gone too.
        m.update(Action::OpenCompose { text: String::new() });
        keys(&mut m, "x ~/no");
        read(&mut m, "~/", &["~/notes/"], vec![]);
        m.update(Action::ComposeComplete.sent_by(Origin::User));
        m.update(Action::ComposeFolderClear);
        assert_eq!((line(&m), m.compose_folder()), ("x ~/notes/", None));
        m.update(Action::CloseCompose);
        m.update(Action::OpenCompose { text: String::new() });
        keys(&mut m, "x ~/no");
        read(&mut m, "~/", &["~/notes/"], vec![]);
        m.update(Action::ComposeComplete.sent_by(Origin::User));
        keys(&mut m, "a");
        assert_eq!(m.compose_folder(), None, "~/notes/a is not the folder taken");
        // A path typed out, never taken: the agent runs in the home folder.
        m.update(Action::CloseCompose);
        m.update(Action::OpenCompose { text: "y ~/notes/".into() });
        read(&mut m, "~/notes/", &[], vec![found("~/notes/")]);
        m.update(Action::ComposeSubmit { open: true });
        assert_eq!(
            m.tasks.list.last().map(|task| (task.title.as_str(), task.folder.is_none())),
            Some(("y ~/notes/", true))
        );
    }

    #[test]
    fn the_tags_understood_are_told_with_where_they_are() {
        let mut m = composing();
        keys(&mut m, "fix #canvas ");
        keys(&mut m, ">app ");
        keys(&mut m, ">web @claude p2, $nope");
        let marks: Vec<(char, &str)> =
            m.compose_spans().iter().map(|span| (span.mark, &line(&m)[span.range.clone()])).collect();
        assert_eq!(marks, [('#', "#canvas"), ('>', ">app"), ('@', "@claude"), ('p', "p2,")]);
    }

    #[test]
    fn files_go_in_as_path_words_at_the_cursor() {
        let mut m = composing();
        keys(&mut m, "read now");
        m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::WordLeft, select: false } });
        let paths = vec!["/Users/me/My Notes/a b.md".to_string(), "/etc/hosts".into(), "relative".into()];
        m.update(Action::ComposeAttach { paths: paths.clone(), home: Some("/Users/me".into()), unreadable: 0 });
        // Inside the home folder: `~/`. A space gets a backslash. Not a path: left out.
        assert_eq!(line(&m), r"read ~/My\ Notes/a\ b.md /etc/hosts now");
        assert_eq!(compose::path_words(line(&m)), [vec!["~/My Notes/a b.md"], vec!["/etc/hosts"]]);
        // One step to undo; a word is added after a word.
        m.update(Action::FieldEdit { edit: Edit::Undo });
        m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::End, select: false } });
        m.update(Action::ComposeAttach {
            paths: paths[1..2].to_vec(),
            home: Some("/Users/meadow".into()),
            unreadable: 0,
        });
        assert_eq!(line(&m), "read now /etc/hosts ");
        // No room for all of it: none goes in. No box: nothing happens.
        let long = vec![format!("/{}", "x".repeat(MAX_TITLE))];
        m.update(Action::ComposeAttach { paths: long.clone(), home: None, unreadable: 0 });
        assert_eq!(line(&m), "read now /etc/hosts ");
        m.update(Action::CloseCompose);
        m.update(Action::ComposeAttach { paths: long, home: None, unreadable: 0 });
        assert_eq!(m.compose, None);
    }

    #[test]
    fn a_reference_names_what_is_open_and_is_kept_as_it_was() {
        let mut m = Model::default();
        // Two tabs of one title; a terminal in a repository running vim; an app pane.
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        m.update(Action::Open { kind: app(7), axis: Right, beside: None });
        m.update(Action::NewTab);
        m.tabs[1].title = m.tabs[0].title.clone();
        m.update(Action::SelectTab { index: 0 });
        let info =
            TerminalInfo { pane: 1, cwd: Some("/code/flow app".into()), program: Some("vim".into()), shell: None };
        m.update(Action::SetTerminals { terminals: vec![info], home: Some("/code".into()) });
        let sketch = Installed { name: "Sketchpad".into(), path: "/Applications/Sketchpad.app".into() };
        m.update(Action::SetInstalled { apps: vec![sketch], running: Vec::new() });
        m.update(Action::OpenCompose { text: "compare ^".into() });
        let rows = m.dropdown().unwrap().rows;
        let shown: Vec<(&str, &str, &str)> =
            rows.iter().map(|r| (r.kind, r.name.as_str(), r.detail.as_str())).collect();
        assert_eq!(
            shown,
            [
                ("tab", "Tab 1", "tab · 2 panes"),
                ("tab", "Tab 1-2", "tab · 0 panes"),
                ("pane", "flow app", "terminal · vim · ~/flow app"),
                ("pane", "app", "app pane · w7"),
                ("app", "Sketchpad", "app · not running"),
            ]
        );
        // Taken from the dropdown, a space in the name gets a backslash.
        keys(&mut m, "fl");
        m.update(Action::ComposeComplete);
        assert_eq!(line(&m), r"compare ^flow\ app ");
        // ⌥-click on a tab and on a pane: each goes in at the cursor; one that is gone does not.
        m.update(Action::ComposeRef { target: Pointed::Tab(m.tabs[1].id) });
        m.update(Action::ComposeRef { target: Pointed::Pane(2) });
        m.update(Action::ComposeRef { target: Pointed::Pane(99) });
        keys(&mut m, "^Sketchpad ^nothing");
        assert_eq!(line(&m), r"compare ^flow\ app ^Tab\ 1-2 ^app ^Sketchpad ^nothing");
        let marks: Vec<char> = m.compose_spans().iter().map(|span| span.mark).collect();
        assert_eq!(marks, ['^', '^', '^', '^']);
        // The terminal closes before the task is added: its reference is kept as it was.
        m.update(Action::Close { pane: Some(1) });
        m.update(Action::ComposeEscape);
        m.update(Action::ComposeSubmit { open: false });
        let task = m.tasks.list.last().unwrap();
        assert_eq!(task.title, "compare ^nothing");
        let kept: Vec<(RefKind, &str, Option<u32>)> =
            task.refs.iter().map(|r| (r.kind, r.name.as_str(), r.id)).collect();
        assert_eq!(
            kept,
            [
                (RefKind::Pane, "flow app", Some(1)),
                (RefKind::Tab, "Tab 1-2", Some(m.tabs[1].id)),
                (RefKind::Pane, "app", Some(2)),
                (RefKind::App, "Sketchpad", None)
            ]
        );
        assert_eq!(
            (task.refs[0].cwd.as_deref(), task.refs[0].program.as_deref()),
            (Some("/code/flow app"), Some("vim"))
        );
        assert_eq!(task.refs[3].bundle.as_deref(), Some("/Applications/Sketchpad.app"));
        assert_eq!(m.task_tags(task), "4 references");
        // Kept in the task's file, and read back; a task from before has none.
        let json = serde_json::to_value(task).unwrap();
        assert_eq!(
            json["refs"][1],
            serde_json::json!({"kind": "tab", "name": "Tab 1-2", "id": m.tabs[1].id, "title": "Tab 1"})
        );
        let back: Task = serde_json::from_value(json).unwrap();
        assert_eq!(&back, task);
        let old: Task = serde_json::from_str(r#"{"id":1,"title":"x","state":"captured"}"#).unwrap();
        assert!(old.refs.is_empty());
        // From the socket's line: what is open by that name now.
        m.update(Action::TaskFromLine {
            line: "look at ^app ^flow\\ app".into(),
            known: Default::default(),
            open: false,
        });
        let task = m.tasks.list.last().unwrap();
        assert_eq!((task.title.as_str(), task.refs.len()), (r"look at ^flow\ app", 1));
    }

    #[test]
    fn taking_a_row_never_loses_what_is_typed() {
        // A space typed inside a word is a space: the row is not taken, and nothing after
        // the cursor goes.
        let mut m = composing();
        keys(&mut m, "do #cablesfix the bug");
        for _ in 0.."fix the bug".len() {
            m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::Left, select: false } });
        }
        assert_eq!(offered(&m), ["Cables"]);
        keys(&mut m, " ");
        assert_eq!(line(&m), "do #cables fix the bug");
        // At the end of the word it takes the row.
        m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::Left, select: false } });
        keys(&mut m, " ");
        assert_eq!(line(&m), "do #Cables fix the bug");
        m.update(Action::CloseCompose);

        // A line with no room for the name: the row is not taken in part. Tab and ↵ say so and
        // leave the line; after Esc ↵ adds the task with what is typed.
        let full = format!("{} #ca", "x".repeat(MAX_TITLE - 4));
        m.update(Action::OpenCompose { text: full.clone() });
        assert_eq!(
            (offered(&m), m.dropdown().unwrap().selected),
            (vec!["canvas".into(), "Cables".into(), "flow-canvas".into()], Some(0))
        );
        m.update(Action::ComposeComplete);
        assert_eq!((line(&m), m.compose_note()), (full.as_str(), Some("no room in the line for that name")));
        m.update(Action::ComposeAccept { index: 1 });
        assert_eq!(line(&m), full);
        // The note goes with the next key.
        m.update(Action::FieldEdit { edit: Edit::Move { to: Motion::End, select: false } });
        assert_eq!(m.compose_note(), None);
        let before = m.tasks.list.len();
        assert_eq!((m.enter(), m.enter_completes()), (Enter::Take(0), false), "the hint does not say ↵ completes");
        m.update(Action::ComposeSubmit { open: false });
        assert_eq!(
            (line(&m), m.compose_note(), m.tasks.list.len()),
            (full.as_str(), Some("no room in the line for that name"), before)
        );
        m.update(Action::ComposeEscape);
        m.update(Action::ComposeSubmit { open: false });
        let task = m.tasks.list.last().unwrap();
        assert_eq!((m.tasks.list.len(), task.project.as_deref(), m.mode()), (before + 1, Some("ca"), Mode::Normal));

        // A file with no room is not put in in part either, and the box says so.
        m.update(Action::OpenCompose { text: "x".repeat(MAX_TITLE - 4) });
        m.update(Action::ComposeAttach { paths: vec!["/etc/hosts".into()], home: None, unreadable: 0 });
        assert_eq!((line(&m).len(), m.compose_note()), (MAX_TITLE - 4, Some("no room in the line: nothing was added")));
    }

    #[test]
    fn a_path_of_any_name_goes_in_as_one_word_or_not_at_all() {
        let mut m = composing();
        // macOS names a screenshot with a narrow no-break space before AM; a name may hold a backslash.
        let shot = "/Users/me/Desktop/Screenshot 2026-11-12 at 9.41.05\u{202f}AM.png".to_string();
        let odd = r"/tmp/a\b c".to_string();
        m.update(Action::ComposeAttach {
            paths: vec![shot.clone(), odd.clone()],
            home: Some("/Users/me".into()),
            unreadable: 0,
        });
        assert_eq!(line(&m), "~/Desktop/Screenshot\\ 2026-11-12\\ at\\ 9.41.05\\\u{202f}AM.png /tmp/a\\\\b\\ c ");
        let read = compose::path_words(line(&m));
        assert_eq!(read, [vec![shot.replace("/Users/me", "~")], vec![odd.clone()]]);
        // A line break cannot be in the line; a name too long cannot be kept; one that is
        // not text was never given. Each is left out, and the box says how many.
        m.update(Action::FieldEdit { edit: Edit::SelectAll });
        let long = format!("/{}", "x".repeat(tasks::MAX_TAG));
        let paths = vec!["/tmp/a\nb".to_string(), long, "/etc/hosts".into()];
        m.update(Action::ComposeAttach { paths, home: None, unreadable: 1 });
        assert_eq!(
            (line(&m), m.compose_note()),
            ("/etc/hosts ", Some("3 left out: a name too long, or not one a line can hold"))
        );
        // Under the key reference the box is hidden: nothing goes into its line, and Esc is not its own.
        m.keys = true;
        m.update(Action::ComposeAttach { paths: vec!["/etc/passwd".into()], home: None, unreadable: 0 });
        m.update(Action::ComposeRef { target: Pointed::Pane(1) });
        m.update(Action::ComposeEscape);
        m.keys = false;
        assert_eq!((line(&m), m.mode()), ("/etc/hosts ", Mode::Compose));
    }

    #[test]
    fn a_name_in_a_line_means_one_thing_while_the_line_is_there() {
        let mut m = Model::default();
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        let info = |pane, cwd: &str| TerminalInfo { pane, cwd: Some(cwd.into()), program: None, shell: None };
        m.update(Action::SetTerminals { terminals: vec![info(1, "/code/repo"), info(2, "/code/other")], home: None });
        m.update(Action::OpenCompose { text: String::new() });
        // ⌥-click pane 1 (`repo`). It exits; pane 2 moves into a directory of that name; ⌥-click it.
        m.update(Action::ComposeRef { target: Pointed::Pane(1) });
        m.update(Action::Close { pane: Some(1) });
        m.update(Action::SetTerminals { terminals: vec![info(2, "/work/repo")], home: None });
        m.update(Action::ComposeRef { target: Pointed::Pane(2) });
        // The same pane again adds its word again, and is still one reference.
        m.update(Action::ComposeRef { target: Pointed::Pane(2) });
        assert_eq!(line(&m), "^repo ^repo-2 ^repo-2 ");
        keys(&mut m, "compare");
        m.update(Action::ComposeSubmit { open: false });
        let refs = &m.tasks.list[0].refs;
        let kept: Vec<(&str, Option<u32>, Option<&str>)> =
            refs.iter().map(|r| (r.name.as_str(), r.id, r.cwd.as_deref())).collect();
        assert_eq!(kept, [("repo", Some(1), Some("/code/repo")), ("repo-2", Some(2), Some("/work/repo"))]);

        // A draft that is cancelled keeps nothing: a client's line is read against what is
        // open, and never against what a box pointed at.
        m.update(Action::OpenCompose { text: String::new() });
        m.update(Action::ComposeRef { target: Pointed::Pane(2) });
        m.update(Action::Close { pane: Some(2) });
        assert_eq!(m.draft("x ^repo").refs, ["repo"], "the box's own line keeps it");
        let theirs = Action::TaskFromLine { line: "theirs ^repo".into(), known: Default::default(), open: false };
        m.update(theirs.clone());
        assert_eq!((m.tasks.list[1].title.as_str(), m.tasks.list[1].refs.len()), ("theirs ^repo", 0));
        m.update(Action::CloseCompose);
        assert_eq!((m.compose_refs.len(), m.draft("x ^repo").refs.len()), (0, 0));
        m.update(Action::OpenCompose { text: String::new() });
        m.update(Action::ComposeRef { target: Pointed::Tab(m.tabs[0].id) });
        m.update(Action::ComposeEscape);
        m.update(theirs);
        assert_eq!((m.compose_refs.len(), m.tasks.list[2].refs.len()), (0, 0));
        // A name that ends as a clause does reads as itself first, then without the dot.
        m.tabs[0].title = "notes v1.".into();
        m.update(Action::NewTab);
        m.tabs[1].title = "plan".into();
        let draft = m.draft(r"see ^notes\ v1. and ^plan. now");
        assert_eq!((draft.refs, draft.title.as_str()), (vec!["notes v1.".to_string(), "plan".into()], "see and now"));
    }

    #[test]
    fn the_highlight_stays_on_its_row_when_the_rows_change() {
        let mut m = composing();
        keys(&mut m, "fix #ca");
        m.update(Action::ComposeMove { delta: 1 });
        let on = |m: &Model| m.dropdown().and_then(|menu| menu.selected.map(|at| menu.rows[at].name.clone()));
        assert_eq!(on(&m).as_deref(), Some("Cables"));
        // A client adds tasks: `Cables` now has the most, and is the first row.
        for _ in 0..3 {
            m.update(
                Action::TaskFromLine { line: "more #Cables".into(), known: Default::default(), open: false }
                    .sent_by(Origin::Socket),
            );
        }
        assert_eq!((offered(&m)[0].as_str(), on(&m).as_deref()), ("Cables", Some("Cables")));
        // What the user moved to is gone from the rows: the first is highlighted again.
        m.tasks.list.retain(|task| task.project.as_deref() != Some("Cables"));
        assert_eq!(on(&m).as_deref(), Some("canvas"));
    }

    #[test]
    fn a_task_file_keeps_less_of_a_reference_than_the_session_does() {
        let mut m = Model::default();
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        m.update(Action::Open { kind: app(7), axis: Right, beside: None });
        let info = TerminalInfo {
            pane: 1,
            cwd: Some("/Users/me/clients/acme".into()),
            program: Some("vim".into()),
            shell: None,
        };
        m.update(Action::SetTerminals { terminals: vec![info], home: None });
        let sketch = Installed { name: "Sketchpad".into(), path: "/Applications/Sketchpad.app".into() };
        m.update(Action::SetInstalled { apps: vec![sketch], running: Vec::new() });
        m.update(Action::OpenCompose { text: "look ^acme ^app ^Sketchpad ^Tab\\ 1".into() });
        m.update(Action::ComposeSubmit { open: false });
        let task = &m.tasks.list[0];
        // In memory, and in the state: what tells each apart.
        assert_eq!(
            (task.refs[0].cwd.as_deref(), task.refs[1].title.as_deref()),
            (Some("/Users/me/clients/acme"), Some("w7"))
        );
        // In the file: what it is, its name, its id then, its app. No window title, no
        // directory, no program, no place on disk.
        let file = serde_json::to_value(task.for_file()).unwrap();
        assert_eq!(
            file["refs"],
            serde_json::json!([
                {"kind": "pane", "name": "acme", "id": 1},
                {"kind": "pane", "name": "app", "id": 2, "app": "app"},
                {"kind": "app", "name": "Sketchpad", "app": "Sketchpad"},
                {"kind": "tab", "name": "Tab 1", "id": m.tabs[0].id},
            ])
        );
        assert_eq!(serde_json::from_value::<Task>(file).unwrap().refs.len(), 4);
    }

    #[test]
    fn the_box_is_the_drawers_new_task_state() {
        let mut m = Model::default();
        // Nothing open: the drawer shows itself, in its new-task state.
        assert!(m.welcome() && m.compose_host().is_none());
        m.update(Action::OpenCompose { text: "tidy up".into() });
        assert_eq!(m.compose_host(), Some(Host::Drawer));
        // ⇧↵ files it for later: the box closes. Nothing is open but a task: no welcome.
        m.update(Action::ComposeSubmit { open: false });
        assert_eq!((m.tasks.list.len(), m.compose_host(), m.mode(), m.welcome()), (1, None, Mode::Normal, false));
        // ↵ adds and starts: its conversation opens, so the box goes.
        m.update(Action::OpenCompose { text: "start me".into() });
        m.update(Action::ComposeEnter);
        assert_eq!((m.compose_host(), m.talk.as_ref().and_then(|talk| talk.task.task())), (None, Some(2)));
        // With a pane showing it is the drawer too.
        term(&mut m);
        m.update(Action::OpenCompose { text: "over panes".into() });
        assert_eq!(m.compose_host(), Some(Host::Drawer));
    }

    #[test]
    fn the_drawers_picks_set_the_lines_repository_and_agent_and_say_what_enter_does() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: listed() });
        m.update(Action::OpenCompose { text: "fix zoom >old @ana".into() });
        let picks = m.compose_picks();
        assert_eq!(picks.wheres, ["app"]);
        assert_eq!(picks.whos[..3], ["claude", "claude-fable-5-2", "claude-opus-5-5"]);
        // WHERE and WHO replace the line's own tags; "no repository" takes it out.
        m.update(Action::ComposePick { mark: '>', name: Some("app".into()) });
        m.update(Action::ComposePick { mark: '@', name: Some("codex-gpt-6-astra".into()) });
        assert_eq!(line(&m), "fix zoom >app @codex-gpt-6-astra ");
        let plan = Plan { agent: "codex-gpt-6-astra".into(), starts: true, dir: Some("app".into()), branch: None };
        assert_eq!(m.compose_plan(), Some(plan));
        m.update(Action::ComposePick { mark: '>', name: None });
        assert_eq!(line(&m), "fix zoom @codex-gpt-6-astra ");
        // A word that only starts with the mark is no tag: it stays, spaces and all.
        m.update(Action::FieldEdit { edit: Edit::Insert("  >= 3".into()) });
        m.update(Action::ComposePick { mark: '>', name: Some("app".into()) });
        assert_eq!(line(&m), "fix zoom @codex-gpt-6-astra   >= 3 >app ");
        m.update(Action::ComposePick { mark: '>', name: None });
        // Only what the picks offer: nothing else is written into the line.
        for (mark, name) in [('>', "elsewhere"), ('@', "ana"), ('#', "app"), ('@', "--yolo")] {
            m.update(Action::ComposePick { mark, name: Some(name.into()) });
            assert_eq!(line(&m), "fix zoom @codex-gpt-6-astra   >= 3 ", "{mark}{name}");
        }
        // No tag: the default agent, in the home folder. A saved agent starts nothing.
        m.update(Action::ComposePick { mark: '@', name: None });
        assert_eq!(line(&m), "fix zoom   >= 3 ");
        assert_eq!(
            m.compose_plan().map(|plan| (plan.agent, plan.starts, plan.dir)),
            Some(("claude".into(), true, None))
        );
        m.update(Action::SetAgents {
            claude: Vec::new(),
            codex: Vec::new(),
            default: Some("ana".into()),
            shows: View::Native,
        });
        assert_eq!(m.compose_plan().map(|plan| plan.starts), Some(false));
        m.update(Action::CloseCompose);
        assert_eq!(
            (m.compose_plan(), m.update(Action::ComposePick { mark: '>', name: Some("app".into()) })),
            (None, vec![])
        );
    }

    /// The pickers show the default agent at once, follow a typed tag, and write theirs into the
    /// line: one source, two ways in.
    #[test]
    fn the_pickers_show_the_default_agent_and_follow_the_line_both_ways() {
        let mut m = composing();
        let choices = |m: &Model| m.compose_choices().expect("pickers");
        let c = choices(&m);
        assert_eq!((c.project, c.place, c.agent.as_str(), c.default), (None, None, "claude", true));
        assert_eq!(m.compose_pickers(), ['#', '>', '@']);
        // A typed tag fills its picker, and the picker's list opens on it.
        keys(&mut m, "fix zoom >app #canvas ");
        let c = choices(&m);
        assert_eq!((c.project.as_deref(), c.place.as_deref()), (Some("canvas"), Some("app")));
        m.update(Action::ComposePicker { mark: Some('>') });
        let menu = m.picker_menu().expect("the repository list");
        let names: Vec<&str> = menu.rows.iter().map(|row| row.name.as_str()).collect();
        assert_eq!((names, menu.selected), (vec!["no repository", "app", "app-2"], Some(1)));
        // A row taken goes into the line as its tag, in place of the other; the list closes.
        m.update(Action::ComposeAccept { index: 2 });
        assert_eq!((line(&m), m.picker_menu()), ("fix zoom #canvas >app-2 ", None));
        assert_eq!(choices(&m).place.as_deref(), Some("app-2"));
        // "no project" takes the tag out.
        m.update(Action::ComposePicker { mark: Some('#') });
        m.update(Action::ComposeAccept { index: 0 });
        assert_eq!((line(&m), choices(&m).project), ("fix zoom >app-2 ", None));
        // A click on the open one closes it; typing closes it too.
        m.update(Action::ComposePicker { mark: Some('@') });
        m.update(Action::ComposePicker { mark: Some('@') });
        assert!(m.picker_menu().is_none());
        m.update(Action::ComposePicker { mark: Some('@') });
        keys(&mut m, "x");
        assert!(m.picker_menu().is_none());
        // A tag a comma ends goes with "no project"; a model typed that no list has is kept.
        m.update(Action::FieldEdit { edit: Edit::Delete { to: Motion::Start } });
        keys(&mut m, "fix #canvas), @claude-opus-9 ");
        m.update(Action::ComposePicker { mark: Some('#') });
        m.update(Action::ComposeAccept { index: 0 });
        m.update(Action::ComposePicker { mark: Some('@') });
        m.update(Action::ComposeEnter);
        assert_eq!((line(&m), choices(&m).project), ("fix @claude-opus-9 ", None));
        // A word is as the line reads it: a backslash keeps a space in it; any space ends one.
        m.update(Action::FieldEdit { edit: Edit::Delete { to: Motion::Start } });
        keys(&mut m, "see /tmp/a\\ #b fix\u{a0}#canvas ");
        m.update(Action::ComposePick { mark: '#', name: None });
        assert_eq!(line(&m), "see /tmp/a\\ #b fix\u{a0}");
        // A name the line has no room for: its list says so.
        m.update(Action::FieldEdit { edit: Edit::Delete { to: Motion::Start } });
        keys(&mut m, &"x".repeat(MAX_TITLE - 4));
        m.update(Action::ComposePicker { mark: Some('@') });
        m.update(Action::ComposeMove { delta: 1 });
        let said = m.compose_status().unwrap_or_default();
        assert!(said.starts_with("↵: no room in the line for @"), "{said}");
        // The quick note has none, and no list stays open from the box it was.
        m.update(Action::FieldEdit { edit: Edit::Delete { to: Motion::Start } });
        m.update(
            Action::SetFeatures { features: Features::all().with(Feature::OverlayPanels, true) }
                .sent_by(Origin::System),
        );
        m.update(Action::ComposePicker { mark: Some('@') });
        m.update(Action::QuickOpen { now: 0, word: "note".into(), transcript: None }.sent_by(Origin::User));
        assert_eq!((m.quick.is_some(), m.picker_menu()), (true, None));
        m.update(Action::CloseCompose);
        assert_eq!(m.compose_choices(), None);
    }

    /// Keys only: Tab steps through the pickers' lists and back to the line, ↓ moves, ↵ takes, and
    /// the one line says what ↵ will take. ⇧Tab goes back.
    #[test]
    fn each_picker_is_reached_and_taken_from_the_keys() {
        let mut m = composing();
        keys(&mut m, "fix zoom");
        let open = |m: &Model| m.picker_menu().map(|menu| menu.mark);
        m.update(Action::ComposeComplete);
        assert_eq!(
            (open(&m), m.compose_status().as_deref()),
            (Some('#'), Some("↵ takes no project · Esc closes the list"))
        );
        m.update(Action::ComposeComplete);
        assert_eq!(open(&m), Some('>'));
        m.update(Action::ComposeMove { delta: 1 });
        assert_eq!(m.compose_status().as_deref(), Some("↵ takes >app · Esc closes the list"));
        m.update(Action::ComposeEnter);
        assert_eq!((line(&m), open(&m), m.tasks.list.len()), ("fix zoom >app ", None, 4), "taken, nothing filed");
        // To the agent's: ⇧Tab from the line goes to the last.
        m.update(Action::ComposePickerStep { delta: -1 });
        assert_eq!(open(&m), Some('@'));
        let said = "↵ takes @claude · ⌥↵ makes it the default · Esc closes the list";
        assert_eq!(m.compose_status().as_deref(), Some(said));
        m.update(Action::ComposeMove { delta: 1 });
        m.update(Action::ComposeEnter);
        assert_eq!(line(&m), "fix zoom >app @claude-fable-5-2 ");
        // Tab past the last is the line again; Esc closes a list, the box stays.
        m.update(Action::ComposePickerStep { delta: -1 });
        m.update(Action::ComposeComplete);
        assert_eq!(open(&m), None);
        m.update(Action::ComposeComplete);
        m.update(Action::ComposeEscape);
        assert_eq!((open(&m), m.composing()), (None, true));
        // ↵ with no list open does what the line says.
        let said = m.compose_status().unwrap_or_default();
        assert!(said.starts_with("↵ starts @claude-fable-5-2 in app"), "{said}");
        let effects = m.update(Action::ComposeEnter);
        assert!(matches!(effects[..], [Effect::StartAgent { .. }]), "{effects:?}");
    }

    /// ⌥↵ in the agent list makes the highlighted one the default, written as the user's own act;
    /// a client's is refused, and a saved agent is never the default.
    #[test]
    fn the_users_alt_enter_in_the_agent_list_makes_the_default() {
        let mut m = composing();
        keys(&mut m, "fix @codex ");
        m.update(Action::ComposePicker { mark: Some('@') });
        assert_eq!(m.refusal(&Action::ComposeDefault, Origin::Socket), Some(pickers::DEFAULT_USERS));
        assert_eq!(m.update(Action::ComposeDefault.sent_by(Origin::Socket)), []);
        let effects = m.update(Action::ComposeDefault);
        assert_eq!(effects, [Effect::SaveDefaultAgent { agent: "codex".into() }]);
        // The default needs no tag: it leaves the line, and the picker still shows it.
        let c = m.compose_choices().expect("pickers");
        assert_eq!((line(&m), c.agent.as_str(), c.default), ("fix ", "codex", true));
        // A saved agent: ⌥↵ does nothing, and the line does not offer it.
        let names = compose::Names { agents: vec!["claude".into(), "codex".into(), "ana".into()], skills: vec![] };
        m.update(Action::SetKnown {
            line: String::new(),
            typing: None,
            names: Some(names),
            paths: vec![],
            entries: vec![],
        });
        m.update(Action::ComposePicker { mark: Some('@') });
        let last = m.picker_menu().map_or(0, |menu| menu.rows.len() - 1);
        m.update(Action::ComposeMove { delta: last as i32 + 1 });
        m.update(Action::ComposeMove { delta: -1 });
        assert_eq!(
            m.picker_menu().and_then(|menu| menu.selected.map(|at| menu.rows[at].name.clone())).as_deref(),
            Some("ana")
        );
        assert_eq!((m.picker_default(), m.update(Action::ComposeDefault)), (None, vec![]));
        assert!(!m.compose_status().unwrap_or_default().contains("⌥↵"));
    }

    #[test]
    fn a_status_line_too_long_leaves_off_its_trailing_keys_never_part_of_a_word() {
        let said = "↵ starts @claude in your home folder · ⇧↵ later · Esc";
        let room = |n: usize| move |text: &str| text.chars().count() <= n;
        assert_eq!(fit_status(said, room(80)), said);
        assert_eq!(fit_status(said, room(50)), "↵ starts @claude in your home folder · ⇧↵ later");
        assert_eq!(fit_status(said, room(40)), "↵ starts @claude in your home folder");
        // Then what ↵ does, after a word; with room for no word, the shell cuts it.
        assert_eq!(fit_status(said, room(30)), "↵ starts @claude in your home…");
        assert_eq!(fit_status(said, room(1)), "↵ starts @claude in your home folder");
        let mut m = Model::default();
        m.update(Action::OpenCompose { text: "fix".into() });
        assert_eq!(
            fit_status(&m.compose_status().unwrap_or_default(), room(40)),
            "↵ starts @claude in your home folder"
        );
    }

    #[test]
    fn the_box_says_what_enter_does_in_one_line_and_its_tags_on_demand() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: listed() });
        assert_eq!((m.compose_status(), m.compose_hint()), (None, None), "closed");
        m.update(Action::OpenCompose { text: String::new() });
        // Empty: what ↵ will do once there is a title. No tags until asked for.
        let said = "Type, then ↵ starts @claude in your home folder · ⇧↵ later · Esc";
        assert_eq!((m.compose_status().as_deref(), m.compose_hint()), (Some(said), None));
        // The sheet: "? tags" or ⌘/ (the key reference's key) while the line has the keyboard.
        m.update(Action::ComposeSheet);
        assert_eq!(m.compose_hint(), Some(TAG_HINT));
        m.update(Action::ComposeSheet);
        assert_eq!(m.compose_hint(), None);
        m.update(Action::ToggleKeys);
        assert_eq!((m.compose_hint(), m.keys), (Some(TAG_HINT), false));
        // ⌘/ again: every key, in its place.
        m.update(Action::ToggleKeys);
        assert_eq!((m.compose_hint(), m.keys), (None, true));
        m.update(Action::CloseKeys);
        // Each key of the hint is in its text.
        assert!(TAG_KEYS.iter().all(|(key, word)| TAG_HINT.contains(&format!("{key}{word}")) || *key == "p1"));
        // A row to take: ↵ takes it, and the line says so.
        keys(&mut m, "fix zoom >");
        assert_eq!(m.compose_status().as_deref(), Some("↵ takes >app · Esc closes the list"));
        m.update(Action::ComposeComplete);
        assert_eq!(line(&m), "fix zoom >app ");
        assert_eq!(m.compose_status().as_deref(), Some("↵ starts @claude in app · ⇧↵ later · Esc"));
        m.update(Action::FieldEdit { edit: Edit::Delete { to: Motion::Start } });
        keys(&mut m, "fix zoom");
        m.update(Action::ComposePick { mark: '@', name: Some("codex-gpt-6-astra".into()) });
        let said = "↵ starts @codex-gpt-6-astra in your home folder · ⇧↵ later · Esc";
        assert_eq!(m.compose_status().as_deref(), Some(said));
        // A saved agent as the default: ↵ starts nothing, and the box says so.
        m.update(Action::ComposePick { mark: '@', name: None });
        let saved = Some("ana".into());
        m.update(Action::SetAgents { claude: Vec::new(), codex: Vec::new(), default: saved, shows: View::Native });
        assert_eq!(m.compose_status().as_deref(), Some("↵ files it; nothing starts · Esc"));
        // Closed, the sheet is gone with it.
        m.update(Action::CloseCompose);
        m.update(Action::OpenCompose { text: String::new() });
        assert_eq!(m.compose_hint(), None);
    }

    #[test]
    fn any_keys_in_the_box_leave_a_line_that_reads_and_a_dropdown_that_holds() {
        use unicode_segmentation::UnicodeSegmentation;
        let mut rng = crate::edit::fuzz::Rng(0x2545_f491_4f6c_dd1d);
        let mut m = composing();
        let sketch = Installed { name: "Sketch pad".into(), path: "/Applications/Sketch pad.app".into() };
        m.update(Action::SetInstalled { apps: vec![sketch], running: Vec::new() });
        for step in 0..6000 {
            if m.compose.is_none() {
                m.update(Action::OpenCompose { text: rng.text() });
            }
            let len = line(&m).len();
            let before = m.dropdown();
            let action = match rng.below(12) {
                0 => Action::ComposeMove { delta: rng.below(5) as i32 - 2 },
                1 => Action::ComposeComplete,
                2 => Action::ComposeAccept { index: rng.below(9) },
                3 => Action::ComposeEscape,
                4 if rng.below(8) == 0 => Action::ComposeSubmit { open: false },
                5 => Action::ComposeRef { target: Pointed::Pane(1) },
                6 if rng.below(4) == 0 => {
                    Action::ComposeAttach { paths: vec!["/a b/c".into()], home: None, unreadable: 0 }
                }
                _ => Action::FieldEdit { edit: rng.edit(len) },
            };
            let taken = match (&action, &before) {
                (Action::ComposeAccept { index }, Some(menu)) => {
                    menu.rows.get(*index).map(|row| (menu.mark, row.name.clone()))
                }
                (Action::ComposeComplete, Some(menu)) => {
                    menu.rows.get(menu.selected.unwrap_or(0)).map(|row| (menu.mark, row.name.clone()))
                }
                _ => None,
            };
            m.update(action.clone());
            let Some(field) = &m.compose else { continue };
            let text = field.text();
            let why = format!("step {step}: {text:?} after {action:?}");
            // The cursor is between clusters; the line reads; its spans are words of it.
            let clusters: Vec<usize> = text.grapheme_indices(true).map(|(i, _)| i).chain([text.len()]).collect();
            assert!(clusters.contains(&field.cursor()), "{why}");
            let (draft, spans) = (m.draft(text), m.compose_spans());
            assert!(draft.title.len() <= text.len(), "{why}");
            assert!(
                spans.iter().all(|span| text
                    .get(span.range.clone())
                    .is_some_and(|word| !word.contains(' ') || word.contains('\\'))),
                "{why}"
            );
            // The highlight is on a row. A row taken reads back as the tag it is: a project,
            // a repository, an agent, a skill or a reference of that very name.
            if let Some(menu) = m.dropdown() {
                assert!(
                    menu.selected.is_none_or(|at| at < menu.rows.len()) && menu.rows.len() <= complete::MAX_ROWS,
                    "{why}"
                );
            }
            if let Some((mark, name)) = taken.filter(|(mark, _)| *mark != '/') {
                let named = match mark {
                    '#' => draft.project.as_ref() == Some(&name),
                    '>' => draft.repo.as_ref() == Some(&name),
                    '@' => draft.agent.as_ref() == Some(&name),
                    '$' => draft.skills.contains(&name),
                    _ => draft.refs.contains(&name),
                };
                assert!(named, "{mark}{name} was taken and does not read: {draft:?}; {why}");
            }
        }
    }

    /// The names on the dropdown's rows.
    fn offered(m: &Model) -> Vec<String> {
        m.dropdown().map(|menu| menu.rows.into_iter().map(|row| row.name).collect()).unwrap_or_default()
    }

    #[test]
    fn tags_count_only_for_names_the_shell_read() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: listed() });
        let line = "review the export >app @Codex $Code-Review $code-review /src/export ~/gone p2";
        // Nothing read yet: only the repository is known.
        assert_eq!(m.draft(line).title, "review the export @Codex $Code-Review $code-review /src/export ~/gone");
        assert_eq!(m.draft_repo(line).as_deref(), Some("/code/app"));
        let list = |list: &[&str]| list.iter().map(|name| name.to_string()).collect::<Vec<_>>();
        let names = compose::Names { agents: list(&["claude", "codex"]), skills: list(&["code-review", "deploy"]) };
        let found = compose::PathFound { typed: "/src/export".into(), resolved: "/code/app/src/export".into() };
        // What the shell read for a line counts for that line only: an answer that comes after
        // the line has changed is dropped, and a folder's entries while another is typed. The
        // names are good for any line.
        m.update(Action::OpenCompose { text: "see /src/ex".into() });
        assert!(!m.compose_read());
        let stale = Action::SetKnown {
            line: "see /e".into(),
            typing: Some(("/".into(), "/".into())),
            names: Some(names.clone()),
            paths: vec![found.clone()],
            entries: list(&["/elsewhere/"]),
        };
        m.update(stale);
        assert_eq!((offered(&m), m.compose_read()), (vec![], false));
        m.update(Action::SetKnown {
            line: "see /src/ex".into(),
            typing: Some(("/src/".into(), "/src/".into())),
            names: None,
            paths: Vec::new(),
            entries: list(&["/src/export/", "/src/extra.rs"]),
        });
        assert_eq!((offered(&m), m.compose_read()), (list(&["/src/export/", "/src/extra.rs"]), true));
        m.update(Action::ComposeComplete);
        assert_eq!((m.compose.as_ref().map(Field::text), m.compose_read()), (Some("see /src/export/"), false));
        m.update(Action::CloseCompose);
        // Tab offers each tag's own names.
        for (typed, names) in [("@c", vec!["claude", "codex"]), ("$dep", vec!["deploy"])] {
            m.update(Action::OpenCompose { text: typed.into() });
            assert_eq!(offered(&m), names, "{typed}");
            m.update(Action::CloseCompose);
        }
        // Filed from the box: agent and skill as they are spelled where they were read, the skill
        // once; the path with where it was found; the unknown path stays in the title.
        m.update(Action::OpenCompose { text: line.into() });
        m.update(Action::SetKnown {
            line: line.into(),
            typing: None,
            names: None,
            paths: vec![found.clone()],
            entries: Vec::new(),
        });
        m.update(Action::ComposeSubmit { open: false });
        let task = &m.tasks.list[0];
        assert_eq!(
            (task.title.as_str(), task.repo.as_deref(), task.priority),
            ("review the export /src/export ~/gone", Some("/code/app"), 2)
        );
        assert_eq!((task.agent.as_deref(), task.skills.as_slice()), (Some("codex"), &list(&["code-review"])[..]));
        assert_eq!(
            (task.paths.as_slice(), task.resolved.as_slice()),
            (&list(&["/src/export"])[..], &list(&["/code/app/src/export"])[..])
        );
        assert_eq!(m.task_tags(task), ">app · @codex · 1 path · 1 skill");
        // Filed: the box closes.
        assert_eq!(m.compose_host(), None);
        // A line filed from outside brings what was read for it, and leaves what the box knows
        // alone: the line the user is typing keeps its tags.
        m.update(Action::OpenCompose { text: "mine $deploy".into() });
        let theirs = compose::Known {
            names: compose::Names { agents: list(&["ana"]), skills: Vec::new() },
            ..Default::default()
        };
        m.update(Action::TaskFromLine { line: "ask @ana $deploy".into(), known: theirs, open: false });
        assert_eq!((m.tasks.list[1].title.as_str(), m.tasks.list[1].agent.as_deref()), ("ask $deploy", Some("ana")));
        assert_eq!(m.draft("mine $deploy").skills, list(&["deploy"]));
        m.update(Action::ComposeSubmit { open: false });
        assert_eq!(
            (m.tasks.list[2].title.as_str(), m.tasks.list[2].skills.as_slice()),
            ("mine", &list(&["deploy"])[..])
        );
        // The socket's `task_add` names them without a line, in the same step.
        let assign = Assign { agent: Some("claude".into()), skills: list(&["a", "b"]), ..Assign::default() };
        m.update(Action::TaskAdd { title: "a".into(), priority: 1, state: State::Running, tab: None, assign });
        assert_eq!(m.task_tags(&m.tasks.list[3]), "@claude · 2 skills");
    }

    /// The Tasks section as (heading, count, ids of the rows drawn).
    fn sections(m: &Model) -> Vec<(Heading, usize, Vec<TaskId>)> {
        let sections = m.task_sections(0);
        sections.iter().map(|s| (s.heading, s.count, s.rows.iter().map(|r| r.id).collect())).collect()
    }

    #[test]
    fn the_tasks_section_lists_each_task_once_and_what_needs_you_first() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: listed() });
        m.update(Action::Tick { now: 1_000 });
        for (title, state) in [("ask", State::NeedsYou), ("build", State::Running), ("idea", State::Captured)] {
            m.update(Action::TaskAdd { title: title.into(), priority: 2, state, tab: None, assign: Assign::default() });
        }
        m.update(Action::TaskFromLine {
            line: "fix zoom #canvas >app-2 p1".into(),
            known: Default::default(),
            open: false,
        });
        // Under its state's heading, open or not; within one, most urgent first, then oldest.
        m.update(Action::SpaceOpen { space: Owner::Task { id: 4 } });
        m.update(Action::NewTab);
        m.update(Action::SpaceOpen { space: Owner::Task { id: 1 } });
        m.update(Action::TaskSetState { id: 3, state: State::Parked });
        assert_eq!(
            sections(&m),
            [(Heading::NeedsYou, 1, vec![1]), (Heading::Running, 1, vec![2]), (Heading::Later, 2, vec![4, 3])],
            "Later holds what is captured and what is on hold"
        );
        // Each row: one fact, by its state (none for needs you); the one on show is marked. Its
        // tags and what it has open are on its card.
        let now = 1_000 + 3 * 3_600_000;
        let sections = m.task_sections(now);
        let (needs, later) = (&sections[0].rows[0], &sections[2].rows[0]);
        assert_eq!((&needs.fact, needs.current, needs.group), (&None, true, tasks::Group::NeedsYou));
        assert_eq!((later.fact.as_deref(), later.current), (Some("3h"), false));
        let (needs, later) = (m.card(1, now).unwrap(), m.card(4, now).unwrap());
        assert_eq!((needs.workspace.as_str(), needs.filed.as_deref()), ("1 tab · 0 panes", Some("3h")));
        assert_eq!((later.tags.as_slice(), later.priority), (&["#canvas".to_string(), ">app-2".into()][..], 1));
        assert_eq!(later.workspace, "2 tabs · 0 panes");
        // List mode walks the headings and rows in the order drawn.
        m.update(Action::ToggleSection { section: Section::Tasks });
        let (heading, task) = (ListRow::Heading, ListRow::Task);
        let drawn = [heading(Heading::NeedsYou), task(1), heading(Heading::Running), task(2)];
        assert_eq!(m.list_rows(), [&drawn[..], &[heading(Heading::Later), task(4), task(3)]].concat());
        // A finished task is under Done, last and folded: counted, not listed, until unfolded.
        m.update(Action::TaskSetState { id: 2, state: State::Done });
        let done = m.task_sections(0).pop().unwrap();
        assert_eq!((done.heading, done.count, done.collapsed, done.rows.len()), (Heading::Done, 1, true, 0));
        m.update(Action::ToggleGroup { heading: Heading::Done });
        assert_eq!(m.task_sections(0).pop().unwrap().rows[0].id, 2);
    }

    /// Tasks with these (title, project, state), filed in this order.
    fn filed(m: &mut Model, tasks: &[(&str, Option<&str>, State)]) {
        for (title, project, state) in tasks {
            let tags = project.map(|p| format!(" #{p}")).unwrap_or_default();
            m.update(Action::TaskFromLine { line: format!("{title}{tags}"), known: Default::default(), open: false });
            let id = m.tasks.list.last().map(|t| t.id).unwrap_or_default();
            m.update(Action::TaskSetState { id, state: *state });
        }
    }

    #[test]
    fn the_project_view_groups_by_project_with_no_project_last_and_a_bar_of_states() {
        let mut m = Model::default();
        use State::*;
        filed(
            &mut m,
            &[
                ("a", Some("web"), Done),
                ("b", None, Captured),
                ("c", Some("api"), Running),
                ("d", Some("web"), NeedsYou),
                ("e", Some("Beta"), Parked),
                ("f", Some("web"), Captured),
                ("g", Some("web"), Running),
            ],
        );
        let groups = m.project_groups(0);
        let names: Vec<Option<&str>> = groups.iter().map(|g| g.project.as_deref()).collect();
        assert_eq!(names, [Some("api"), Some("Beta"), Some("web"), None], "by name, whatever the case; none last");
        let web = &groups[2];
        // Needs you, running, later; Done is a folded line under them.
        assert_eq!(web.rows.iter().map(|r| r.id).collect::<Vec<_>>(), [4, 7, 6]);
        assert_eq!((web.done, web.done_open, web.done_rows.len()), (1, false, 0));
        assert_eq!(web.bar, tasks::Segments { needs_you: 1, running: 1, later: 1, done: 1 });
        assert_eq!(web.bar.shares(), [0.25; 4]);
        assert_eq!(tasks::Segments::default().shares(), [0.; 4]);
        assert_eq!(web.bar.tip(), "1 needs you · 1 running · 1 later · 1 done");
        // List mode walks the projects, their tasks and their Done lines; ↵ on one folds it.
        m.update(Action::ToggleSection { section: Section::Tasks });
        m.update(Action::FocusList);
        // A client's switch is not written; the user's is, once.
        assert_eq!(m.update(Action::TasksView { view: TasksView::Project }.sent_by(Origin::Socket)), []);
        m.update(Action::TasksView { view: TasksView::State }.sent_by(Origin::Socket));
        let saved = m.update(Action::TasksView { view: TasksView::Project });
        assert_eq!(saved, [Effect::SaveTasksView { view: TasksView::Project }]);
        assert_eq!(m.update(Action::TasksView { view: TasksView::Project }), []);
        let (project, task) = (|p: Option<&str>| ListRow::Project(p.map(String::from)), ListRow::Task);
        let web_done = ListRow::ProjectDone(Some("web".into()));
        assert_eq!(
            m.list_rows()[..9],
            [
                project(Some("api")),
                task(3),
                project(Some("Beta")),
                task(5),
                project(Some("web")),
                task(4),
                task(7),
                task(6),
                web_done.clone()
            ]
        );
        assert_eq!(m.list, Some(5), "still on the task it was on: d, which needs you");
        m.update(Action::ListMove { delta: 3 });
        m.update(Action::ListChoose { axis: Axis::Right });
        assert_eq!((m.open_done.as_slice(), m.list_rows()[9].clone()), (&[Some("web".to_string())][..], task(1)));
        m.update(Action::ToggleProject { project: Some("web".into()), done: false });
        assert_eq!(m.project_groups(0)[2].rows.len(), 0);
        assert_eq!(m.list_rows()[4..6], [project(Some("web")), project(None)]);
    }

    #[test]
    fn the_sessions_read_for_work_are_of_open_tasks_and_those_done_just_now_running_first() {
        let mut m = Model::default();
        m.update(Action::Tick { now: 1_000_000 });
        filed(&mut m, &[("a", None, State::Captured), ("b", None, State::Running), ("c", None, State::Running)]);
        for id in 1..=3 {
            m.tasks.link(id, sessions::Link { runner: "claude".into(), id: format!("s{id}"), state: None });
        }
        let ids = |m: &Model| m.worked_sessions().into_iter().map(|(_, id, _)| id).collect::<Vec<_>>();
        assert_eq!(ids(&m), ["s2", "s3", "s1"]);
        // Done: read a while longer, for what it wrote after the last read. Then no more.
        m.update(Action::TaskSetState { id: 3, state: State::Done });
        assert_eq!(ids(&m), ["s2", "s1", "s3"]);
        m.update(Action::Tick { now: 1_000_000 + progress::LAST_READ_MS + 1 });
        assert_eq!(ids(&m), ["s2", "s1"]);
    }

    #[test]
    fn a_tasks_time_and_tokens_come_from_its_sessions_work() {
        const UUID: &str = "8f14e45f-ceea-467f-a8d3-0242ac130003";
        let mut m = Model::default();
        m.update(Action::Tick { now: 5_000 });
        filed(&mut m, &[("ship it", Some("web"), State::Captured)]);
        let link = sessions::Link { runner: "claude".into(), id: UUID.into(), state: None };
        m.tasks.link(1, link);
        let tokens =
            |model: &str, sub, input| progress::Tokens { model: model.into(), sub, input, output: 2, cached: 1 };
        let work = |session: &str, ms, day, day_ms, rows| progress::Work {
            runner: "claude".into(),
            session: session.into(),
            clock: progress::Clock { ms, last: None, day, day_ms },
            tokens: rows,
            context: Some(50_000),
            window: Some(200_000),
        };
        // Another session's work, or a runner not listed: no task takes it.
        m.update(Action::SessionWork { work: work("other", 9, 0, 0, Vec::new()), cwd: None });
        assert!(m.tasks.list[0].work.is_empty());
        let rows = vec![tokens("claude-opus-5-5", false, 10), tokens("claude-haiku-5", true, 4)];
        m.update(Action::SessionWork { work: work(UUID, 60_000, 0, 0, rows.clone()), cwd: None });
        // Read again: it replaces what was kept of that session, it does not add to it.
        m.update(Action::SessionWork { work: work(UUID, 90_000, 1_000, 30_000, rows), cwd: None });
        let task = &m.tasks.list[0];
        assert_eq!(
            (task.work.len(), task.work[0].clock.ms, task.work[0].tokens[0].model.as_str()),
            (1, 90_000, "opus-5.5")
        );
        // It started when its agent did; it is finished when it is done, and not when reopened.
        m.tasks.started(1, Some(4_000));
        m.update(Action::Tick { now: 7_000 });
        m.update(Action::TaskSetState { id: 1, state: State::Done });
        assert_eq!(m.tasks.list[0].finished_at, Some(7_000));
        // The footer: what was done since the day began, what runs, and today's time at work.
        assert_eq!(m.today(1_000).line(), "1 done · 0 running · 30s");
        assert_eq!(m.today(8_000), Today { done: 0, running: 0, agent_ms: 0 });
        // The card: its state, tags, times, workspace and tokens.
        let card = m.card(1, 4_000 + 3 * 3_600_000).unwrap();
        assert_eq!(
            (card.state, card.tags.as_slice(), card.started.as_deref()),
            ("Done", &["#web".to_string()][..], Some("3h"))
        );
        assert_eq!((card.agent_time.as_str(), card.workspace.as_str()), ("1m", "0 tabs · 0 panes"));
        // Counts the row no longer shows: of paths, skills, references and captures it has.
        (m.tasks.list[0].paths, m.tasks.list[0].materials) = (vec!["a".into(), "b".into()], vec!["c".into()]);
        assert_eq!(m.card(1, 0).unwrap().tags, ["#web", "2 paths", "1 capture"]);
        let table: Vec<_> = card.tokens.iter().map(|t| (t.model.as_str(), t.sub, t.input)).collect();
        assert_eq!(table, [("opus-5.5", false, 10), ("haiku-5", true, 4)]);
        assert_eq!((card.context, card.window), (Some(50_000), Some(200_000)));
        m.update(Action::TaskSetState { id: 1, state: State::Running });
        assert_eq!(m.tasks.list[0].finished_at, None);
        // A key this build does not know is written back as it was.
        let text = r#"{"id":1,"title":"t","state":"done","workspace":{"tabs":[1]}}"#;
        let read: Task = serde_json::from_str(text).unwrap();
        assert!(serde_json::to_string(&read).unwrap().contains(r#""workspace":{"tabs":[1]}"#));
    }

    #[test]
    fn a_collapsed_heading_keeps_its_count_and_hides_its_rows() {
        let mut m = Model::default();
        for (title, state) in [("a", State::NeedsYou), ("b", State::NeedsYou), ("c", State::Running)] {
            m.update(Action::TaskAdd { title: title.into(), priority: 2, state, tab: None, assign: Assign::default() });
        }
        m.update(Action::ToggleSection { section: Section::Tasks });
        m.update(Action::FocusList);
        m.update(Action::ListMove { delta: 1 }); // on "b"
        m.update(Action::ToggleGroup { heading: Heading::Running });
        assert_eq!(sections(&m), [(Heading::NeedsYou, 2, vec![1, 2]), (Heading::Running, 1, vec![])]);
        let (heading, task) = (ListRow::Heading, ListRow::Task);
        let (needs, running) = (heading(Heading::NeedsYou), heading(Heading::Running));
        assert_eq!(
            (m.list_rows(), m.list),
            (vec![needs.clone(), task(1), task(2), running.clone()], Some(2)),
            "it stays"
        );
        // The selected row's own heading: the selection goes to a row that is still drawn.
        m.update(Action::ToggleGroup { heading: Heading::Running });
        m.update(Action::ToggleGroup { heading: Heading::NeedsYou });
        assert_eq!(
            (m.list_rows(), m.list, m.collapsed.as_slice()),
            (
                vec![needs.clone(), running.clone(), task(3)],
                Some(2),
                &[Heading::Done, Heading::Sessions, Heading::NeedsYou][..]
            )
        );
        // All folded is no dead end: a heading is a row, and ↵ on it unfolds it. The selection stays on it.
        m.update(Action::ToggleGroup { heading: Heading::Running });
        assert_eq!((m.list_rows(), m.list), (vec![needs.clone(), running.clone()], Some(1)));
        assert_eq!(m.update(Action::ListChoose { axis: Right }), []);
        assert_eq!(
            (m.list_rows(), m.list, m.mode()),
            (vec![needs.clone(), running.clone(), task(3)], Some(1), Mode::List)
        );
        m.update(Action::ListChoose { axis: Right });
        assert_eq!(m.collapsed.as_slice(), &[Heading::Done, Heading::Sessions, Heading::NeedsYou, Heading::Running]);
        m.update(Action::ToggleGroup { heading: Heading::NeedsYou });
        assert_eq!((sections(&m)[0].2.len(), m.collapsed.len()), (2, 3));
    }

    #[test]
    fn other_sessions_start_folded_and_list_mode_skips_their_rows() {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: listed() });
        m.update(Action::Tick { now: 5_000 });
        m.update(Action::SetSessions { found: vec![session("claude", "busy", "/code/app", true, 5_000)], day: 0 });
        m.update(Action::ToggleSection { section: Section::Tasks });
        // At work, and still folded: the heading counts it, list mode has the heading alone.
        let bar = m.sessions_bar();
        assert_eq!((bar.count, bar.collapsed, bar.rows.len()), (1, true, 0));
        assert_eq!(m.list_rows(), [ListRow::Heading(Heading::Sessions)]);
        assert_eq!(Heading::Sessions.title(), "Elsewhere");
        // ↵ on the heading unfolds it, as any other.
        m.update(Action::FocusList);
        m.update(Action::ListChoose { axis: Right });
        assert_eq!(m.list_rows()[1], ListRow::Session("claude".into(), "busy".into()));
    }

    fn session(runner: &str, id: &str, cwd: &str, active: bool, at: u64) -> Found {
        let (runner, id, cwd, repo) = (runner.to_string(), id.to_string(), cwd.to_string(), cwd.to_string());
        let (station, label, title, model, held) = (None, None, None, None, false);
        let (started, last_activity) = (None, Some(at));
        Found { runner, id, cwd, repo, started, last_activity, active, station, label, title, model, held }
    }

    /// The Elsewhere group as (count in range, ids of the rows drawn, count in all).
    fn session_rows(m: &Model) -> (usize, Vec<String>, usize) {
        let bar = m.sessions_bar();
        (bar.count, bar.rows.into_iter().map(|row| row.id).collect(), bar.total)
    }

    #[test]
    fn sessions_that_are_no_tasks_are_listed_active_first_and_in_their_range() {
        let mut m = Model::default();
        m.update(Action::ToggleGroup { heading: Heading::Sessions }); // folded at first
        m.update(Action::SetRepos { repos: listed() });
        // 10 days in; the local day started 5 hours ago.
        let (now, hour) = (10 * sessions::DAY_MS, 3_600_000);
        m.update(Action::Tick { now });
        let mut busy = session("claude", "busy", "/code/app/crates", true, now - 2_000);
        (busy.repo, busy.station, busy.label) = ("/code/app".into(), Some("shell".into()), Some("cargo test".into()));
        m.update(Action::SetSessions {
            found: vec![
                session("codex", "old", "/code/app", false, now - 3 * sessions::DAY_MS),
                session("codex", "idle", "/code/app-2", false, now - 3 * hour),
                busy,
            ],
            day: now - 5 * hour,
        });
        // 7 days, at first; Today: the one at work and the one idle since the day started.
        assert_eq!(session_rows(&m), (3, vec!["busy".into(), "idle".into(), "old".into()], 3));
        m.update(Action::SessionsRange { range: sessions::Range::Today });
        assert_eq!(session_rows(&m), (2, vec!["busy".into(), "idle".into()], 3));
        let rows = m.sessions_bar().rows;
        // Named after the listed repository or worktree, wherever below it the session started.
        assert_eq!(
            (
                rows[0].runner.as_str(),
                rows[0].name.as_str(),
                rows[0].active,
                rows[0].doing.as_deref(),
                rows[0].age.as_deref()
            ),
            ("claude", "app", true, Some("shell · cargo test"), Some("now"))
        );
        assert_eq!(
            (
                rows[1].runner.as_str(),
                rows[1].name.as_str(),
                rows[1].active,
                rows[1].doing.as_deref(),
                rows[1].age.as_deref()
            ),
            ("codex", "app-2", false, None, Some("3h"))
        );
        // 7 days takes in the one of three days ago. A range is read, never written.
        let week = Action::SessionsRange { range: sessions::Range::Week };
        assert_eq!(m.update(week.clone().sent_by(Origin::Socket)), []);
        assert_eq!(session_rows(&m), (3, vec!["busy".into(), "idle".into(), "old".into()], 3));
        assert_eq!(m.update(week.sent_by(Origin::User)), []);
        // The heading folds like any other.
        m.update(Action::ToggleGroup { heading: Heading::Sessions });
        assert_eq!(session_rows(&m), (3, vec![], 3));
        m.update(Action::ToggleGroup { heading: Heading::Sessions });
        // List mode walks the tasks, then the sessions as drawn: their heading, the rows.
        m.update(Action::TaskAdd {
            title: "a".into(),
            priority: 2,
            state: State::Captured,
            tab: None,
            assign: Assign::default(),
        });
        m.update(Action::ToggleSection { section: Section::Tasks });
        let row = |id: &str, runner: &str| ListRow::Session(runner.into(), id.into());
        let tasks = [ListRow::Heading(Heading::Later), ListRow::Task(1), ListRow::Heading(Heading::Sessions)];
        let sessions = [row("busy", "claude"), row("idle", "codex"), row("old", "codex")];
        assert_eq!(m.list_rows(), [&tasks[..], &sessions[..]].concat());
        // ↵ on the heading folds the group. None in range: the heading stays, to widen it again.
        m.update(Action::FocusList);
        m.update(Action::ListMove { delta: 1 });
        m.update(Action::ListChoose { axis: Right });
        assert_eq!((m.list_rows(), m.list), (tasks.to_vec(), Some(2)));
        m.update(Action::ListChoose { axis: Right });
        m.update(Action::LeaveList);
        m.update(Action::Tick { now: now + 9 * sessions::DAY_MS });
        m.update(Action::SetSessions { found: vec![session("codex", "old", "/code/app", false, 0)], day: now });
        assert_eq!((session_rows(&m), m.list_rows().len()), ((0, vec![], 1), 3));
        // Hidden: gone for this run, whatever the shell finds again. The group goes with its last row.
        m.update(Action::SessionHide { runner: "codex".into(), id: "old".into() });
        m.update(Action::SetSessions { found: vec![session("codex", "old", "/code/app", true, now)], day: 0 });
        assert_eq!(session_rows(&m), (0, vec![], 0));
    }

    #[test]
    fn a_sessions_title_and_model_are_in_its_row_and_in_no_task() {
        let mut m = Model::default();
        m.update(Action::ToggleGroup { heading: Heading::Sessions }); // folded at first
        m.update(Action::SetRepos { repos: listed() });
        m.update(Action::Tick { now: 5_000 });
        let mut titled = session("claude", "s1", "/code/app", false, 4_000);
        titled.title = Some("Rename it #urgent >app-2 @codex p0\nand run this".into());
        titled.model = Some("claude-opus-4-7[1m]".into());
        m.update(Action::SetSessions {
            found: vec![titled, session("codex", "s2", "/code/app", false, 1_000)],
            day: 0,
        });
        let rows = m.sessions_bar().rows;
        let shown = |row: &sessions::Row| (row.quoted_title.clone(), row.model.clone());
        assert_eq!(shown(&rows[0]), (Some("Rename it #urgent >app-2 @codex p0".into()), Some("opus-4.7".into())));
        assert_eq!(shown(&rows[1]), (None, None));
        // Adopted, the task is named after the repository as ever: the title names nothing, and
        // its words are no tags.
        m.update(Action::SessionAdopt { runner: "claude".into(), id: "s1".into() });
        let task = m.tasks.list[0].clone();
        assert_eq!((task.title.as_str(), task.project.as_deref()), ("app", None));
        assert_eq!((task.repo.as_deref(), task.agent.as_deref()), (Some("/code/app"), Some("claude")));
        assert!(!serde_json::to_string(&m.tasks).unwrap().contains("Rename it"));
    }

    /// Sessions of the listed checkouts, for the conversation tests: `idle` started below its
    /// repository, `busy` at work, `held` idle with a live process, `astray` left the checkout,
    /// `plain` with an id that is no UUID.
    fn conversations() -> Model {
        let mut m = Model::default();
        m.update(Action::SetRepos { repos: listed() });
        m.update(Action::ToggleSection { section: Section::Tasks });
        m.update(Action::Tick { now: 9_000_000 });
        let below = |runner: &str, id: &str, cwd: &str| Found {
            repo: "/code/app".into(),
            ..session(runner, id, cwd, false, 1_000)
        };
        let found = vec![
            Found { title: Some("Fix the login".into()), ..below("claude", IDLE, "/code/app/crates/core") },
            session("codex", BUSY, "/code/app-2", true, 9_000_000),
            Found { held: true, ..session("claude", HELD, "/code/app", false, 2_000) },
            below("claude", ASTRAY, "/code/app/../other"),
            session("claude", "plain", "/code/app", false, 500),
        ];
        m.update(Action::SetSessions { found, day: 0 });
        m
    }

    const IDLE: &str = "8f14e45f-ceea-467f-a8d3-0242ac130001";
    const BUSY: &str = "8f14e45f-ceea-467f-a8d3-0242ac130002";
    const HELD: &str = "8f14e45f-ceea-467f-a8d3-0242ac130003";
    const ASTRAY: &str = "8f14e45f-ceea-467f-a8d3-0242ac130004";

    fn of_session(runner: &str, id: &str) -> Subject {
        Subject::Session { runner: runner.into(), id: id.into() }
    }

    /// `claude --resume <id>` (or Codex's) for `subject`, in `cwd`.
    fn resumed(subject: Subject, runner: &str, id: &str, cwd: &str) -> Effect {
        let start = agents::Start::Resume { runner: RunnerId::named(runner).unwrap(), session: id.into() };
        Effect::StartAgent { task: subject, start, cwd: Some(cwd.into()), brief: None, command: None }
    }

    /// A session's space: no task, so nothing in front; ⌘⌥] / ⌘⌥[ still reach the transcript.
    #[test]
    fn in_a_sessions_space_the_rail_keys_start_from_the_top_or_the_foot() {
        use crate::model::rail::RailItem;
        let mut m = conversations();
        m.update(Action::Split { axis: Axis::Right, kind: Kind::Terminal });
        m.update(Action::ListenFixture.sent_by(Origin::System));
        m.update(Action::SessionOpen { runner: "claude".into(), id: IDLE.into() });
        assert_eq!((m.rail(), m.rail_selected(), m.drawer_collapsed()), (vec![RailItem::Transcript], None, false));
        m.update(Action::TalkCycle { delta: 1 });
        assert_eq!(m.rail_selected(), Some(RailItem::Transcript));
        m.listen.shown = false;
        m.update(Action::TalkCycle { delta: -1 });
        assert_eq!(m.rail_selected(), Some(RailItem::Transcript));
    }

    /// A session another terminal holds is watched, read-only: what it did, no card, no turn;
    /// once idle it may be taken over, by the user's click.
    #[test]
    fn a_session_held_elsewhere_is_watched_and_taken_over_once_idle() {
        use crate::transcript::{Event, Text};
        let mut m = conversations();
        let held = of_session("claude", HELD);
        assert_eq!(started(&mut m, Action::SessionOpen { runner: "claude".into(), id: HELD.into() }), []);
        assert_eq!(m.watch_target().map(|(subject, ..)| subject), Some(held.clone()));
        assert!(!m.take_over_ready(&held));
        let tool = Event::ToolStart {
            id: "a".into(),
            sub: false,
            tool: "Bash".into(),
            station: crate::activity::Station::Shell,
            label: "git".into(),
            detail: Text::default(),
            diff: None,
            gist: None,
        };
        let card = Event::Permission {
            ticket: 1,
            tool: "Bash".into(),
            label: "rm".into(),
            detail: Text::default(),
            len: 0,
            cut: false,
            claim: Text::default(),
            questions: Vec::new(),
        };
        let events = Action::AgentEvents { task: held.clone(), events: vec![Event::TurnStarted, tool, card], at: 1 };
        assert!(m.update(events.clone().sent_by(Origin::Socket)).is_empty() && m.chat(&held).is_none());
        m.update(events.sent_by(Origin::System));
        let t = &m.chat(&held).expect("a watched transcript").transcript;
        assert!(t.watched && !t.live && t.turn.is_none() && t.cards.is_empty(), "{t:?}");
        assert_eq!(t.items().len(), 1);
        // Watched again, the file is read from its start: what it shows once, not twice.
        let again = vec![
            Event::WatchFromStart,
            Event::ToolStart {
                id: "a".into(),
                sub: false,
                tool: "Bash".into(),
                station: crate::activity::Station::Shell,
                label: "git".into(),
                detail: Text::default(),
                diff: None,
                gist: None,
            },
        ];
        m.update(Action::AgentEvents { task: held.clone(), events: again, at: 2 }.sent_by(Origin::System));
        assert_eq!(m.chat(&held).map(|chat| chat.transcript.items().len()), Some(1));
        // Idle and no longer held: no more watching, and Take over (the user's open) goes on with it.
        let free = Found { repo: "/code/app".into(), ..session("claude", HELD, "/code/app", false, 2_000) };
        m.update(Action::SetSessions { found: vec![free], day: 0 });
        assert!(m.watch_target().is_none() && m.take_over_ready(&held));
        let took = started(&mut m, Action::SessionOpen { runner: "claude".into(), id: HELD.into() });
        assert!(matches!(&took[..], [Effect::StartAgent { start: agents::Start::Resume { .. }, .. }]), "{took:?}");
    }

    #[test]
    fn opening_a_session_goes_on_with_it_in_the_drawer_where_it_started() {
        let mut m = conversations();
        let open = |m: &mut Model, runner: &str, id: &str| {
            started(m, Action::SessionOpen { runner: runner.into(), id: id.into() })
        };
        let idle = of_session("claude", IDLE);
        // Gone on with in the folder it started in, below the repository: `claude --resume`
        // finds a session by its directory. No task, no pane: its space, one empty tab.
        assert_eq!(open(&mut m, "claude", IDLE), [resumed(idle.clone(), "claude", IDLE, "/code/app/crates/core")]);
        assert_eq!((m.tasks.list.len(), m.panes.len(), m.tabs.len(), m.mode()), (0, 0, 2, Mode::Talk));
        assert_eq!(m.talk, Some(Talk { task: idle.clone(), open: true, keys: true }));
        // Once: a second open, before the shell says it started and after, starts nothing.
        assert_eq!(open(&mut m, "claude", IDLE), []);
        m.update(Action::AgentStarted { task: idle.clone(), session: None, at: 1 }.sent_by(Origin::System));
        assert_eq!((open(&mut m, "claude", IDLE), m.agents.clone()), (vec![], vec![idle.clone()]));
        // Its own space on the top row, as a task's; it is at work only while its file says so.
        assert_eq!(m.space(), &Owner::of(&idle));
        assert!(!m.talk_working(&idle));
        // Stop ends it; a click goes on with it again.
        assert_eq!(m.update(Action::TaskStop { id: idle.clone() }), [Effect::StopAgent { task: idle.clone() }]);
        m.update(Action::AgentExited { task: idle.clone() }.sent_by(Origin::System));
        assert_eq!(open(&mut m, "claude", IDLE).len(), 1);
        // At work elsewhere, or idle and held by a live process: the drawer says so, and no
        // second program is started on it.
        for (runner, id) in [("codex", BUSY), ("claude", HELD)] {
            assert_eq!(open(&mut m, runner, id), [], "{id}");
            assert_eq!(m.talk.as_ref().map(|talk| (&talk.task, talk.keys)), Some((&of_session(runner, id), false)));
            let note = m.talk_note().unwrap_or_default();
            assert_eq!(note, "its session is live in another terminal: go on with it there");
        }
        // Out of the listed checkout, or an id no command is built from: nothing started, and the
        // drawer says why.
        for (id, why) in [
            (ASTRAY, "it started in other, outside the listed repositories"),
            ("plain", "its session id is not one Claude Code can resume"),
        ] {
            assert_eq!(open(&mut m, "claude", id), [], "{id}");
            assert_eq!(m.talk_note().as_deref(), Some(why));
        }
        // Never read: nothing opens.
        let before = m.talk.clone();
        assert_eq!(open(&mut m, "claude", "nope"), []);
        assert_eq!(m.talk, before);
    }

    /// The Tasks section closed after a session's conversation opened: nothing is listed, so the
    /// session is read for the resume, as a task's is, and gone on with where it started.
    #[test]
    fn a_session_opened_before_the_section_closed_is_read_and_gone_on_with() {
        let closed = || {
            let mut m = conversations();
            m.update(Action::SessionOpen { runner: "claude".into(), id: IDLE.into() });
            m.update(Action::SessionsAtWork { found: Vec::new() }.sent_by(Origin::System));
            let idle = of_session("claude", IDLE);
            // No dead end: Resume session shows, and nothing says it cannot.
            assert_eq!((m.talk_note(), m.talk_resumes(), m.take_over_ready(&idle)), (None, Some(true), true));
            let read = Effect::ReadSession { runner: "claude".into(), id: IDLE.into() };
            assert_eq!(m.update(Action::TalkStart), [read]);
            assert!(m.talk_live(&idle) && m.talk_note().is_none());
            m
        };
        let read = |found: Option<Found>| Action::SessionRead { runner: "claude".into(), id: IDLE.into(), found };
        let below = Found { repo: "/code/app".into(), ..session("claude", IDLE, "/code/app/crates/core", false, 1) };
        let mut m = closed();
        let resumes = [resumed(of_session("claude", IDLE), "claude", IDLE, "/code/app/crates/core")];
        assert_eq!(m.update(read(Some(below.clone())).sent_by(Origin::System)), resumes);
        // No listed checkout has it now: nothing started, and the drawer says why.
        let mut m = closed();
        assert_eq!(m.update(read(None).sent_by(Origin::System)), []);
        let note = m.talk_note();
        assert_eq!(note.as_deref(), Some("its session file is in no listed repository now: gone, or moved"));
        // Held by a live process as it is read: live there.
        let mut m = closed();
        assert_eq!(m.update(read(Some(Found { held: true, ..below })).sent_by(Origin::System)), []);
        assert!(m.talk_note().is_some_and(|note| note.contains("live in another terminal")));
        // Never opened: a session not listed still opens nothing.
        let mut m = conversations();
        m.update(Action::SessionsAtWork { found: Vec::new() }.sent_by(Origin::System));
        assert_eq!(m.update(Action::SessionOpen { runner: "claude".into(), id: IDLE.into() }), []);
        assert_eq!(m.talk, None);
    }

    /// Hiding a session only takes it out of Elsewhere: its tab, already open, still goes on with
    /// it (Resume and Take over). Nothing unhides it: it stays out of the list after.
    #[test]
    fn a_hidden_sessions_open_tab_still_goes_on_with_it() {
        let mut m = conversations();
        let idle = of_session("claude", IDLE);
        m.update(Action::SessionOpen { runner: "claude".into(), id: IDLE.into() });
        m.update(Action::SessionHide { runner: "claude".into(), id: IDLE.into() });
        assert!(!m.sessions_bar().rows.iter().any(|row| row.id == IDLE));
        assert_eq!((m.talk_note(), m.talk_resumes(), m.take_over_ready(&idle)), (None, Some(true), true));
        let resumes = [resumed(idle.clone(), "claude", IDLE, "/code/app/crates/core")];
        assert_eq!(m.update(Action::TalkStart), resumes);
        m.update(Action::AgentStarted { task: idle.clone(), session: None, at: 1 }.sent_by(Origin::System));
        let found = m.found.iter().map(|s| Found { active: s.id == IDLE, ..s.clone() }).collect();
        m.update(Action::SetSessions { found, day: 0 }.sent_by(Origin::System));
        assert!(!m.sessions_bar().rows.iter().any(|row| row.id == IDLE), "still hidden");
        // Closed and reopened from its tab, unlisted too: read first, then gone on with.
        m.update(Action::TaskStop { id: idle.clone() });
        m.update(Action::AgentExited { task: idle.clone() }.sent_by(Origin::System));
        m.update(Action::SessionsAtWork { found: Vec::new() }.sent_by(Origin::System));
        let read = Effect::ReadSession { runner: "claude".into(), id: IDLE.into() };
        assert_eq!(m.update(Action::TalkStart), [read]);
    }

    /// Our own agent just stopped: what its session's file shows (written lately, a process
    /// recorded for it) is ours, and reopening goes on with it at once.
    #[test]
    fn a_session_whose_agent_we_stopped_is_not_live_elsewhere() {
        let mut m = conversations();
        let idle = of_session("claude", IDLE);
        let system = |m: &mut Model, action: Action| m.update(action.sent_by(Origin::System));
        let open = Action::SessionOpen { runner: "claude".into(), id: IDLE.into() };
        let listed = |m: &mut Model, last: u64, held: bool| {
            let found = m.found.iter().map(|s| match s.id == IDLE {
                true => Found { active: true, held, last_activity: Some(last), ..s.clone() },
                false => s.clone(),
            });
            let found = found.collect();
            system(m, Action::SetSessions { found, day: 0 });
        };
        let now = 9_000_000;
        started(&mut m, open.clone());
        system(&mut m, Action::AgentStarted { task: idle.clone(), session: None, at: now });
        // It wrote while it ran, and Claude Code recorded its process.
        listed(&mut m, now + 4_000, true);
        system(&mut m, Action::Tick { now: now + 5_000 });
        m.update(Action::TaskStop { id: idle.clone() });
        system(&mut m, Action::AgentExited { task: idle.clone() });
        // Read again within the 30 s after which a session reads idle: still "at work".
        listed(&mut m, now + 5_500, false);
        assert_eq!(m.talk_note(), None);
        let resumes = [resumed(idle.clone(), "claude", IDLE, "/code/app/crates/core")];
        assert_eq!(started(&mut m, open.clone()), resumes);
        system(&mut m, Action::AgentExited { task: idle.clone() });
        // Written to since it ended, by another terminal: live there.
        listed(&mut m, now + 30_000, true);
        assert_eq!(m.update(open.clone()), []);
        assert!(m.talk_note().is_some_and(|note| note.contains("live in another terminal")));

        // A task's the same: its agent stopped, the stale record of its process is ours.
        let stopped = || {
            let mut m = conversations();
            m.update(Action::SessionAdopt { runner: "claude".into(), id: IDLE.into() });
            system(&mut m, Action::AgentStarted { task: Subject::Task(1), session: None, at: now });
            listed(&mut m, now, true);
            m.update(Action::TaskStop { id: Subject::Task(1) });
            system(&mut m, Action::AgentExited { task: Subject::Task(1) });
            // A read in flight when it stopped says the session is at work: the task is not moved by it.
            listed(&mut m, now, true);
            m
        };
        let mut m = stopped();
        assert_eq!(m.tasks.get(1).map(|task| task.state), Some(State::NeedsYou));
        assert_eq!(m.talk_note(), None);
        let resumes = [resumed(Subject::Task(1), "claude", IDLE, "/code/app/crates/core")];
        assert_eq!(started(&mut m, Action::TaskTalk { id: 1 }), resumes);
        // Two rounds on, a listing that records a process for it is believed.
        let mut m = stopped();
        system(&mut m, Action::Tick { now: now + ENDED_HELD_MS + 1 });
        listed(&mut m, now, true);
        assert_eq!(started(&mut m, Action::TaskTalk { id: 1 }), []);
        // A read made for the resume came after it stopped: a process it records is another's.
        let mut m = stopped();
        system(&mut m, Action::SetSessions { found: Vec::new(), day: 0 });
        assert_eq!(started(&mut m, Action::TaskTalk { id: 1 }).len(), 1);
        let held = Found { held: true, repo: "/code/app".into(), ..session("claude", IDLE, "/code/app", false, now) };
        let read = Action::SessionRead { runner: "claude".into(), id: IDLE.into(), found: Some(held) };
        assert_eq!(system(&mut m, read), []);
        assert!(m.talk_note().is_some_and(|note| note.contains("live in another terminal")));
    }

    /// An adopted session gone on with in the drawer: its task runs at once, as on a new start.
    #[test]
    fn a_task_gone_on_with_runs_at_once() {
        let mut m = conversations();
        m.update(Action::SessionAdopt { runner: "claude".into(), id: IDLE.into() }.sent_by(Origin::Socket));
        assert_eq!(m.tasks.get(1).map(|task| task.state), Some(State::Captured));
        assert_eq!(started(&mut m, Action::TaskTalk { id: 1 }).len(), 1);
        m.update(Action::AgentStarted { task: Subject::Task(1), session: None, at: 1 }.sent_by(Origin::System));
        let task = m.tasks.get(1).expect("the task");
        assert_eq!(
            (task.state, task.session.as_ref().and_then(|link| link.state)),
            (State::Running, Some(State::Running))
        );
        // Its agent gone: the user's to look at.
        m.update(Action::AgentExited { task: Subject::Task(1) }.sent_by(Origin::System));
        assert_eq!(m.tasks.get(1).map(|task| task.state), Some(State::NeedsYou));
    }

    /// The owner: "i'd like to run 'ja claude' instead of 'claude'". `agent_commands` goes with
    /// each start of its runner's agent, new or gone on with, read again at once; never in the state.
    #[test]
    fn a_runners_command_goes_with_each_start_of_it_and_never_into_the_state() {
        const MINE: &str = "TOKEN=made-up-secret claude";
        let mut m = conversations();
        let read = |m: &mut Model, text: String| {
            m.update(Action::SettingsRead { text, written: false }.sent_by(Origin::System));
        };
        read(&mut m, serde_json::json!({"agent_commands": {"claude": MINE}}).to_string());
        let command = |effects: Vec<Effect>| match &effects[..] {
            [Effect::StartAgent { command, .. }] => command.clone(),
            _ => panic!("{effects:?}"),
        };
        let names = compose::Names { agents: vec!["codex".into()], skills: Vec::new() };
        let known = compose::Known { names, ..Default::default() };
        let line = |line: &str| Action::TaskFromLine { line: line.into(), known: known.clone(), open: false };
        m.update(line("mine"));
        m.update(line("theirs @codex"));
        assert_eq!(command(started(&mut m, Action::TaskTalk { id: 1 })), Some(MINE.into()));
        // Another runner's start: its own program.
        assert_eq!(command(started(&mut m, Action::TaskTalk { id: 2 })), None);
        // A listed session gone on with: the same command.
        let open = Action::SessionOpen { runner: "claude".into(), id: IDLE.into() };
        assert_eq!(command(started(&mut m, open)), Some(MINE.into()));
        let state = serde_json::to_string(&m).unwrap();
        assert!(!state.contains("made-up-secret") && !state.contains("agent_commands"), "{state}");
        // Taken out of the file: the program again, with no restart.
        read(&mut m, "{}".into());
        m.update(line("again"));
        assert_eq!(command(started(&mut m, Action::TaskTalk { id: 3 })), None);
        // At start, a wrong key elsewhere does not undo it; a wrong file later keeps the last good.
        let mut m = Model::default();
        read(&mut m, serde_json::json!({"agent_commands": {"claude": MINE}, "typo": true}).to_string());
        m.update(line("first"));
        assert_eq!(command(started(&mut m, Action::TaskTalk { id: 1 })), Some(MINE.into()));
        read(&mut m, "{,}".into());
        m.update(line("second"));
        assert_eq!(command(started(&mut m, Action::TaskTalk { id: 2 })), Some(MINE.into()));
    }

    /// The Tasks section closed: a session's conversation keeps the name and badge it had.
